apps/next/src/view/toolBox/Tool/video/ed:
"use client";

// 节目画布只适配单个片段：真实媒体在裁切层，操作选框在独立交互层。
import { useEffect, useRef, type CSSProperties, type PointerEvent, type ReactNode } from "react";
import { useTranslation } from "@/i18n";
import { defaultTransform, fittedSize, type ClipTransform } from "./clip-transform-model";
import type { EditorMediaAsset, EditorPreviewClip, EditorPreviewProject } from "./editor-panels";
import styles from "./editor.module.css";

// 外层仍拥有工程确认值；组件只把拖动意图回报，不另存一份片段工程。
// preview传完整候选用于即时画面与X/Y联动，commit只在松手时真正写工程。
// cancel扔掉候选，确认值没有被改过，所以Escape不需要执行反向移动命令。
// select只选画布对应实例，不定位时间，也不选择素材库中的原文件。
// locked拒绝开始与提交，selected只决定选框显示，不能决定叠放优先级。
// 当前只有一个媒体层，没有通过提高选中z-index冒充多轨合成。
export interface CanvasEdit {
  selected: boolean; locked: boolean; value: ClipTransform;
  select: () => void; preview: (value: ClipTransform | null) => void; commit: (value: ClipTransform) => void;
}
// 组件children是已经挂载的真实媒体内容，父层控制src和解码，不在画布层重建播放器。
// 可选edit意味着只读渲染仍可采用同一构图几何，静态图片样板无需复制CSS矩阵。
// 源查看不使用该层，保持原始contain预览，不将工程参数应用到素材原件。
// project提供像素尺和宽高比；clip提供身份与确认变换；asset提供源的基础尺寸。
// 这三类数据分别来自项目、安排、素材，不能把它们合成一个可随意改写的大对象。
// clip.id决定生命周期，同源不同安排切换时旧手势必须结束。
// 操作按钮是独立覆盖层，所以播放器不会因为指针焦点而变成可编辑输入框。
// plane只拆分绘制与操作职责，三种模式仍使用唯一canvasStyle和手势换算。
// 默认all保留静态图片样板调用，不要求旧调用方重新装配两层。
// picture用于合成内容栈，不生成能抢指针的操作按钮。
// operations用于独立操作栈，不渲染video或img，因此不会重复解码。
// 两个平面读取同一个edit.value，属性草稿不会使选框和画面落在不同位置。
// 两者的测量框均铺满项目frame，换算不包含标题和播放器控制栏。
// 内容裁切与操作提示分离，选框越过项目边界时仍可辨认。
// 锁层按钮不参与鼠标命中，继续显示内容，但不能拦截下方可编辑片段。
// 锁层从键盘Tab路径排除，时间线仍可以明确访问其身份。
// 透明度零时指针放行，用户可从时间线恢复该片段透明度。
// plane不是业务类型开关，素材查看不调用画布操作适配器。
// 操作标记与内容标记分开，自动回归不会把两个平面误数成两份媒体。
// 既有指针捕获、Escape和窗口resize取消机制继续统一使用。
// 位置数据仍是项目像素中心，拆平面不能把它改为DOM左上角。
// 选中状态仅产生细边框，不给内容提高层级。
interface CanvasProps { clip: EditorPreviewClip; asset: EditorMediaAsset; project: EditorPreviewProject; edit?: CanvasEdit; children?: ReactNode; plane?: "all" | "picture" | "operations"; }
// 复用同一手势对象保留按下时的原变换与抓取位置，不能每次move累加屏幕误差。
// 两平面读取同一项目尺寸，因此窗口缩放不会使画面和操作层使用不同坐标原点。
// 拖动取消时只丢弃候选，不提交反向位移来假装恢复。
// 锁在拖动中改变会触发既有取消，松手不能把锁前候选写回确认值。
// 操作层卸载同样释放pointer capture，不留下全局鼠标监听。
// 画面平面没有edit按钮，却继续读取草稿value，因此直接拖动时真实帧同步移动。
// 图片静态样板使用默认all，所以旧调用无需知道多视频合成的分层装配细节。
// 键盘焦点只进入可编辑操作目标，锁定与隐藏内容不抢快捷键。
// 透明层不参与鼠标拾取，但它的时间线ID仍有效，不等于从工程删除。
// 当前没有自由变形手柄，plane参数不能被误读成缩放手柄已实现。
interface CanvasGesture { pointer: number; element: HTMLElement; x: number; y: number; factorX: number; factorY: number; origin: ClipTransform; candidate: ClipTransform; }

// 百分比只从项目坐标计算，因此窗口宽度变化不会改写X/Y确认值。
// 如960项目像素在1920工程中总是50%，画布缩成600px也仍在正中央。
// 基础尺寸只contain源画面一次；scale再乘在基础宽高上，避免contain叠两次。
// 旋转绕自身中心，位置仍是项目坐标中的中心，不能用旋转后包围盒反推X/Y。
// 透明度只用于真实内容层，操作边框保持可见，零透明也能找回当前选中对象。
// 不读取DOM尺寸来推导数据，屏幕比例仅在手势开始时用于反算位移。
// CSS中的left/top指向内容盒中心所在的项目百分比，再用translate移回半个盒宽高。
// translate(-50%,-50%)使用自身大小，不能改成项目的一半或窗口的一半。
// rotate与均匀缩放顺序不会改变中心，但非等比变形不在本轮契约内。
// 这里把scale乘进宽高而不再加CSS scale，避免真实内容放大两次。
// 旋转后的命中包围盒由浏览器计算，不能拿它反推基础适配宽高。
// 元数据存在时优先真实显示尺寸；静态图片可使用StaticImageData的原始宽高。
// 字符串封面没有可信尺寸时采用项目比例安全回退，不能解析URL猜源宽高。
// 图片导入尚未接通，静态图片渲染边界与正式真实视频回归分开报告。
// 不透明度不放进通用style结果，因为相同几何也要给可见操作层复用。
// 内容opacity为0时选框仍可见，用户能通过属性把透明画面恢复。
// 选框细线不占布局宽度，不会把百分比坐标挤成另一个实际中心。
// CSS transform-origin固定center，旋转不会让位置参数变成左上角坐标。
// 按百分比渲染能自然跟随窗口与分隔条尺寸变化，不额外监听DPR改数据。
// 项目像素与CSS像素不混用，也不根据getBoundingClientRect结果重写transform。
// 镜像只应用到实际内容层的scaleX，位置选框不改变项目坐标方向。
// 旋转先围绕画面中心进行，X/Y始终表示项目中的同一个中心点。
// 宽高沿用contain基础适配，镜像不会把竖视频强制拉伸到横项目全幅。
// 内容层裁在项目边界内，操作选框位于独立交互层，避免手势反馈被裁掉。
// 上层缩小时留出的空间是真实透明区域，下层解码视频可以从中露出。
// 不透明度应用到每层实际媒体像素，黑色背景只属于最底部项目画布。
// 选中框不会写入内容，也不参与未来导出画面的契约。
// 从素材模式查看源时不套用这个工程构图，仍看到原始文件画面。
function canvasStyle(value: ClipTransform, asset: EditorMediaAsset, project: EditorPreviewProject): CSSProperties {
  const size = fittedSize(asset.metadata?.width ?? (typeof asset.cover === "object" ? asset.cover?.width : undefined) ?? project.width, asset.metadata?.height ?? (typeof asset.cover === "object" ? asset.cover?.height : undefined) ?? project.height, project);
  return { left: `${value.x / project.width * 100}%`, top: `${value.y / project.height * 100}%`, width: `${size.width * value.scale / project.width}%`, height: `${size.height * value.scale / project.height}%`, transform: `translate(-50%, -50%) rotate(${value.rotation}deg)` };
}

// 拖动像平移桌面上的一张照片，不论照片转了多少度，屏幕向右仍对应项目X增大。
// 因此使用画布比例换算全局位移，不能用旋转后的对象矩形当尺子。
// 起点保留鼠标抓住照片的偏移，绝不把照片中心吸到鼠标下面。
// 位置限制与属性字段一致；保留两位小数是项目值精度，不是屏幕像素取整。
// 允许出界，只在最终画面裁切；禁止出界会让用户无法做常见的局部构图。
// factor在本手势开始时固定；画布尺寸若改变则由生命周期取消，不能继续用旧尺子。
// 起点value在按下瞬间复制，因此每次move都从同一个原中心加完整位移。
// 不能用上一次候选加本次总位移，否则鼠标移动十像素会被重复累加多次。
// X和Y分别使用项目宽/屏幕宽与项目高/屏幕高，不能假设两者永远同一个数。
// 常规项目frame保持比例，这两个系数应接近；分别计算可以抵御亚像素舍入差。
// 屏幕坐标用clientX/clientY，与frame矩形相同参照，不掺入系统窗口装饰偏移。
// frame左上已反映居中黑边，位移算法不再额外减一次预览表面的留边。
// 因为只算差值，点击时抓取偏移自动保持，不需要逆旋转求鼠标局部坐标。
// 例如指针抓在右上角，再向右移动192项目像素，画面中心也只增加192。
// 照片转30度或缩50%仍应得到相同项目位移，不能被旋转包围盒宽度放大误差。
// 候选位置保留其他三个字段，不在每次move时重新contain或清空透明度。
// 坐标允许负值和越过项目宽高，画布边界只是最终裁切而非拖动范围限制。
// 只有数值安全范围会夹限到十万，范围与属性输入一致，防止无穷CSS百分比。
// 两个小数位足以表达项目亚像素位置，不把屏幕整数坐标等同于项目整数像素。
// 松手会再用最后坐标计算一次，浏览器没有发最后move时仍能提交正确终点。
function gestureValue(gesture: CanvasGesture, x: number, y: number): ClipTransform {
  const round = (value: number) => Number(Math.max(-100000, Math.min(100000, value)).toFixed(2));
  return { ...gesture.origin, x: round(gesture.origin.x + (x - gesture.x) * gesture.factorX), y: round(gesture.origin.y + (y - gesture.y) * gesture.factorY) };
}

// 只为当前片段捕获手势，媒体节点作为children始终保留，不把视频换成封面来拖动。
// 裁切层独立overflow:hidden，旋转或移出项目的真实像素不会画到项目边界以外。
// 选框是另一个无媒体的按钮层，截图导出能力没有接通，也不会把选框当画面像素。
// 交互层允许溢出frame，外侧预览表面仍负责工作区边界；选框不被内容裁切层切掉。
// pointer捕获保证鼠标离开画面后仍能松手提交，Escape和系统取消都保留旧构图。
// 关闭页面、换片段、锁轨或改变画布尺寸会结束旧手势，不留下全局键盘监听。
// frameRef测量的是整个项目相框，不是当前已经缩放或旋转的内容。
// 相框包括项目黑场，源画面可能只占其中一部分，但项目坐标尺始终不变。
// canvasRoot绝对铺满frame，所以基础left/top百分比不包含标题、控制条或边栏。
// 真实内容通过children保留引用，字段变化只更新样式，不调用load或替换src。
// 因此构图不应改变当前视频帧、播放位置、静音状态或媒体readyState。
// 画面外的操作反馈来自另一层，不会被canvasCrop的overflow隐藏。
// 整个预览表面仍限制工作区外溢，不能让选框覆盖应用导航或窗口按钮。
// 当对象大部分移出画布，仍可通过属性数字和重置找回，不新增自由变形手柄。
// 没有添加旋转手柄，旋转只由复用字段提交，符合本轮不做自由变形的边界。
// 没有canvas像素绘制或getImageData处理用户视频，避免建立另一套解码和采样流程。
// 视频继续由Chromium渲染，裁切和二维变换由同一DOM几何完成。
// 这是一层真实单源变换，不是上方视频轨覆盖下方视频轨的合成器。
// 选框显示与轨道顺序没有任何关联，不能用选中高亮改变未来叠放规则。
export function ClipCanvas({ clip, asset, project, edit, children, plane = "all" }: CanvasProps) {
  const { t } = useTranslation(), frameRef = useRef<HTMLDivElement>(null), gesture = useRef<CanvasGesture | null>(null);
  const value = edit?.value ?? clip.transform ?? defaultTransform(project), style = canvasStyle(value, asset, project);
// 先清gesture引用再释放捕获，因为release可能同步触发lostpointercapture。
// 若先释放再清引用，lost事件可能第二次取消同一草稿，形成重复状态写入。
// 没有活跃手势时取消应是无动作，正常主题刷新不能清空其他对象的候选。
// 移除草稿由edit.preview(null)完成，工程确认值从未被中间move改写。
// 不执行反向transform意味着取消不会覆盖手势期间外部已经确认的新值。
// 释放捕获前检查hasPointerCapture，避免系统已取消后再释放抛DOMException。
// 捕获元素可能已被卸载，清理仍使用当初保存的元素引用，不重新查另一按钮。
  function cancel() {
    const active = gesture.current;
    gesture.current = null;
    if (!active) return;
    if (active.element.hasPointerCapture(active.pointer)) active.element.releasePointerCapture(active.pointer);
    edit?.preview(null);
  }
  // effect只拥有当前画布的取消边界，所有回调都读取本次实际手势。
  // 依赖对象、锁和确认变换，切换对象或字段提交不能继续拖动旧草稿。
  // 不依赖每次变化的edit对象，否则每帧候选更新都会把自己取消掉。
  // preview回调仅清候选，清理时不提交工程，也不重新选择素材。
  // ResizeObserver初次通知只建立基准，真正尺寸变化才结束手势。
  // blur覆盖切换到其他程序；系统pointercancel也走同一保留确认值流程。
  // Escape监听限于活跃手势，平时不会抢属性输入框的Escape恢复行为。
  // 元素移除时先释放捕获，迟到的pointerup不能把已取消候选写回来。
  useEffect(() => {
    const frame = frameRef.current;
    if (!frame) return;
    let size = "";
    const observer = new ResizeObserver(() => { const box = frame.getBoundingClientRect(), next = `${box.width}:${box.height}`; if (size && next !== size) cancel(); size = next; });
    const key = (event: globalThis.KeyboardEvent) => { if (event.key === "Escape" && gesture.current) { event.preventDefault(); event.stopPropagation(); cancel(); } };
    observer.observe(frame); window.addEventListener("blur", cancel); window.addEventListener("keydown", key, true);
    return () => { observer.disconnect(); window.removeEventListener("blur", cancel); window.removeEventListener("keydown", key, true); cancel(); };
    // 候选变化不重装订阅；锁/对象/确认值变化必须结束旧手势。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clip.id, clip.transform, edit?.locked]);
  // 取消选中才终止手势；从未选中变为选中是按下画面的正常动作。
  // 若把selected放进上面effect的清理依赖，首次点击会刚捕获就被自己取消。
  // 独立检查失选可兼顾“点击选中后继续拖”和“外部切换对象后放弃旧草稿”。
  useEffect(() => {
    if (!edit?.selected) cancel();
    // cancel读取当前捕获，只在选择身份变化时执行，候选更新不重装订阅。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [edit?.selected]);
// 只接主键，右键不能改构图或抢走现有片段菜单的意图。
// 锁轨在手势起点就拒绝，不给用户一个最后才回弹的假移动反馈。
// frame宽高为零时不开始手势，隐藏页面或正在布局时不能除零得到无限坐标。
// preventDefault阻止浏览器选择视频或执行默认拖图片行为，画布用pointer而非HTML文件拖放。
// 因此不会生成时间线MIME载荷，也不会被外部Files导入流程误识别为新素材。
// focus使用preventScroll，避免按钮边界在画布外时浏览器自动滚动造成视觉抖动。
// 选中动作不调用播放头定位，用户可以在当前真实帧上调整画面。
// origin复制当前确认或候选值，后面不修改父组件传入的对象。
// 指针ID记录在gesture，一个无关触点不能接管另一次鼠标操作。
// setPointerCapture由真实pointerdown触发，捕获失败不会通过伪造属性蒙混成真实拖动。
  function down(event: PointerEvent<HTMLButtonElement>) {
    if (!edit || edit.locked || event.button !== 0) return;
    const box = frameRef.current?.getBoundingClientRect();
    if (!box?.width || !box.height) return;
    event.preventDefault(); edit.select(); event.currentTarget.focus({ preventScroll: true });
    gesture.current = { pointer: event.pointerId, element: event.currentTarget, x: event.clientX, y: event.clientY, factorX: project.width / box.width, factorY: project.height / box.height, origin: { ...value }, candidate: { ...value } };
    event.currentTarget.setPointerCapture(event.pointerId);
  }
// 只接受本次pointerID，系统额外触点和迟到事件都不改变当前候选。
// 锁表变化后即使还没收到清理通知也先停止更新候选。
// candidate同时存在于本次手势引用与外层预览草稿，松手不依赖React是否已画完最后一帧。
// 预览回调会刷新字段显示，但不调用工程提交，因此工程时长和源区间都不变。
// 不能直接把event对象保存在状态中，React事件生命周期不应延长到松手以后。
// 这里仅保存数值，不保存DataTransfer、File或完整媒体对象。
  function move(event: PointerEvent<HTMLButtonElement>) {
    const active = gesture.current;
    if (!active || active.pointer !== event.pointerId || edit?.locked) return;
    active.candidate = gestureValue(active, event.clientX, event.clientY);
    edit?.preview(active.candidate);
  }
// 先保存当前手势引用再清全局槽位，后续lost捕获不会误取消刚提交的构图。
// 最后坐标重新换算，避免释放发生在两个pointermove之间时丢失末端位置。
// 先结束临时预览再提交确认值，二者在同一事件批次，不显示回原处再跳到终点。
// 提交前再次查看locked，防止拖动中途被锁定还按旧权限写入。
// 工程命令还会复核锁与身份，组件层只是提前提供交互保护。
// pointercancel不走这里，系统中断必须保留原确认值而非提交当前候选。
// 拖动松手不改变selectedClip以外的任何安排，复制对象不被连带位移。
  function up(event: PointerEvent<HTMLButtonElement>) {
    const active = gesture.current;
    if (!active || active.pointer !== event.pointerId) return;
    gesture.current = null;
    const candidate = gestureValue(active, event.clientX, event.clientY);
    if (active.element.hasPointerCapture(active.pointer)) active.element.releasePointerCapture(active.pointer);
    edit?.preview(null);
    if (!edit?.locked) edit?.commit(candidate);
  }
// sourceIn以只读数据属性提供源区间观测，不能通过改DOM属性写回工程。
// 该值服务真实媒体映射与验收，不影响百分比构图或时间线位置。
// 相同源的两个层可能有不同入点，不能只比较currentTime就宣称两层失步。
// 图层同步必须先扣各自sourceIn，再加工程start比较同一节目时间。
  return <div ref={frameRef} className={styles.canvasRoot} data-clip-canvas={plane !== "operations" ? clip.id : undefined} data-canvas-operations={plane === "operations" ? clip.id : undefined} data-source-in={clip.sourceIn ?? 0} data-transform={JSON.stringify(value)}>
    {/* 节目画面：真实video/img位于唯一裁切层，构图不改变媒体src和解码生命周期。 */}
    {plane !== "operations" && <div className={styles.canvasCrop}><div className={styles.canvasContent} style={{ ...style, transform: `${style.transform} scaleX(${clip.mirrored ? -1 : 1})`, opacity: value.opacity / 100 }} data-canvas-content>{children}</div></div>}
    {/* 操作选框：只控制当前单源片段，不改变轨道优先级，也没有自由变形手柄。 */}
    {plane !== "picture" && edit && <button type="button" data-canvas-selection={edit.selected} data-canvas-locked={edit.locked} className={styles.canvasSelection} style={{ ...style, pointerEvents: edit.locked || value.opacity === 0 ? "none" : undefined }} tabIndex={edit.locked ? -1 : 0} aria-label={t("toolBox.editorUi.canvasSelect")} aria-disabled={edit.locked} onClick={edit.select} onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={cancel} onLostPointerCapture={cancel} />}
  </div>;
}

/** 片段构图纯计算：工程像素存事实，预览百分比只负责缩小显示。 */
import { inspectorFields, type PropertyKey } from "./editor-property-model";
import type { EditorMediaAsset, EditorPreviewProject } from "./editor-panels";
import type { LiveTimelineClip } from "./live-timeline-model";

// 位置是整张源画面的中心，左上原点、向右向下递增，允许画面移出项目。
// 缩放百分比乘在contain基础尺寸上，不表示源文件一像素对应屏幕一像素。
// 旋转是中心周围的二维顺时针角度，和DOM坐标向下的约定一致。
// 不透明度属于当前单源画面，不把它叫作已经完成多轨混合。
// 一个片段一份数值记录；源素材和其他同源安排不共享可修改的对象。
// 没有关键帧、透视、自由变形或输出编码字段，不能借此更改源文件。
// 参数的单位跟字段一一对应，x/y为项目px，scale/opacity为百分数，rotation为度。
// 位置可以为零和负数，不能用逻辑或把合法零换成默认中心。
// 透明度0也不是空值，必须保留为整张画面透明的明确意图。
// scale最小值沿用字段的0.01%，不允许0造成对象变成不可操作的退化点。
// 这里没有源宽高字段，源分辨率仍由素材元数据拥有，不复制到每个实例里。
// 保留的是五个数值，不持有HTMLVideoElement或Image对象，也不扣住文件句柄。
// 将来序列化需要独立工程版本规则，当前接口只属于临时渲染会话。
// 它不是跨进程类型，本轮不增加IPC通道或任意JSON写入能力。
// 工程重开后依然是空会话，值不会悄悄写进用户设置。
// 未显式传入transform的历史样板仍可显示，不能为兼容改写DEMO常量。
// X/Y使用项目像素，可表达小数位置，不随播放器的CSS宽高变成不同单位。
// 缩放100对应适配后的基础盒，缩放200使基础宽高各翻倍、面积变为四倍。
// 不透明度按百分数保存，渲染时才除100转为CSS的0到1。
// 旋转输入度数，浏览器CSS也接收deg，不引入弧度存储和二次换算。
// X/Y不会因为旋转改变参照轴，向右拖动始终增加X。
// 位置定义中心意味着修改scale不需要补偿半个旧宽高。
// 二维旋转不包含透视倾斜，不能把此类型当成任意四角网格。
// 帧率不参与空间参数，30fps和24fps素材使用同一种项目像素尺。
// 参数没有时间戳，表示整个安排的恒定构图，不是关键帧曲线。
// 不同源分辨率共用项目坐标系，但各自contain基础盒不同。
// 项目边界之外仍是有效位置，裁边只改变可见像素，不改保存的中心。
// 允许极小缩放是数值能力，不保证屏幕上始终容易用鼠标抓取。
// 极小或全透明对象仍可通过属性重置恢复，操作层不随透明度消失。
// 类型本身不决定媒体可编辑，模型仍需检查素材类别和轨道锁。
// transform对象不能放回共享素材条目，否则两个同源片段将被迫使用同一构图。
export interface ClipTransform { x: number; y: number; scale: number; rotation: number; opacity: number; }
export type TransformKey = keyof ClipTransform;
export const TRANSFORM_KEYS: readonly TransformKey[] = ["x", "y", "scale", "rotation", "opacity"];

// 像把照片完整放进相框，先保持比例找到能容纳整张照片的最大尺寸。
// 这就是100%的基础适配尺寸；横竖源都有同一种解释，不预先裁掉边缘。
// 640×360放进1920×1080得到1920×1080；360×640得到607.5×1080。
// 宽高取真实源元数据，不能把素材卡片缩略图的尺寸当作源分辨率。
// 无效分辨率返回项目比例的安全布局，探测失败的源仍由播放器报告不可用。
// 返回的是项目像素，不包含窗口尺寸、系统DPR、导航宽度或画布黑边。
// 缩放50%会把这里的宽高各减半，不改变项目宽高或视频解码分辨率。
// 基础适配使用两个比值的较小者，这与铺满并裁边的cover策略不同。
// 源长宽比不等于项目长宽比时，一侧会留黑边，但实际画面本身不拉伸。
// 比如竖片在横项目内，黑边属于项目画布，不属于可拖动画面。
// 点击黑边不应被当成抓取竖片，命中层采用基础画面尺寸而非整个frame。
// 放大之后可能覆盖并越过项目边界，裁切由预览内容层完成而不是改变源尺寸。
// 100%不是源文件原始像素大小，因此小分辨率源也可能被适配放大。
// 用户若想让640宽源在1920工程占640宽，可设缩放约33.33%。
// 这只是构图显示大小，不做超分、不添加像素，也不改变ffprobe探测结果。
// 预览窗口缩小时仍先计算项目基础宽高，再按frame同比缩小。
// 不能先把源适配到屏幕，再把屏幕宽度存进transform，否则换窗口构图就漂移。
// 参数验证只负责避免NaN和除零，不把素材元数据的错误伪装为解码成功。
// 没有宽高时采用项目比例供占位布局，真实媒体可用性仍归导入和播放器判断。
// 默认项目宽高由正式工作区常量提供，必须保持正数才能建立有效画布。
// 如果未来允许修改项目尺寸，需明确已有中心坐标如何迁移，不能由此函数偷偷决定。
// 本方法没有缓存，源或项目参数变更后直接得到新基础尺寸，不持有旧DOM测量。
// 基础适配与旋转分开，旋转90度不会自动交换源尺寸并重新contain。
// 否则每次改变角度都可能突然缩小图片，违背固定缩放比例的操作预期。
export function fittedSize(width: number, height: number, project: EditorPreviewProject) {
  const valid = Number.isFinite(width) && Number.isFinite(height) && width > 0 && height > 0;
  const factor = valid ? Math.min(project.width / width, project.height / height) : 1;
  return { width: valid ? width * factor : project.width, height: valid ? height * factor : project.height };
}

// 默认中心随项目定义计算，不能把1920工程的960写死给竖屏项目。
// 每次返回独立对象，重置一个片段不会改变模块级模板或另一个安排。
// 省略覆盖值的旧片段按同一默认值解释，兼容静态样板和已有临时工程。
// 源像素尺寸只参与基础适配，不参与中心坐标，因此换源分辨率不改变默认中心。
// 角度零、透明度100和缩放100是一组明确的无额外变换，不是未处理完成标志。
// 重置返回项目中心而非源中心，竖片和横片处于同一工程时中心相同。
// 项目1920×1080的坐标范围以左上角为原点，但允许画面中心移出该范围。
// 位置取画面中心，避免用户缩放后X/Y突然因为左上角移动而改变含义。
// 默认旋转零保持源朝向；视频探测的显示宽高需要由素材适配先处理好。
// 默认透明度100意味着当前单层画面不额外变暗，不宣称任何混音或图层混合完成。
// 每次返回新对象还能保护复制后的记录，后续字段更新不复用同一可变模板。
// 调用此函数不会建立轨道、选择素材或播放媒体，显示默认值没有业务副作用。
export function defaultTransform(project: EditorPreviewProject): ClipTransform {
  return { x: project.width / 2, y: project.height / 2, scale: 100, rotation: 0, opacity: 100 };
}

// UI字段、画布拖动和重置最终都走这个入口，不能只在disabled外观上保护锁。
// patch是局部变更，未提供的值保留当前片段确认值，不回落成其他片段的默认值。
// 键经过白名单，速度和淡入淡出即使误调用此处也不能被写成“已生效”。
// 范围和小数精度复用检查器字段定义，拖动和输入不能各自采用一套限制。
// 先验证整份patch再返回新数组，X合法Y非法时不能留下半次位置提交。
// 音轨引用原视频也仍是音频安排，没有画面变换，拒绝给它写X/Y。
// 素材存在且类型为视频或图片才可提交，未知ID不能默认修改第一项。
// 不接时间参数，所以构图提交不会改变start/end、sourceIn或工程时长。
// 返回null表示拒绝，调用者保留旧快照，不用空数组把已有工程清掉。
// 校验先定位稳定ID，两个文件名完全相同也不会选错片段实例。
// 再根据assetId找到真实媒体类别，不能用.mp4等后缀代替视频/图片/音频类型。
// 独立音轨虽然仍指向视频源文件，但audioOnly标记让它没有画面变换权限。
// 锁表以轨道ID判断，不以当前工具栏高亮或属性名称推断锁定。
// 源锁在每次提交重查，菜单曾经打开或字段曾经可用都不构成持续授权。
// 字段范围来自inspectorFields，因此坐标、缩放和不透明度不能共享一个笼统的0到100限制。
// 旋转保留累计度数，360不自动归零，用户输入和字段显示保持同一种解释。
// 数值先检查有限性再取精度，否则Infinity.toFixed不会成为合法布局数值。
// 圆整到字段精度后生成确认记录，避免指针反复来回积累不可读的浮点尾数。
// 输入的patch对象不被修改，事件层仍可保留原候选用于取消和测试对照。
// 原clip对象也不被修改，正在渲染旧快照的预览不会半途读到另一个构图。
// 没有修改的其他实例原样保留，避免输入X时导致所有视频播放器重装源。
// 新transform是完整五个值，哪怕只提交X，也保留此前缩放、角度和透明度。
// 这比保存一份DOM矩阵更易解释，也不会把CSS transform字符串作为工程契约。
// 不接sourceUrl意味着此处没有磁盘访问、上传或媒体重编码权限。
// 不接start/end补丁意味着构图不会绕过已有时间轴碰撞和锁定规则。
// 失败返回null时不携带半成品数组，调用方只有成功才替换当前clips。
// 如果其中一项非法，前面暂存的数值只留在局部next对象，不会先写回源记录。
// 空patch没有新的效果意图，但仍必须验证身份、媒体类型和锁，不能成为绕过入口。
// 复制后的对象使用相同数值是正确继承，独立更新依靠新clip.id与新transform对象保证。
// 后续多轨合成应消费这组项目值，不能以当前选中对象的DOM顺序推断层级。
// 导出尚未接通，本方法不声称这些参数已经写入任何输出文件。
export function updateClipTransform(clips: readonly LiveTimelineClip[], assets: readonly EditorMediaAsset[], id: string, patch: Partial<ClipTransform>, project: EditorPreviewProject, locked: readonly string[]) {
  const clip = clips.find(item => item.id === id), asset = assets.find(item => item.id === clip?.assetId);
  if (!clip || clip.audioOnly || !asset || asset.kind === "audio" || locked.includes(clip.track)) return null;
  const fields = inspectorFields([{ id, asset, duration: clip.end - clip.start }]);
  const next = { ...(clip.transform ?? defaultTransform(project)) };
  for (const [name, value] of Object.entries(patch)) {
    if (!TRANSFORM_KEYS.includes(name as TransformKey)) return null;
    const field = fields.find(item => item.key === name);
    if (!field || typeof value !== "number" || !Number.isFinite(value) || value < field.min || value > field.max) return null;
    next[name as TransformKey] = Number(value.toFixed(field.precision));
  }
  return clips.map(item => item.id === id ? { ...item, transform: next } : item);
}

// 字段键属于更大的检查器集合，这个守卫只允许五个真实画面参数进入构图命令。
// 返回类型让调用方安全构造Partial，而不是用any跳过速度/音量能力判断。
// 重置组同样过滤这些键，不能顺带启用还没有接入的媒体处理效果。
export function isTransformKey(key: PropertyKey): key is TransformKey { return TRANSFORM_KEYS.includes(key as TransformKey); }

"use client";

// 时间线声音槽复用源包络，按片段源入点/跨度映射，不生成装饰随机波形。
// SVG只有实际读取后的振幅轮廓，取消、加载和失败不会冒充静音成功。
import { useTranslation } from "@/i18n";
import type { VideoWaveformResult } from "@/types/electron-api";
import { useSourceWaveform } from "./source-waveform";
import styles from "./editor.module.css";

// 声音条属于片段内容，鼠标在它上面按住时仍应拖整个片段而非选中SVG文字。
// 组件没有button、tabIndex或自建菜单，不增加与原片段壳冲突的交互入口。
// 图片片段没有声音来源，不因共享片段壳就请求一条假的波形。
// 分离音轨引用原视频路径，既可共享采样结果，也保留原文件不变的语义。
// 视频已分离声音时这里仍展示源声音摘要，不表示该视频实例仍会播放音轨。
// 真正静音由播放器的audioDetached规则控制，波形颜色不参与声音路由。
// 一条源可以有很多片段，各自的入点与源跨度在调用方明确传入。
// 文件名、时间码和选择边框继续由EditorClipShell提供，声音组件不复制标题层。
// sourceIn默认零用于未修剪实例，已经修剪的副本必须显式带自己的入点。
// span包含速度映射但不包含项目时间线空隙，空白轨道不会凭空显示声音。
// 同源两段即使工程位置相隔很远，源区间相同就应具有相同轮廓。
// 只改变不透明度、旋转或X/Y不会重算声音，因为这些是画面变换。
// 只改变文件名显示文本也不触发读取，声音身份来自sourcePath。
// 两个路径字符串即使指向硬链接同内容，当前也按不同源处理，不计算文件哈希。
// 这是避免读取大文件指纹的取舍，不宣称全磁盘内容级去重。
// hasAudio变false时hook会释放该订阅，不能保留上一源的ready图形。
// 辅助图失败不能阻断主体拖动，否则缺少FFmpeg会令有效视频不能排列。
// 数组只读用途由当前调用契约维护，没有用冻结拷贝制造每片段一份全源峰值。

// 画布采用1000单位宽的局部坐标，与工程帧或像素无关，外壳负责时间轴宽度。
// sourceIn是源秒数，span已经乘片段速度，不能把工程start当成声音数组下标。
// 采用窗的真实secondsPerPeak，尾部AAC填充不会把之前的声音整体挤压。
// 起止都截到源包络有效范围，不能从不存在的峰值补出装饰图形。
// 每个点的位置由源时间相对入点决定，裁掉头部后声音特征相应左移。
// 用一条封闭路径画上下包络，不为每个峰值创建一个DOM节点。
// 振幅开方只压缩视觉动态范围，让轻声可见，不写回音量或播放效果。
// 全静音峰值仍是零高度直线，不给静音随机添加起伏。
// 中心线高度是16，上下最大14，给细边框保留两像素空隙。
// 端点延到片段边缘，最后不足一采样窗不产生肉眼可见空洞。
// 负入点、非法跨度或空数组不绘图，工程写入校验仍由原共同模型负责。
// 返回路径仅用于展示；不能用波形高度推断音高、音色或语音识别结果。
// 同源实例即使共享result，也只创建各自路径字符串，不修改peaks数组。
// 1000单位横向缩放不会重新采样源音频，Ctrl滚轮只影响轮廓的屏幕密度。
// 窗口覆盖的平均时间分辨率受2048窗预算约束，不声称逐音频样本可见。
export function waveformPath(data: VideoWaveformResult, sourceIn: number, span: number) {
  if (!data.peaks.length || !Number.isFinite(span) || span <= 0 || sourceIn < 0) return "";
  const first = Math.max(0, Math.floor(sourceIn / data.secondsPerPeak));
  const last = Math.min(data.peaks.length - 1, Math.floor((sourceIn + span) / data.secondsPerPeak));
  const upper: string[] = [], lower: string[] = [];
  for (let index = first; index <= last; index += 1) {
    const x = Math.max(0, Math.min(1000, (index * data.secondsPerPeak - sourceIn) / span * 1000));
    const height = Math.sqrt(data.peaks[index]) * 14;
    upper.push(`${x.toFixed(2)},${(16 - height).toFixed(2)}`);
    lower.unshift(`${x.toFixed(2)},${(16 + height).toFixed(2)}`);
  }
  return upper.length ? `M0,16 L${upper.join(" L")} L1000,16 L${lower.join(" L")} Z` : "";
}

// 例如0.5秒入点、1秒源跨度，数组0.5秒附近的峰值应出现在条带左端。
// 若片段2倍速，1秒工程跨度覆盖2秒源声音，父级把span乘速度后再传入。
// 工程start只决定片段摆在哪一秒，不能拿它去裁源数组，否则移动会改变声音图形。
// 横坐标0到1000像一把伸缩直尺，同一时间占比可以投影到任意屏幕片段宽度。
// 上边界按时间正序收集，下边界逆序收集，闭合后形成一条连续包络。
// 如果下边界也按正序连接，会画出交叉多边形，声音高低看起来会错乱。
// 起点与终点夹在0/1000内，部分采样窗覆盖边缘时也不会越出片段。
// floor选择入点所在采样窗，允许这一窗跨过入点，这是概览采样精度的边界。
// 每窗只保留最高振幅，窗内具体哪一毫秒发生声音已经不可从摘要反推。
// 因此此图适合辨认大致静音和节奏，不能替代逐样本音频编辑。
// 如果入点超出包络末端，循环没有有效窗口，返回空路径而非制造全幅声音。
// 开方使0.01振幅可显示为最大高度的十分之一，便于在16px槽里看到轻声。
// 这个视觉比例不是分贝刻度，界面不提供基于它的响度读数。
// toFixed只缩短SVG坐标文本，原数据与片段时间没有被四舍五入写回。
// 每次绘图建立局部字符串数组，不反转或修改多个片段共享的peaks。
// SVG使用一条轮廓路径，4096个点不会变成4096个独立React子组件。
// 最多保留源摘要预算内的点，缩放时间线不会触发无限增长的采样数组。
// 单个窗口内有多个音节时只见最高峰，不能据此推算精确音节数。
// SVG横向拉伸只影响显示密度，返回的源秒坐标仍可与帧带逐项比对。
// 视频边框采用border-box，1000单位局部坐标不需要再扣导航或轨道头宽。
// 原始峰值没有颜色或主题字段，同一组结果可在浅深两种主题下复用。
// 减少动态效果不改变波形形状，本实现没有根据音量添加闪动动画。
// 路径生成是同步小数组转换，不再等待音频播放到相应位置才填图。
// 因而暂停节目也能查看整段轮廓，辅助展示不会驱动播放进度。
// 当前只有整体振幅包络，左右声道的相位差或单独电平没有可编辑控件。
// 如果未来接入声道编辑，需要独立扩展数据契约，不能从本单声道数组臆造。
// 这份轮廓不会成为导出内容，导出仍应读取原始源声音而非SVG或峰值摘要。
// 中线用于区分真实零振幅与整个槽没有绘制，加载与失败则用文字说明。

// 视频内嵌音轨与分离后的音频安排共用同一个波形组件，不重复读取同源内容。
// hasAudio由真实探测给出，无声源不发IPC；音轨分离只是改变安排，不删除源音轨。
// loading与error文字沿用i18n，本槽位永远不向素材库写入失败状态。
// pointer-events在CSS关闭，波形不截获片段移动、边缘修剪或右键。
// sourceIn/span随原trimDraft变化，因此鼠标候选与确认结果读取相同源区间。
// aria-hidden只隐藏装饰SVG，状态文本仍可访问，片段名称由父按钮提供。
// 无音轨使用独立标记，测试可以区别静音源与读取失败，但不会创建可播放节点。
// waveform数据就绪才加ready标记，不把挂载了SVG当成真实采样已经完成。
// ready路径为空仍保留中心线表示真实静音包络，而不是创建随机起伏。
// 组件本身不控制播放，也不自动启动声音，扬声器试听仍需另行人工验证。
// 样板不传sourcePath时不发真实请求，避免静态资产意外触发系统文件能力。
// 同一组件的源切换由hook的key保护，旧源包络不会闪到新片段上。
export function ClipWaveform({ sourcePath, hasAudio, sourceIn = 0, span }: { sourcePath?: string; hasAudio: boolean; sourceIn?: number; span: number }) {
  const { t } = useTranslation();
  const data = useSourceWaveform(hasAudio ? sourcePath : undefined);
  const path = data?.result ? waveformPath(data.result, sourceIn, span) : "";
  return <span data-clip-waveform data-waveform-source-in={sourceIn} data-waveform-span={span} data-waveform-state={!hasAudio ? "silent" : !data ? "loading" : data.status} className={styles.clipWaveform}>
    {hasAudio && data?.status === "ready" ? <svg aria-hidden="true" viewBox="0 0 1000 32" preserveAspectRatio="none"><path d={path} /><path d="M0,16H1000" /></svg> : <small>{t(!hasAudio ? "toolBox.editorUi.noAudioTrack" : data?.status === "error" ? "toolBox.editorUi.waveformError" : "toolBox.editorUi.waveformLoading")}</small>}
  </span>;
}

// data-waveform-source-in/span是只读验收信息，不作为未来保存文件的工程结构。
// ready必须来自有结果的IPC响应，挂一个空SVG本身不能证明采样成功。
// 无音轨状态直接由ffprobe元数据决定，不因请求成功null就推断源静音。
// error保留原名称与连续帧，辅助音频读取失败不会令视频片段失去选择能力。
// 小字提示走双语词条，未支持桥接的普通浏览器不会显示未翻译的内部错误。
// 波形状态在每个槽位独立渲染，分离音轨与原视频可以同时处于同源ready。
// 细窄片段可能省略状态文字，但原片段可访问名称和工程属性不因此丢失。
// SVG隐藏于读屏是因为它没有独立操作语义，周围的状态说明仍保留文本内容。

"use client";

// 项目栏、只读信息条与暂未接通的动作共享展示入口，边界不延伸至媒体业务。
// 同一个禁用按钮服务项目、预览、属性和时间轴，不在各区复制禁用样式。
// 现有 SimpleSelect 没有 disabled 契约，此阶段不改公共选择器冒充可用下拉。
// 原应用导航和窗口控制继续由 AppShell 管理，内部只有项目层级的操作。
import Link from "next/link";
// Lucide 图标继续沿用应用现有依赖，不为骨架新增工具栏图标包。
// Icon 的类型限制为 LucideIcon，调用方无法传任意字符串拼接成不安全标签。
// 同尺寸图标共享 class，预览按钮不需要单独写另一套禁用状态。
import { ArrowLeft, ArrowUpRight, FileVideo, Undo2, Redo2, Upload } from "lucide-react";
// 所有可见标签和禁用原因通过当前双语词条读取，切换语言不会保留旧提示。
// DEMO_PROJECT 仅提供帧率、宽高等只读值，不触发真实项目存取。
// CSS Module 约束本页几何，避免污染 GIF 的相同 button/header 标签。
import { useTranslation } from "@/i18n";
import { DEMO_PROJECT } from "./editor-demo";
import styles from "./editor.module.css";
import { formatEditorTimecode } from "./editor-timecode";

// 重新导出既有名称以保留项目栏和时间轴调用方，唯一实现位于 editor-controls。
// 新 UI 回调只注入纯界面动作，没有回调的旧业务入口继续禁用。
// 相同参数契约同时服务正式工作区和独立状态样板。
export { EditorAction } from "./editor-controls";
// re-export 保留旧调用路径，避免为了提取控件批量改写四个区域的 import。
// 单一实现保证修复焦点圈后项目栏、预览和时间轴同时生效。
// ProjectToolbar 自己也从新实现导入，不留一份同名旧函数造成假复用。
// 状态样板链接与业务动作不同，它是真实可用导航，不归默认禁用集合。
// 不把导航传入 EditorAction 的空回调，保留链接可复制和键盘打开语义。
// 样板页仍使用上级 AppShell，不通过新窗口或透明覆盖层显示。
// 原 legacy 链接保留，用户仍可回到真实旧版工具能力。
// 导出按钮的 accent 只表达视觉层级，未接回调就继续禁用。
import { EditorAction } from "./editor-controls";

// R01 项目工作栏：文件/编辑/视图只做禁用入口，不伪造下拉内容。
// 项目名旁用本地项目图标，避免云朵暗示当前工程已同步到服务器。
// 项目名允许截断但保留 title，宿主变窄时导航和导出仍在同一工作栏。
// 保存状态为“未保存”，不能照抄原图“已保存”误导用户文件已写入。
// 旧版链接保留真实单片段编辑能力，UI-01 不挂载旧播放器在后台消费资源。
// 工具箱返回链接复用现有路由，不调用 history.back 导致窗口离开应用。
// 标题栏不含品牌或关闭按钮，避免与 Electron 的自定义 head 重复。
// 所有菜单按钮复用 EditorAction，修改共同样式会同步到其他区域。
// 撤销与重做分别命名，不把一个禁用按钮绑定成共享的假历史记录。
// 工程名称来自词条而非硬编码中文，英语截图保持同一数据和几何。
// 状态说明靠近项目名，未接通原因还可在禁用动作悬停时查看。
// 项目栏固定高度，长标题不能挤压节目预览和时间轴的高度预算。
export function ProjectToolbar({ onImport, busy = false, onCancelImport }: { onImport?: () => void; busy?: boolean; onCancelImport?: () => void }) {
  // 当前的“文件/编辑/视图”只是布局槽位，不设置 aria-haspopup 承诺不存在的菜单。
  // Undo/Redo 没有快捷键声明，用户不会看到本轮尚未实现的 Ctrl+Z 提示。
  // 返回工具箱不会关闭 Electron 窗口，窗口关闭能力只在原 head 中出现。
  // 旧版工具链接是显式选择，不按文件是否存在自动跳转切换编辑器实现。
  // 长项目名的 title 只补全文字，不包含用户本地路径或账号敏感信息。
  // 当前保存状态没有旋转 loading 图标，不能以动画冒充真实保存进度。
  // 导出入口固定保留，但禁用时不会打开一个已经填满假成功结果的弹窗。
  // “项目操作”的 nav 名称与应用主导航不同，读屏可区分这两个导航区域。
  // 品牌原图中的 Illusion Studio 不被复制，真实 AppShell 继续呈现 Illusion Realm。
  // 链接使用应用内相对路由，静态导出和 app:// 下都由 Next 负责导航。
  const { t } = useTranslation();
  return <header data-editor-region="R01" className={styles.projectBar}>
    <Link href="/tools" className={styles.navigation} title={t("toolBox.main.back")}><ArrowLeft size={16} /><span className={styles.optionalText}>{t("toolBox.main.back")}</span></Link>
    <div className={styles.projectName} title={t(onImport ? "toolBox.editorUi.liveProjectName" : "toolBox.editorUi.projectName")}><FileVideo size={17} /><strong>{t(onImport ? "toolBox.editorUi.liveProjectName" : "toolBox.editorUi.projectName")}</strong><span>{t("toolBox.editorUi.unsaved")}</span></div>
    <nav className={styles.projectMenus} aria-label={t("toolBox.editorUi.projectActions")}><EditorAction label={t("toolBox.editorUi.file")} /><EditorAction label={t("toolBox.editorUi.edit")} /><EditorAction label={t("toolBox.editorUi.view")} /><EditorAction icon={Undo2} label={t("toolBox.editorUi.undo")} compact /><EditorAction icon={Redo2} label={t("toolBox.editorUi.redo")} compact /></nav>
    <Link href="/tools/video/editor/legacy" className={`${styles.navigation} ${styles.legacyLink}`}>{t("toolBox.editorUi.legacy")}<ArrowUpRight size={14} /></Link>
    <Link href="/tools/video/editor/samples" className={styles.navigation}>{t("toolBox.editorUi.samples")}</Link>
    {onImport && <EditorAction icon={Upload} label={t("toolBox.editorUi.import")} onClick={onImport} busy={busy} accent />}
    {/* 窄屏素材栏隐藏时，项目栏仍能取消当前批次；静态样板不获得这个能力。 */}
    {busy && onCancelImport && <EditorAction label={t("toolBox.editorUi.cancelImport")} onClick={onCancelImport} />}
    <EditorAction icon={Upload} label={t("toolBox.editorUi.export")} accent />
    <span id="video-editor-unavailable" className="sr-only">{t("toolBox.editorUi.unavailable")}</span>
  </header>;
}

// R10 只读信息条：项目参数与播放总时长来自同一 DEMO_PROJECT。
// 它不是全局任务栏，不重复下载、ComfyUI 状态或保存按钮。
// 项目时长明确为 30 秒，不能用当前选中 scene_02 的 8 秒替换。
// 保留完整 title，紧凑宽度下视觉截断不丢失项目信息。
// 时间码固定在 30fps 的零帧边界，暂不声称有任意帧精度计算。
// 未来格式化函数接入时应在此替换，不散落在素材或属性区各算一份。
// 信息条保持固定高度，时间轴内容较多时仍在滚动区域外可见。
export function ProjectInfoStrip({ project = DEMO_PROJECT }: { project?: { width: number; height: number; fps: number; duration: number } }) {
  // 不在这里读系统时间或 Date.now，确保预渲染与客户端首帧参数一致。
  // 30fps 仅是样例工程帧率，不根据本机显示器刷新率推断项目帧率。
  // 项目宽高与节目图 object-contain 分开，画面显示大小不改变输出参数。
  // 信息文本无点击事件，状态栏不成为第二个可编辑工程设置入口。
  // 不显示文件大小、码率或导出路径，因为这些没有真实媒体或输出证据。
  const { width, height, fps } = project;
  const text = `${width} × ${height} · ${fps}fps · ${formatEditorTimecode(project.duration, fps)}`;
  return <footer data-editor-region="R10" className={styles.infoStrip} title={text}>{text}</footer>;
}

"use client";

// 视频、图片和音频共享工程坐标与选择外框，内容通过 children 注入。
// 秒数像一把共同的尺子：left 用开始时间，width 用片段时长，不能按文件名撑宽。
// 正式V1与样板通过各自回调驱动选择，未接通入口不传回调。
// 本外壳不持有素材、撤销栈、碰撞规则或解码器，避免 UI 抽象吞并业务。
import type { ReactNode, DragEvent, KeyboardEvent, MouseEvent, PointerEvent } from "react";
import { useTranslation } from "@/i18n";
import styles from "./editor.module.css";

// clipId 与素材身份分开，同源片段也能各自选中，不用数组下标当身份。
// locked 只控制当前实例，公共组件不查询其他轨道的全局锁。
// start/end/duration 由工程模型给出，组件不回写修剪或拉长工程时长。
// label 同时作为 title 和无障碍名称，窄片段隐藏文字也不会丢失名称。
// children 表达媒体内容，视频封面和音频波形不复制外框与把手。
// 没有 onSelect 即原生禁用，不以透明度假装阻止真实剪辑操作。
// 本轮新增的是可选事件契约，不另造一个“真实片段Card”。
// onDragStart接收原生按钮事件，currentTarget才是完整片段外框。
// 若从内部封面或标题抓取，事件target可能是span，不应用它计算偏移。
// onDragEnd不接收业务参数，因为结束只需通知拥有者清理手势。
// onKeyDown把事件和实例身份在调用处绑定，公共壳不查全局选中项。
// 没有拖动回调时draggable为false，静态样板不会变成半接通编辑器。
// locked优先于拖动能力，未来传入锁定片段也不会仅禁用点击却允许拖动。
// 壳不生成clipId，身份来自创建命令，在重渲染和滚动时保持稳定。
// 选中只改变边框和装饰把手，CSS宽度始终由end-start确定。
// 按钮保留原生焦点能力，方向键替代不需要增加一组隐形控制器。
// 把手接收独立pointerdown，主体仍走原HTML移动载荷，两种手势不能同时启动。
// ARIA名称是源文件名，数据属性另存clipId，自动化不靠名称区分同源实例。
interface ClipShellProps {
  id: string; label: string; start: number; end: number; duration: number;
  // 正式时间线注入时长时间码，静态样板仍沿用原布局和状态。
  // 帧率由调用方提供，外壳不从源文件名推算时间或改变边缘。
  // label保留完整源名称，时间码只是另一段可见信息。
  timecode?: string;
  kind: "video" | "image" | "audio"; selected: boolean;
  children: ReactNode; locked?: boolean; onSelect?: () => void;
  // 真实V1注入手势，样板不传仍是原来的选择或禁用行为。
  // 壳只转发当前按钮事件，碰撞与源身份归工程层校验。
  // 键盘动作也由调用方注入，不在公共壳里猜测一帧多少秒。
  onDragStart?: (event: DragEvent<HTMLButtonElement>) => void;
  onPointerDown?: (event: PointerEvent<HTMLButtonElement>) => void;
  onTrimStart?: (event: PointerEvent<HTMLElement>, edge: "start" | "end") => void;
  onTrimKey?: (event: KeyboardEvent<HTMLElement>, edge: "start" | "end") => void;
  onDragEnd?: () => void;
  onKeyDown?: (event: KeyboardEvent<HTMLButtonElement>) => void;
  // 右键与菜单键由工程层绑定目标，外壳不保存全局“最近右键片段”。
  // 可选回调让原样板继续维持静态能力边界，GIF不受影响。
  // 事件使用currentTarget定位完整片段，封面子节点不会改变目标身份。
  onContextMenu?: (event: MouseEvent<HTMLButtonElement>) => void;
  // currentTarget由按钮本身确定；文字span和音符都只承担展示，不绑定另一份菜单。
  // 公共壳不阻止默认右键，只有注入真实回调的正式工程才将其替换为片段操作。
  // KeyboardEvent仍交给同一实例回调，菜单键不会靠文件名去寻找目标。
  // 音频片段与视频片段的百分比定位不变，因此锁轨只属于手势规则，不写到外壳坐标里。
  // 选中状态由会话注入，右键聚焦另一个实例不会让全部同源安排一起高亮。
}
// start 和 end 使用同一个工程单位秒，组件不接受混杂的像素和帧值。
// duration 由调用方提供总时长，不用素材自己的长度充当工程分母。
// 0–8 秒和 10–18 秒由相同长度得出等宽，真实空隙不会被布局均分。
// kind 只决定视觉表面，音频内容由插槽插入，外壳不生成波形数据。
// image 使用视觉片段规则，但不暗示图片有原生音视频时长。
// selected 从外部传入，多个同源片段可以表达不同的选择状态。
// id 是片段身份，不能用 label 当 key，重名媒体也可能有不同片段。
// 锁定优先于 onSelect，即使调用方忘记移除回调也不能激活。
// 没有回调时保留静态选中外观，不能通过外框自行建立另一份选择状态。
// 手柄随悬停或键盘焦点显露，修剪由可聚焦slider与指针捕获共同实现。
// 片段壳内不嵌套button；修剪边缘使用slider语义并隔离父级键盘事件。
// left/width 采用百分比以共享标尺列，不包含轨道头或全局导航宽度。
// 主时间轴横滚时外壳和标尺在同一滚动体内，不需要事件追赶位置。
// 片段边框位于 border-box 内，选中不会改变 start/end 对应的宽度。
// 不在外壳里注册 document 键盘事件，避免每个片段都监听空格或删除。
// 后续真实拖动需要独立命令边界，不能在此直接修改素材描述。
// 锁定片段保留外观和提示，但不接收鼠标与键盘选择。
// 把手携带可访问名称和当前秒数，锁定时不挂载，避免伪装仍可编辑。
// 所有媒体用同一个 box-sizing 与边框，选择时坐标不会增宽两个像素。
// aria-pressed 表达可选状态，aria-current 保留既有几何回归的定位契约。
// data 属性提供稳定时间信息，不暴露磁盘路径或项目存储格式。
// 时间轴与样板页都引用同一个类，深浅主题不需要复制 JSX。
// 边缘把手现在通过onTrimStart/onTrimKey注入真实能力，不再是假装可拖的装饰线。
// 左右分别提供slider语义和独立标签，键盘用户可以明确操作入点或出点。
// 把手仅在有回调且未锁定时挂载，独立静态样板不意外获得真实修剪。
// 主体仍沿用原button壳和选择/右键行为，不新增“多轨专用片段组件”。
// 手柄按下阻止冒泡，由上层修剪Hook捕获；主体按下只记录移动抓取点。
// 点击手柄不重新选中或定位到片段头，避免一次边缘操作把节目书签偷换。
// 原生dragstart若来自手柄就阻止，不能同时启动HTML拖放和pointer修剪。
// 左右箭头由onTrimKey处理并阻止冒泡，父片段的左右平移不会重复执行。
// aria-valuenow使用实际工程边缘时间，不用显示像素反推一个近似值。
// 选中样式保持一像素，选择和鼠标悬停不能改变片段百分比宽度。
// 标签和把手都不参与区间长度计算，长文件名省略不会让时间线片段变长。
// 锁定仍使用原生disabled，右键与键盘提交另有共同模型复核。
// 轨道ID不在外壳内部硬编码，调用方可把相同片段壳用于任意合法V/A编号。
// 片段壳保留真实button语义，选中高亮从外部注入，不在点击时临时改DOM边框。
// 按钮整体承接选择与右键，内部胶片带只是当前片段源内容的缩略展示。
// 透明修剪热区贴在左右工程边界，不能让封面遮住热区造成只能拖主体。
// 左右热区使用各自slider名称与当前边缘秒数，读屏能够区分入点和出点。
// slider的值域使用工程范围，实际源剩余长度仍由修剪模型最终约束。
// 键盘事件在边缘处隔离，按一次方向键不能同时修剪和整段平移。
// 鼠标按下边缘后由修剪Hook捕获，不让HTML原生dragstart再启动主体移动。
// 片段内容较窄时热区可能接近，视觉仍是一像素边框而不是两块厚把手。
// 当前没有对极端小于热区总宽的片段提供放大手柄浮层，用户可先放大时间轴。
// 时间线缩放只改变百分比投影的屏幕宽度，不能改变aria-valuenow的工程值。
// 长文件名通过标签省略，完整名称仍作为按钮可访问标签与title。
// 同源片段共用文件名时，data-editor-clip仍用独立实例ID。
// 锁轨关闭主体拖动与修剪热区，不靠一个覆盖层假装禁止编辑。
// 取消修剪后外壳重新读取确认区间，不留一个看似已裁掉的局部CSS宽度。
// 音频复用相同边界机制，不能另算一套按波形像素决定的时间模型。
export function EditorClipShell({ id, label, timecode, start, end, duration, kind, selected, children, locked = false, onSelect, onDragStart, onDragEnd, onKeyDown, onContextMenu, onTrimStart, onTrimKey, onPointerDown }: ClipShellProps) {
  // 右键仍受原生disabled保护，锁定或未接回调的样板不会获得工程编辑能力。
  // data-kind使真实音频安排可观察，不需要从封面颜色猜通道类型。
  // 所有通道继续使用相同start/end百分比，音频与视频不各画一把尺子。
  const { t } = useTranslation();
  return <button type="button" disabled={locked || !onSelect} onClick={onSelect} onPointerDown={onPointerDown} draggable={!locked && !!onDragStart} onDragStart={event => { if ((event.target as HTMLElement).closest('[data-clip-trim]')) event.preventDefault(); else onDragStart?.(event); }} onDragEnd={onDragEnd} onKeyDown={onKeyDown} onContextMenu={onContextMenu} data-editor-kind={kind} data-editor-clip={id} data-editor-start={start} data-editor-end={end} data-editor-locked={locked || undefined} aria-label={label} aria-current={selected ? "true" : undefined} aria-pressed={selected} title={label} className={`${styles.timelineClip} ${kind === "audio" ? styles.audioClip : styles.visualClip} ${timecode ? styles.referenceClip : ""}`} style={{ left: `${start / duration * 100}%`, width: `${(end - start) / duration * 100}%` }}>
    {/* 时间轴片段：标题、连续帧和真实波形仍共享同一按钮与原修剪事件。 */}
    {/* 时间码只改变信息排布，left/width继续来自工程区间，样板不传时保持原样。 */}
    {/* 文件名可收缩省略，时间码不收缩；完整文件名仍由父按钮title保留。 */}
    {children}<span className={styles.clipName}><span>{label}</span>{timecode && <span data-clip-timecode>{timecode}</span>}</span>{onTrimStart && !locked && (["start", "end"] as const).map(edge => <span key={edge} role="slider" tabIndex={0} aria-label={t(edge === "start" ? "toolBox.editorUi.trimStart" : "toolBox.editorUi.trimEnd")} aria-valuenow={edge === "start" ? start : end} aria-valuemin={0} aria-valuemax={duration} data-clip-trim={edge} className={edge === "start" ? styles.trimStart : styles.trimEnd} onClick={event => event.stopPropagation()} onPointerDown={event => onTrimStart(event, edge)} onKeyDown={event => onTrimKey?.(event, edge)}>{edge === "start" ? "<|" : "|>"}</span>)}
  </button>;
}

"use client";

// 属性外壳、分组和数值字段是正式工作区与样板的同一实现。
// 这里组合展示模型，媒体效果、工程提交与持久化均由外部决定。
import { RotateCcw } from "lucide-react";
import { useState } from "react";
import { useTranslation, t } from "@/i18n";
import { EditorAction, EditorFloatField, EditorGroup, EditorPlaceholder } from "./editor-controls";
import type { EditorMediaAsset, EditorPreviewProject } from "./editor-panels";
import { DEMO_ASSETS, DEMO_CLIPS, DEMO_PROJECT } from "./editor-demo";
import { inspectorFields, propertyGroup, propertyValue, type InspectorTarget, type PropertyField, type PropertyKey } from "./editor-property-model";
import styles from "./editor.module.css";

// 检查器像一张按对象类型裁剪的表单，不是素材浏览器的第二个详情页。
// 外层决定当前选择有哪些片段，内层只组合这些目标能共同使用的字段。
// 视频、图片和音频共用同一组外观，不代表它们的效果处理流程已经共用。
// 正式页按构图能力清单提供回调，独立样板继续演示其他字段的草稿行为。
// 展示默认值时同时说明来源，避免用户把100%误读成已读到真实工程效果。
// 素材库高亮与这里的targets没有绑定，浏览素材不会抢走属性目标。
// 多选目标必须有各自身份，不能把相同文件名当成同一个片段去重。
// 内容滚动归propertyBody，标题、选中名称和来源说明保留在外侧。
// 空选择仍保留R04外壳，紧凑面板打开时不会因为没有字段而高度塌陷。
// 这里不查文件、不读取浏览器视频尺寸，也不推断当前画面有没有成功解码。
// 探测事实已经在asset里，效果默认值则由property-model根据项目决定。
// 这两个来源分开，可以在媒体坏掉时仍保留可理解的选择与项目参数。

// 兼容 asset/clipId 的旧调用处仍显式适配成目标，不再解析固定显示字符串。
// 新调用处传 targets，空数组明确表示无选择，不能回落到演示片段。
// 提交与重置都只通知意图，真实效果未接通时不传回调，字段自动禁用。
interface InspectorProps {
  asset?: EditorMediaAsset | null; clipId?: string; targets?: readonly InspectorTarget[];
  project?: EditorPreviewProject;
  editableKeys?: readonly PropertyKey[]; locked?: boolean; live?: boolean;
  onCommit?: (key: PropertyKey, value: number) => void;
  onReset?: (keys: PropertyKey[]) => void;
}

// targets显式传空数组时优先级高于兼容asset，不能用length判断后退回样例。
// 旧样板还用asset/clipId传单个目标，所以兼容入口在本文件统一适配。
// 正式宿主始终传targets与project，不依赖DEMO默认参数。
// onCommit只传字段键与有限数，不能接收任意数组来改时间线安排。
// onReset接一组当前可见字段，音频重置不会顺便重置画面位置。
// 调用者拥有目标集合，回调不再传文件名来要求它做模糊查找。
// 没有工程保存回调，也没有“应用成功”通知槽，避免表单样板冒充真实效果。
// 这里的可选回调表示明确能力，不应传空函数只为了把disabled去掉。
// 标签映射沿用功能域词条，X/Y明确写出项目像素方向，避免合成一个不可编辑字符串。
// 普通模块的 t 在渲染时调用，语言切换后不会保留模块加载时的旧文字。
const LABELS = { scale: "scale", x: "positionX", y: "positionY", rotation: "rotation", opacity: "opacity", speed: "speed", volume: "volume", fadeIn: "fadeIn", fadeOut: "fadeOut", duration: "duration" } as const;

// 标签表只做字段键到翻译键的映射，范围和精度不在这里重新定义。
// 这样切到英文仍提交同一个scale，而不是把“Scale”文字作为业务字段名。
// 标题和单位分别传给公共字段，数字草稿不需要解析带px的输入文本。
// positionX和positionY是两个独立字段，错误可以准确标到其中一个方向。
// 原来合并成“960,540”的字符串无法独立提交，也无法表达单方向混合值。
// 保留原功能域词条，语言集合继续由项目i18n决定，不新增编辑器专用Context。

// 同一个淡入淡出组同时服务视频与音频，回调绑定的是当前选中目标集合。
// key由选择ID和字段键构成，换对象不会保留前一片段的未提交草稿。
// 分组折叠仍交给 EditorGroup，A/B不共享展开值或字段错误。
// 重置按钮只在有真实样板回调时启用，不用空函数冒充正式效果重置。
// 速度字段继续使用同一数值输入，不另建只有视频可用的第二套草稿逻辑。
// 字段单位和精度由PropertyField配置，当前速度显示两位小数与×单位。
// 范围只在最终确认时校验，用户先输入0仍可继续组成0.5。
// Enter或失焦提交，Escape恢复确认值，不把输入中间态写进片段时长。
// 锁轨让速度、构图与组重置同时禁用，不能让其中一个入口留下旁路。
// 速度组重置通过工程命令恢复1倍，碰撞失败仍保留已确认倍速。
// 淡入淡出继续只读，不能因为组内出现可编辑速度就误开放所有属性。
// 选择不同片段会重建字段草稿，不把上一实例输入到一半的速度带过去。
// 读取实际values后显示确认速度，默认1仅用于没有显式speed的旧片段。
// 业务失败的状态条与非法数值的字段错误属于两个不同边界，不混报成功。
function InspectorSection({ fields, targets, project, onCommit, onReset, editableKeys, locked }: { editableKeys?: readonly PropertyKey[]; locked?: boolean; fields: PropertyField[]; targets: readonly InspectorTarget[]; project: EditorPreviewProject; onCommit?: InspectorProps["onCommit"]; onReset?: InspectorProps["onReset"] }) {
  // 本分组只接非空fields，外层按有效字段的组名生成它，fields[0]因而有来源。
  // 单个分组共享一次重置意图，重置按钮与折叠按钮是兄弟，不嵌套button。
  // 字段key包含目标身份集合，换片段时销毁旧草稿，不把旧输入带到新对象。
  // 顺序也纳入key，因为代表值依赖首目标；改顺序时旧混合草稿不能继续代表原集合。
  // epoch只处理显式重置，不因每次render变化，普通打字不会反复卸载输入。
  // 如果确认值本来是默认值，外层回填相同数字并不足以清掉本地错误草稿。
  // 所以重置后让字段重新初始化，但不更换EditorGroup，展开状态仍保留。
  // 例如缩放确认100时输入abc，再点重置，必须回到100.00而不是继续保留abc。
  // 多选重置逐个目标使用默认值，字段再重新比较是否仍为混合。
  // 分组回调只收到本组字段，不能无意重置用户在另一个分组改好的样板值。
  // 正式页没有onReset，按钮原生禁用，epoch不可能被用户绕过业务边界更新。
  // reason和字段禁用说明来自同一词条，鼠标提示与读屏原因保持一致。
  // onCommit存在时逐字段注入目标明确的函数，公共输入无需认识片段列表。
  // propertyValue对每个字段独立计算mixed，不能因缩放不同让所有字段都显示横线。
  const group = propertyGroup(fields[0].key), reason = t(locked ? "toolBox.editorUi.trackLocked" : "toolBox.editorUi.effectUnavailable");
  const canEdit = (key: PropertyKey) => !locked && (!editableKeys || editableKeys.includes(key));
  const resetEnabled = !!onReset && fields.some(field => canEdit(field.key));
  // 重置既还原确认值，也丢弃本组未确认草稿；默认值没变时仍需一次新的输入生命周期。
  // 只更新字段的key，分组自身不卸载，用户的折叠选择不会因此复原。
  const [epoch, setEpoch] = useState(0);
  // 重置按钮被点击前，浏览器可能先触发字段blur；非法草稿仍会保留错误。
  // 随后reset意图重建字段，错误与草稿才一起被丢弃，不依赖blur校验成功。
  // 如果只setError(false)，非法文本还在，下一次失焦又会重复报错。
  // 如果把整个EditorGroup重新key掉，用户刚收起的组又会被强制打开。
  // 当前只重建组内字段，避免把数值恢复和面板展开混成一份状态。
  // epoch不进入values或项目文档，它是表单生命周期标记，不是媒体参数版本。
  // 目标集合的key与epoch组合，重置后再切对象也不会复用前一目标草稿。
  // 淡入和淡出在同一组，重置本组会同时恢复两者，其他组仍保留。
  // 多选类型交集变化由外层重组fields，不能对已消失字段继续调用重置回调。
  // 正式组还需通过能力和锁校验，不能只因onReset存在就显示可用重置。
  function reset() { onReset?.(fields.map(field => field.key)); setEpoch(value => value + 1); }
  return <EditorGroup title={t(`toolBox.editorUi.${group}`)} action={<EditorAction icon={RotateCcw} label={t("toolBox.editorUi.reset")} compact onClick={resetEnabled ? reset : undefined} disabledReason={!resetEnabled ? reason : undefined} />}>
    {/* 属性组仍通过fields配置渲染同一EditorFloatField，拖值不是X/Y专属控件。 */}
    {/* canEdit先按实际能力和锁定裁剪回调，未接速度效果的输入继续disabled。 */}
    {/* 每个字段key包含目标ID与重置epoch，切换对象和重置会丢弃旧字符串草稿。 */}
    {/* scrub仅把纯UI拖值能力交给公共字段，正式写入仍回调当前组的onCommit。 */}
    {/* focusTone明确使用细线，样板和正式工程不会因不同调用方产生粗细分叉。 */}
    {fields.map(({ key, ...field }) => <EditorFloatField scrub focusTone="subtle" key={`${targets.map(target => target.id).join("|")}:${key}:${epoch}`} {...field} {...propertyValue(targets, project, key)} label={t(`toolBox.editorUi.${LABELS[key]}`)} disabledReason={reason} onCommit={onCommit && canEdit(key) ? value => onCommit(key, value) : undefined} />)}
  </EditorGroup>;
}

// 无选中展示项目事实，不能继续显示scene_02或上一个对象的默认效果参数。
// 分辨率/帧率来自项目，项目时长来自片段最晚结束点，不对素材库时长求和。
// 只读文字不是可编辑输入，避免给项目设置开一个尚未接通的提交入口。
function ProjectProperties({ project }: { project: EditorPreviewProject }) {
  // 项目事实是只读dl，不能将其包装成无回调但看似可调的数值字段。
  // 分辨率决定将来变换的坐标单位，不是当前节目画布的屏幕尺寸。
  // fps取工程时间模型，不因用户最后浏览了24fps素材而自动变成24。
  // 总时长从宿主project传入，删除末段后的缩短应随参数更新展示。
  // 空选择不意味着空工程，因此项目时长可能仍大于零。
  // “未选片段”的提示与“没有共同字段”分开，避免用户误以为工程丢了素材。
  // 数字格式仅影响读取，不提供保存、重新探测或项目设置修改能力。
  // 组件没有缓存上一个片段，因此空态不会残留scene_02的文件名。
  const { t } = useTranslation();
  return <><EditorPlaceholder state="empty" message={t("toolBox.editorUi.noClipSelected")} /><dl className={styles.projectFacts}><dt>{t("toolBox.editorUi.projectParameters")}</dt><dd>{project.width} × {project.height}</dd><dt>{t("toolBox.editorUi.frameRate")}</dt><dd>{project.fps}fps</dd><dt>{t("toolBox.editorUi.duration")}</dt><dd>{project.duration.toFixed(2)}s</dd></dl></>;
}

// 外壳保留 R04 与稳定片段标记，素材选择不能通过传入素材高亮改变属性目标。
// 文件名不承担身份，两个同源实例在目标数组里仍有不同的id。
// 多选只展示类型交集；没有共同字段就明确提示，不随机借用第一项全部属性。
// 正式片段没有覆盖值时提示默认来源，样板有values时说明其只是独立确认值。
// 头部不再依赖可能破损的封面，缺图不会把属性名挤到错误位置。
// editableKeys是已接通的效果清单，live只是说明文字，不能充当写入权限。
// 正式传入五个构图键，样板不传清单时保留原有演示编辑能力。
// 这使同一个FloatField仍能验证速度草稿，而正式速度字段保持只读。
// locked在组级别合并权限，不能仅让画布拒绝拖动而数字仍能修改。
// 组重置以该组至少一个有效可编辑字段为前提，不按onReset存在与否直接启用。
// 音频类型由inspectorFields排除构图组，不用CSS把视频字段藏起来。
// 分离音轨的源素材虽然仍是视频文件，宿主传入的类型已经适配为audio。
// 因此是否显示X/Y由安排通道决定，不由文件扩展名决定。
// 默认中心来自project，正式确认值来自target.values，两者不能互换。
// 多选的混合值继续由原propertyValue计算，不能拿首项确认值盖住混合状态。
// 输入控件持有字符串草稿，检查器只向外回报合法数值。
// Enter和失焦复用同一个字段提交机制，未输入完整的负号不会写工程。
// 字段错误在控件旁显示，不用全局通知打断连续调整。
