export interface EditorMediaAsset {
  id: string;
  name: string;
  kind: "video" | "image" | "audio";
  duration: number | null;
  cover: StaticImageData | string | null;
  state?: "ready" | "loading" | "missing" | "error" | "cancelled";
  sourcePath?: string;
  sourceUrl?: string;
  metadata?: VideoProbeResult;
  notice?: string;
