// 交互由真实会话注入，静态入口不创建手势状态或媒体读取。
// 两个入口继续共享轨道、片段壳和同一滚动坐标，不复制LIVE版时间线。
// 这里只消费意图接口，不引入真实素材导入Hook。
import type { TimelineInteraction } from "./use-live-timeline";
