// R06 工具栏在时间轴滚动视口外固定，轨道内容滚动不会把加轨入口带走。
// 选择、切分、吸附与链接选择全部禁用，不能只画成可点击按钮。
// 吸附未接通时不显示 aria-pressed=true，避免暗示执行层已经启用吸附。
// “适合全部”属于工程时间轴，这里与预览“适应”分开显示。
// 缩放滑条保持固定样例值，disabled 明确说明没有实际视口缩放行为。
// 加减按钮复用同一 EditorAction，不复制图标 hover 和禁用主题色。
// 一组工具可在窄宽度内横向滚动，不缩小为难以命中的图标。
// 工具名称来自双语词条，不靠 title 代替所有可见文案。
// 后续 UI-06 只需注入动作和视口状态，宿主上下区无需重新装配。
// 本阶段不接 keyboard 全局快捷键，文字输入时不会误切分或播放。
// 编辑工具和缩放工具分组，宽度足够时缩放组自然靠右。
// 不实现虚假的 undo 栈，点击样例片段也不会产生项目修改记录。
function TimelineToolbar({ pixels, onZoom }: { pixels: number | null; onZoom: (pixels: number | null) => void }) {
  // 工程视口的放大缩小入口不会复用生成页的分辨率缩放滑条。
  // 因为两个操作改变的对象不同，本轮只共享按钮外壳而不共享执行方法。
  // range 的 40 是滑条外观样例，不表示项目只能显示到 40% 或当前在 12 秒。
  // “适合全部”没有默认开启标记，避免让用户误判页面已算出真实素材范围。
  const { t } = useTranslation();
  return <header data-editor-region="R06" className={styles.timelineToolbar}>
    <EditorAction icon={MousePointer2} label={t("toolBox.editorUi.select")} compact /><EditorAction icon={Scissors} label={t("toolBox.editorUi.split")} /><EditorAction icon={Magnet} label={t("toolBox.editorUi.snap")} /><EditorAction icon={Link2} label={t("toolBox.editorUi.linked")} /><EditorAction icon={Plus} label={t("toolBox.editorUi.addTrack")} />
    <div data-timeline-view-controls className={styles.timelineZoom}><EditorAction label={t("toolBox.editorUi.fitAll")} onClick={() => onZoom(null)} /><EditorAction icon={Minus} label={t("toolBox.editorUi.zoomOut")} compact onClick={() => onZoom((pixels ?? 32) / 1.5)} /><input data-timeline-zoom type="range" min="8" max="256" value={pixels ?? 32} onChange={event => onZoom(Number(event.target.value))} aria-label={t("toolBox.editorUi.timelineZoom")} /><EditorAction icon={Plus} label={t("toolBox.editorUi.zoomIn")} compact onClick={() => onZoom((pixels ?? 32) * 1.5)} /></div>
  </header>;
}

// R08 轨道头只根据明确轨道类型组合有效图标，不把音频“可见”当作静音。
// V1 展示可见与锁定，A1/A2 展示音量、独奏和锁定的未启用状态。
// 锁图标使用打开形状，对应默认未锁定，不复刻概念稿的错误锁状态。
// 轨道名在紧凑模式截断，track 编号始终保留便于定位。
// 同一个模板被三条轨道使用，不为配音与背景音乐复制头部 JSX。
// 所有状态动作暂时禁用，UI-01 不维护三套虚假 muted/solo/locked 状态。
// 独奏 S 是行业缩写，但 accessible label 使用完整翻译名称。
// V1不负责独立音频控制，有内嵌音轨的真实视频仍作为一个视频实例安排。
// 该头部与其内容行是同一个 grid 的相邻单元，纵向滚动天然同步。
// sticky 只固定横向位置，不另建纵向滚动容器或手动同步 scrollTop。
// 视频Eye接入当前实例的隐藏表，按下表示正在参与节目合成。
// 锁图标仍连接原锁表，隐藏和锁定是两份不同工程状态。
// A轨的静音与独奏尚未接混音，所以不能因为视频Eye可用就一起启用。
// 没有onVisibility的静态样板继续禁用该动作，不给假成功反馈。
// 所有视频轨共用TrackHeader，新增V2不会遗漏显隐或误用音量按钮。
// 显隐不删除片段，时间线仍能看到隐藏轨中的安排并重新显示。
// 按钮沿用EditorAction的pressed、焦点、主题和禁用说明。
// 轨道头顺序与内容行仍来自同一tracks，不按Eye状态重新排序。
function TrackHeader({ track, locked, onLock, hidden, onVisibility }: { track: TrackId; locked?: boolean; onLock?: () => void; hidden?: boolean; onVisibility?: () => void }) {
  // A1/A2 的 Volume2 表示当前没有静音，不使用 VolumeX 误画默认静音状态。
  // V1 的 Eye 对应可见状态，而不是音频的静音/独奏替代图标。
  // 当前名称从轨道编号得到确定值，不让未知轨道名回落成虚假的视频轨。
  // 后续增加轨道时应扩展明确模型，不能仅复制一份 V1 模板改显示字。
  const { t } = useTranslation();
  const name = t(isVideoTrack(track) ? "toolBox.editorUi.video" : track === "A1" ? "toolBox.editorUi.voice" : "toolBox.editorUi.music");
  return <div data-editor-region="R08" data-editor-track-head={track} className={styles.trackHeader}><strong>{track}</strong><EditorAction icon={isVideoTrack(track) ? Eye : Volume2} label={t(isVideoTrack(track) ? "toolBox.editorUi.visibility" : "toolBox.editorUi.mute")} pressed={isVideoTrack(track) && onVisibility ? !hidden : undefined} onClick={isVideoTrack(track) ? onVisibility : undefined} compact />{!isVideoTrack(track) && <EditorAction label={t("toolBox.editorUi.solo")} />}<EditorAction icon={locked ? Lock : LockOpen} label={t("toolBox.editorUi.lock")} pressed={onLock ? !!locked : undefined} compact onClick={onLock} /><span title={name}>{name}</span></div>;
}

// R09 所有片段共享位置、选中外框和手柄，内部通过媒体类型换封面或波形。
// 百分比只取 start/end 与项目 duration，不使用素材列表中的源时长。
// 主视频 0–8 与 10–18 秒严格等宽，图片 20–30 秒则更宽。
// 片段主体由可选interaction接入选择和拖动，两端把手仍保持装饰。
// aria-current 表达局部演示选择；选中边框与两侧把手提供额外视觉线索。
// 播放头由外层统一绘制，不在每个片段中单独计算 12 秒的位置。
// 源素材查不到时不伪造视频名称，返回空内容交给后续缺失素材状态接管。
// 音频波形来自 DemoWaveform，只呈示意，不报告采样或 RMS 数据。
// name 一行截断，片段过短时不会挤出自己的工程时间宽度。
// 把手为 aria-hidden 的装饰，不产生未实现的可聚焦拖动入口。
// 素材图片复用背景图资源地址，不在每次渲染复制或重新解码文件字节。
// selected 的比较使用 clip id，素材相同的其他实例未来可独立选择。
// 音轨分离只改变实例的通道用途，不把源素材的kind全局改成audio。
// 可选字段保持静态样板和原视频/GIF调用契约兼容。
// audioDetached属于视频实例；同源其他安排仍可保留自己的声音。
export interface EditorTimelineClip { id: string; assetId: string; track: TrackId; speed?: number; sourceIn?: number; mirrored?: boolean; transform?: ClipTransform; start: number; end: number; audioOnly?: boolean; audioDetached?: boolean; }

// 真实调用传interaction后，片段壳得到选择、拖动和方向键三个独立入口。
// 没有interaction的样板保留原静态选择，不会创建真实工程会话。
// 选择比较clip.id，不能用assetId使同源所有实例同时亮起。
// asset只提供文件名和封面，工程位置只读取clip.start/end。
// 传给壳的duration实际是统一视口范围，不是当前源的时长。
// 这样同长片段即使引用不同帧率素材也具有相同工程宽度。
// 视频缺图复用missing占位，不能错误显示音频波形暗示已抽取音轨。
// 普通视频仍只占V1；只有用户明确右键分离才建立独立A1/A2音轨安排。
// 片段按钮内只放展示节点，播放器按钮仍在预览区，避免嵌套交互冲突。
// 回调绑定明确clip.id，排序或横滚后不会拿数组下标移动错误实例。
// 时间线的横向长度仍来自end减start，连续帧带不参与片段尺寸计算。
// 有真实sourceUrl的视频才启动VideoFilmstrip，样板与缺失源保持原回退。
// sourceIn指向源文件读入点，速度把工程跨度换算成抽样源跨度。
// 仅传入span与sourceIn让平移尽量复用帧缓存，整段移动不意味着内容换了。
// span舍入只用于辅助展示的依赖稳定，不能覆盖工程中的帧精度数据。
// 音频片段不渲染视频帧带，即便它来自带画面的同一个原视频。
// 原素材的metadata保留源帧率，不能为了显示工程帧率而改写该数据。
// 片段实际速度来自记录，未设置时按1倍，旧创建入口不必先补默认字段。
// 是否选中仍按clip.id比较，不能用asset.id让同源所有片段同时描边。
// 修剪候选替代本次渲染的clip范围，但确认工程数组在松手前保持不变。
// 正式回调通过interaction注入；静态样板不能因共享壳增加真实编辑能力。
// 新展示没有第二个onDrop，素材入轨、同类跨轨和碰撞继续沿原一条流程。
// 缺图占位复用EditorPlaceholder，辅助帧带失败也不创建新的错误弹窗体系。
function TimelineClip({ clip, asset, project, selected = false, interaction }: { clip: EditorTimelineClip; asset: EditorMediaAsset; project: { duration: number; fps: number }; selected?: boolean; interaction?: TimelineInteraction }) {
  // 0 秒从内容列 left 开始，不能再加素材区或固定轨道头的像素宽度。
  // start=10/end=18 得到 left=33.333…%、width=26.666…%，保留小数精度。
  // bg_01 从 20 秒开始，直到 30 秒末尾，终点就是内容列的 100%。
  // voice 的 10–16 秒宽度为 20%，与视频 10–18 的 26.666…% 不相等。
  // 背景音乐 0–30 秒覆盖整条音频内容，不能为名称额外加一个最小片段宽度。
  // 描边采用 border-box，选中不会把工程范围往左右各扩 1px。
  // 封面 backgroundImage 使用静态打包 URL，不接收用户任意 CSS 字符串。
  // span 名称与波形是同一片段的组合内容，删除片段逻辑不会分散到两个组件。
  // 将来修剪需要明确的 commit/cancel 契约，本轮没有提前更改 DEMO_CLIPS 数值。
  // 正式V1通过interaction接入LIVE-02；没有该参数的样板仍保持原边界。
  const { t } = useTranslation();
  // 分离音轨只改变当前安排的展示通道，素材行仍是原来的视频类型。
  // 真实音频使用源包络，图标只用于原静态样板，不能用装饰线替代采样。
  // 静态音频素材继续使用原DemoWaveform，避免更改历史样板视觉。
  const kind = clip.audioOnly ? "audio" : asset.kind;
  return <EditorClipShell timecode={asset.sourcePath ? formatEditorTimecode(clip.end - clip.start, project.fps) : undefined} onPointerDown={event => interaction?.grab?.(event, clip.id)} onTrimStart={interaction?.trimStart ? (event, edge) => interaction.trimStart?.(event, clip.id, edge) : undefined} onTrimKey={interaction?.trimKey ? (event, edge) => interaction.trimKey?.(event, clip.id, edge) : undefined} locked={interaction?.lockedTracks?.includes(clip.track)} onContextMenu={interaction?.contextMenu ? event => interaction.contextMenu?.(event, clip.id) : undefined} onSelect={interaction ? () => interaction.select(clip.id) : undefined} onDragStart={interaction ? event => interaction.start(event, "clip", clip.id) : undefined} onDragEnd={interaction?.cancel} onKeyDown={interaction ? event => interaction.keyDown(event, clip.id) : undefined} id={clip.id} label={asset.name} start={clip.start} end={clip.end} duration={Math.max(30, project.duration)} kind={kind} selected={selected}>
    {asset.sourceUrl && !clip.audioOnly && asset.kind === "video" && <VideoFilmstrip asset={asset} sourceIn={clip.sourceIn} span={Number(((clip.end - clip.start) * (clip.speed ?? 1)).toFixed(6))} />}
    {/* 声音槽：仅真实探测素材接入，同源分离音轨与视频复用源峰值，不复制解码。 */}
    {/* sourceIn保持源秒数，跨度乘speed，左右修剪的草稿也走这两个参数。 */}
    {/* 无声源不请求采样；有声但失败与静音分别显示，不能补装饰起伏冒充音频。 */}
    {asset.sourcePath && asset.metadata && <ClipWaveform sourcePath={asset.sourcePath} hasAudio={asset.metadata.hasAudio} sourceIn={clip.sourceIn} span={(clip.end - clip.start) * (clip.speed ?? 1)} />}
    {clip.audioOnly ? <AudioLines size={20} aria-hidden="true" /> : asset.cover ? <span className={styles.clipCover} style={{ backgroundImage: `url("${typeof asset.cover === "string" ? asset.cover : asset.cover.src}")` }} /> : asset.kind === "audio" ? <DemoWaveform /> : <EditorPlaceholder state="missing" message={t("toolBox.editorUi.missing")} compact />}
  </EditorClipShell>;
}

// 轨道头和内容行共同装配，保证两列每行使用同一高度。
// 过滤只选择本轨的片段，不改变 DEMO_CLIPS 或原工程秒数。
// 轨道的 ID 就是业务编号，不以数组索引作为身份。
// R09 的实际起点由 grid 第二列决定，CSS 不能叠加导航偏移。
// 对空隙不添加占位片段，底色显露的宽度才是真实时间空隙。
// 样例轨道均解锁，禁用控件用于未接通状态，不表示轨道已经锁定。
// 分片组件使用 clipId 作为 key，未来重排不会串用选中节点。
// 这个组合没有私有 scrollTop，整个 timelineScroll 是唯一滚动所有者。
// 每一行复用同一TrackRow，轨道限制通过track参数交给共同手势拥有者。
// 音频行也接over，目的是显示不允许放置，而非宣称支持跨轨移动。
// 内部MIME由interaction识别，Files会继续交给外层导入宿主。
// 草稿放在真实片段之后绘制，固定状态栏同时保留文本反馈。
// 轮廓不加入clips数组，所以不会被属性区或总时长误当成新片段。
// 轮廓的left和width除以project.duration，此处传的是同一个range。
// 不同轨道复用坐标公式，不能给音频行另加一段轨道头偏移。
// 片段封面解码失败不改变DOM时间坐标，缺图仍占正确的工程宽度。
// 轨道头与内容行成对返回Fragment，不能把所有头和所有lane拆成两个独立纵向列表。
// 否则动态增加V2时行高、滚动和锁按钮可能错位，用户会锁错轨道。
// 同一个scroll节点拥有横纵滚动，sticky头只固定水平方向，不另设头部scrollTop。
// 候选行也包括同样轨道头，用户能在松手前看见将新增的轨道编号。
// 候选头显示锁按钮但还不是正式轨道，不应借此把候选写入轨道列表。
// TrackRow筛选按track完整编号，不能只按前缀把所有视频片段画到每条视频行。
// 同一素材多次入轨时key仍用clip.id，跨层不会因assetId相同复用错误选中状态。
// 选中判定使用interaction.selectedId，DEMO的clip-02默认只在未接正式交互时使用。
// 新增V2不表示每个视频都复制到V2，只移动或创建用户真正投放的那条实例。
// clip.audioOnly优先于asset.kind决定音轨外观，分离音频仍引用video源元数据。
// 分离音轨与原视频复用同源包络，不能拿DemoWaveform替代采样失败状态。
// 源cover缺失时共享placeholder仍占满同一片段壳，不改变其时间宽度。
// trimDraft只替换目标的start/end显示，正式assets元数据和sourceDuration不因此变短。
// 目标行通过data-editor-track-lane向共同手势提供身份，CSS类名不承载业务权限。
// locked数据属性供展示与证据，实际锁检查仍在共同命令，不能只让背景变灰。
// 目标错误类型也接收hover用于解释不能放置，而drop会再验证类型并拒绝。
// Files不会被timeline内部MIME处理，继续到外层导入，不能自动创建时间线实例。
// 草稿轮廓pointer-events none，避免它挡住下一次dragOver导致落点抖动。
// 轮廓不加入正常片段map，不提供右键菜单或选择，不能误被当成已提交剪辑。
// 轮廓文本显示解析后的合法start，最近空位策略不会缩短其length。
// 同轨碰撞只约束实际目标轨，V1与V2同一时刻覆盖是合法合成需求。
// 视口range至少三十秒是UI留白，不等于工程真实时长增加到三十秒。
// 项目信息条仍从真实clips最大end计算，候选和空轨不参与计时。
// 动态grid行的尺寸与CSS一致，轨道多时由timelineScroll承担纵向滚动。
// scrollbar-gutter stable保留纵滚槽，新增候选行不应改变横向每秒像素数。
// 父层播放头叠层跨所有行，时间位置只有一个，不为每条视频轨各画一个书签。
// 所有轨道头与内容行是同一grid的两列，纵滚时不需要监听器追赶位置。
// 轨道ID决定类型组，V类候选插在视频组末端，A类候选插在音频组末端。
// 候选轨在拖动中可见不等于已经写入工程，取消后不消耗五轨名额。
// 鼠标drop仍将实际目标track传给共同校验，不能只更新DOM所属父节点。
// 碰撞检查限定目标同轨，不把相邻视频层的覆盖当作时间重叠错误。
// 锁轨状态从工程锁表读取，轨道按钮与所有片段不能各自维护一份真假锁。
// 候选轮廓显示解析后的合法位置，默认贴邻居完整边缘，不缩短被拖片段。
// 不同媒体类型的无效落点继续说明原因，不能为显示绿色轮廓跨类型写入。
// 片段名称是展示文字，碰撞与移动始终使用稳定ID与工程区间。
// 真实声音槽读取源峰值，静态样板的DemoWaveform继续与真实素材隔离。
// 横向滚动只移动时间列，轨道头保持在自己的固定列中。
// 纵向候选行增加时预留滚动条空间，避免改变横向密度后丢掉抓取偏移。
// 长工程需要横滚时标尺和片段仍在同一滚动体，不各自同步一份scrollLeft。
function TrackRow({ track, clips, assets, project, interaction }: { track: TrackId; clips: readonly EditorTimelineClip[]; assets: readonly EditorMediaAsset[]; project: { duration: number; fps: number }; interaction?: TimelineInteraction }) {
  return <><TrackHeader track={track} hidden={interaction?.hiddenTracks?.includes(track)} onVisibility={interaction?.toggleVisibility ? () => interaction.toggleVisibility?.(track) : undefined} locked={interaction?.lockedTracks?.includes(track)} onLock={interaction?.toggleLock ? () => interaction.toggleLock?.(track) : undefined} /><div data-editor-region="R09" data-editor-track-lane={track} data-locked={interaction?.lockedTracks?.includes(track) || undefined} onDragOver={event => interaction?.over(event, track)} onDragLeave={interaction?.leave} onDrop={event => interaction?.drop(event, track)} className={styles.trackLane}>{clips.filter((clip) => clip.track === track).map((clip) => { const asset = assets.find(item => item.id === clip.assetId); return asset ? <TimelineClip key={clip.id} clip={interaction?.trimDraft?.id === clip.id ? interaction.trimDraft : clip} asset={asset} project={project} selected={interaction ? clip.id === interaction.selectedId : clip.id === "clip-02"} interaction={interaction} /> : null; })}
    {/* R09：轮廓只显示候选，不插入真正片段；失败原因随落点就近展示。 */}
    {/* 百分比与真实片段、标尺和播放头使用同一个视口范围。 */}
    {interaction?.draft?.track === track && <div data-timeline-draft data-valid={interaction.draft.valid} data-start={interaction.draft.start} className={styles.timelineDraft} style={{ left: `${interaction.draft.start / project.duration * 100}%`, width: `${interaction.draft.length / project.duration * 100}%` }}><span>{interaction.draft.start.toFixed(2)}s · {interaction.draft.reason}</span></div>}
  </div></>;
}

// R07–R09 共享一个内容列：刻度、播放头和片段没有独立左右 padding。
// 为完整 30 秒保留右端刻度，0 与 30 秒标签分别向内对齐避免被裁掉。
// 12 秒播放头位于内容宽度的 40%，不能从整个时间轴含轨道头的宽度计算。
// 播放头叠层 pointer-events:none，后续片段点击不会被竖线拦截。
// 轨道头和刻度分别 sticky，在同一个横纵滚动区内维持共同坐标。
// 内容最小宽度由 CSS 控制，窄容器滚动查看，不把 30 秒片段压到难以辨识。
// 正式行由会话注入片段和视口范围，静态样板继续使用默认DEMO数据。
// 表达工程时间的数值不作为用户可编辑输入，不需要本轮新增全局 store。
// 工具栏固定在滚动视口外，轨道再多也不会带走缩放与适合全部入口。
// section 名称用于读屏和自动化定位，不依赖当前语言的显示文本。
// 标尺的背景细分刻度只是装饰，主刻度标签由明确秒数生成。
// ruler 与 lanes 的 100% 都指同一 grid 列宽，这是布局的关键不变量。
// 真实总长和可编辑视口分开：总长给信息条，range给刻度与所有横坐标。
// 统一range同时决定主刻度、细分背景、片段和播放头，不能只更新标签。
// 固定密度默认32px/s，可在8至256之间调整；适合全部使用真实内容宽。
// minWidth保持至少填满当前时间线容器，宽窗口不会右侧留下未铺满区域。
// 实际lane宽度可能大于32px每秒，手势从真实矩形读取比例以保持准确。
// 轨道头在同一个grid内sticky，内容移动时无需脚本追赶另一条滚动轴。
// 冻结手势期间range不因候选越过末端而改变，鼠标不会追着缩放的尺子跑。
// 松手提交后才重新算工程边界，下一次手势读取新的实际比例。
// 主刻度step随长视口增加，避免大量文字标签拥挤重叠。
// 细分背景用同一个CSS变量，所以35秒视口仍是一秒一格而非30格均分。
// 空工程不画播放头，不能把演示的12秒混入真实空会话。
// currentTime是宿主书签，工程单源播放按真实媒体事件推进；素材试听不推进。
// 轨道由interaction.tracks提供，未接正式交互的样板继续使用默认三条。
// 候选行也经过displayTracks分组，不在音轨下面临时插一个视频层。
// 相同TrackRow同时渲染原轨与候选，不复制轨道头和片段列表结构。
// 新轨候选没有clips，因此不会增加工程时长或显示一段假视频。
// 所有轨道共享project.duration作为显示range，横滚后标尺、片段与落点仍同一坐标。
// 修剪draft只替换同clip.id的显示记录，未松手的候选不流入项目统计。
// TrackHeader用isVideoTrack判断图标，V2等新增视频不能误显示成音频独奏工具。
// 原轨道锁按钮接同一个toggleLock，新增轨道也不会因为名字不是V1而缺保护。
// 设置使用slot注入，展示组件不自行保存名额或读取用户JSON。
// 滚动容器保持唯一，动态增加行交给grid-auto-rows，不增加每轨自己的scrollTop。
// grid首行仍给标尺36像素，其后每轨68像素，头和内容在同一网格行里。
// 原min-height填满剩余空间，但不能再把三个固定轨道高度写进模板。
// 主播放头继续从工程秒数换算，不按轨道数量或选择位置重新定位。
// 剪辑修剪只改变某条区间，viewport zoom仍不改工程时间。
export function EditorTimeline({ clips = DEMO_CLIPS, assets = DEMO_ASSETS, project = DEMO_PROJECT, currentTime = DEMO_PROJECT.currentTime, interaction }: { clips?: readonly EditorTimelineClip[]; assets?: readonly EditorMediaAsset[]; project?: { width: number; height: number; fps: number; duration: number }; currentTime?: number; interaction?: TimelineInteraction }) {
  // ownScroll给静态工程提供同样的视口机制，正式工程则复用手势拥有者的scrollRef。
  // 两者都只把ref接到下面同一个滚动体，不能让缩放和拖动测量不同容器。
  // viewport只管理显示密度，不复制clips或构造另一个时间线store。
  // layoutEffect在新网格提交后恢复左端秒数锚点，不在render同步写scrollLeft。
  // Toolbar接effectivePixels，在适合全部模式也能反映真实视口密度。
  // range在拖动期间由原LIVE手势冻结，候选越过右端不会不断撑长尺子。
  // 正常固定缩放宽度是轨道头加range乘密度，再由minWidth保证填满视口。
  // fit宽度直接百分之百，不靠缩短片段起止消除滚动条。
  // grid第二列为minmax(0,1fr)，长文件名不能凭最小内容宽反向撑大整条时间轴。
  // 三条轨道由同一TrackRow映射，锁定和落点状态通过track参数注入。
  // 轨道头sticky只固定横向位置，和lane仍在同一行里纵向滚动。
  // 因此无需监听两个scrollTop互相同步，避免事件延迟造成上下错位。
  // EditorTimeRuler与所有TrackRow共用range，不能仅修改主刻度标签密度。
  // Playhead也除以相同range，1000px宽的尺子与片段不会采用不同时间分母。
  // 真正可交互的是标尺滑块，贯穿线只是定位显示，不覆盖片段按钮。
  // 空工程没有实际duration，不画一根来自DEMO的十二秒蓝线。
  // 选中描边只在border-box内部增加视觉，不能额外挤宽工程占位。
  // 草稿轮廓不进入clips，所以不会把临时位置统计成正式总时长。
  // 锁定时片段事件与提交门槛都阻止编辑，不能仅靠一层灰色背景。
  // 静态波形仍来自DemoWaveform，仅存在明确的演示数据路径。
  // 正式分离音轨通过ClipWaveform展示真实源包络，采样状态独立于节目播放状态。
  // 可见/静音/独奏按钮尚未接轨道效果，没有回调仍由公共按钮原生禁用。
  // 已有复制、删除、分离音频继续走LIVE菜单，不在工具栏另写一套工程命令。
  // 这里没有启用修剪把手或切刀，选中状态可见不等于具备剪辑业务。
  // 时间轴缩放不影响上区面板布局，容器响应式由workspace独立管理。
  // toolbar固定在滚动体之外，横滚或纵滚都不会带走适合全部入口。
  // tabIndex 只赋给滚动视口，装饰刻度和播放头不会逐个进入 Tab 顺序。
  // 轨道头 sticky 的左边界属于本滚动视口，不是窗口最左侧。
  // 同一列中的 R07/R09 横向滚动完全一致，未来无需用 scroll 事件追赶另一层。
  // 标尺的 30 秒标签向内排版，但定位仍为 end=30，避免末尾多出空白时长。
  // UI-01 只有三条轨道，纵滚机制以容器为边界，未来增加行不会压缩每行高度。
  // 项目信息条在本组件外，不会随着轨道滚动离开可见底部。
  const { t } = useTranslation();
  const range = interaction?.range ?? Math.max(30, project.duration);
  const ownScroll = useRef<HTMLDivElement>(null), scrollRef = interaction?.scrollRef ?? ownScroll;
  const viewport = useTimelineViewport(scrollRef, range, interaction?.cancel);
  useLayoutEffect(() => { viewport.restore(); });
  return <section data-editor-timeline className={styles.timeline} aria-label={t("toolBox.editorUi.timeline")}><TimelineToolbar pixels={viewport.effectivePixels} onZoom={viewport.zoom} />{interaction?.settings}{interaction && <p data-timeline-notice role="status" className={styles.timelineNotice}>{interaction.draft ? `${interaction.draft.start.toFixed(2)}s · ${interaction.draft.reason}` : interaction.notice || t("toolBox.editorUi.timelineHint")}</p>}<div ref={scrollRef} data-editor-timeline-scroll className={styles.timelineScroll} tabIndex={0} aria-label={t("toolBox.editorUi.timeline")}><div className={styles.timelineGrid} style={{ "--timeline-range": range, minWidth: "100%", width: viewport.pixels === null ? "100%" : `calc(var(--track-header) + ${range * viewport.pixels}px)`, gridTemplateColumns: "var(--track-header) minmax(0, 1fr)" } as CSSProperties}>
    <div className={styles.rulerCorner} /><EditorTimeRuler range={range} duration={project.duration} fps={project.fps} currentTime={currentTime} onSeek={interaction?.seek} />
    {displayTracks(interaction?.tracks ?? DEFAULT_TRACKS, interaction?.draggingKind, interaction?.limits).map((track) => <TrackRow key={track} track={track} clips={clips} assets={assets} project={{ duration: range, fps: project.fps }} interaction={interaction} />)}
    {project.duration > 0 && <div data-editor-playhead data-time={currentTime} data-interactive={!!interaction?.seek} className={styles.playheadColumn}><i style={{ left: `${currentTime / range * 100}%` }} /></div>}
  </div></div></section>;
}
// 共用边界包括片段外壳和时间线，真实数据由正式会话通过参数注入。
// TimelineClip 把图片或波形作为 children 注入，不能重画另一套选中边框。
// 音频和视觉片段的 start/end 都使用同一总时长，样式提取不改坐标算法。
// 样板未传interaction时对应固定clip-02，正式时间线按实例ID驱动属性与预览。
// 不允许只把选中边框移走却保留右侧旧属性，这会给用户错误的编辑目标。
// 正式选择覆盖V1和分离音轨；多选属性组合由独立样板验证，未接时间线多选。
// 刻度与片段共同放在 timelineGrid，外壳替换不增加第二个横向滚动体。
// 样板的音频封面仍用示意图；正式音轨使用源峰值，不把两种来源混在一起。
// 原生button按回调决定可用性，实际修剪始终未接通，悬停不会改变源入点。
// 锁定由正式会话注入，静态样板未传回调时保持原禁用边界。
// trimStart/trimEnd 继续是装饰，不提供 draggable 或 pointer handler。
// 后续真实修剪应通过命令与撤销边界，不在公共 CSS 中修改时长。

"use client";

// 正式会话和静态工程复用同一宿主几何，数据由各自调用方提供。
// 这个外壳不导入真实文件能力，样板不会因为共用外壳而读取用户视频。
import { useId, useRef, type ReactNode } from "react";
import { GripHorizontal, PanelLeft, PanelRight, X } from "lucide-react";
import { useTranslation } from "@/i18n";
import { ProjectInfoStrip, ProjectToolbar } from "./editor-chrome";
import { EditorTimeline, type EditorTimelineClip } from "./editor-timeline";
import type { EditorMediaAsset, EditorPreviewProject } from "./editor-panels";
// 工作区只透传时间线意图，不持有另一份片段选中状态。
// 样板与正式入口继续共享同一个上下区高度和滚动布局。
// 新增可选参数没有改变legacy或GIF的媒体编辑接口。
// 上区插槽仍由宿主决定展示素材还是片段源，不在几何外壳内查文件。
// 工程总长通过project传给信息条，视口range由时间线自己消费。
// 两者不混为同一个参数，空白可编辑空间不会被统计成视频长度。
import type { TimelineInteraction } from "./use-live-timeline";
import styles from "./editor.module.css";
import { EditorAction } from "./editor-controls";
import { useWorkspacePanels, useWorkspaceSplit } from "./use-workspace-layout";

// children 仅装上区的素材、预览和属性，不接收整个应用外壳。
// AppShell 仍管理导航、窗口按钮和底部全局状态。
// project 是工程参数，不能从源视频元数据隐式覆盖。
// clips 与 assets 分开传入，空时间线不会因为有素材而自动填片段。
// currentTime 是工程时间，与源播放器 currentTime 不同。
// onImport 只在真实宿主提供；演示宿主不提供就继续禁用。
// busy 表达真实导入等待，不会由外壳自动结束。
// 这份接口不含保存或导出回调，未接通业务不会被意外激活。
// 两种宿主使用同一外框尺寸，回归截图能比较同一几何。
// 事件不根据项目名猜业务，静态与真实身份由调用方显式注入。
// 演示数据不被复制进真实数组，外壳只传递当前参数。
// 轨道素材映射仍由既有 EditorTimeline 实现，不在这里重写行内容。
// 没有新的页面容器滚动所有者，保持原上区与时间线分工。
// height 由现有 workspace grid 分配，不再拼窗口或导航偏移。
// 项目栏的导入入口确保素材栏隐藏时仍可打开系统选择器。
// 拖入覆盖层由真实宿主提供，不给静态工程开放文件拖入。
// 只读信息条使用同一 project，避免预览和底部显示不同的工程总长。
// 分隔条只调整局部布局，未接效果或工程保存的按钮仍保持原生禁用。
// 时间线缩放是局部视口能力；切分、修剪等未接业务仍说明原因。
// 本组件不持有视频元素，所以隐藏或卸载清理由真实播放器承担。
// 不使用 position fixed 覆盖全窗口，应用导航始终可用。
// 这层共享的是布局契约，不合并旧视频工具和新多轨编辑业务。
// 布局观察由局部Hook配对清理，没有新增全局持久化布局状态。
// ReactNode 槽只装对应区域，避免为了复用留下毫无约束的空壳。
interface EditorWorkspaceProps {
  // 具名插槽只注入预览标题的临时面板入口，不复制任何素材行或属性结构。
  // 旧调用者仍可传普通children；正式页与演示工程都使用同一布局控制器。
  children: ReactNode | ((panelActions: ReactNode) => ReactNode);
  project: EditorPreviewProject;
  clips: readonly EditorTimelineClip[];
  assets: readonly EditorMediaAsset[];
  currentTime: number;
  onImport?: () => void;
  busy?: boolean;
  onCancelImport?: () => void;
  // 真实工程注入选择与拖动；未传时样板继续只读，不共用会话数组。
  // 外壳只往同一时间线透传，不复制轨道或把工程规则放进项目栏。
  // 项目总长与视口范围分开，R10只接收真实最晚结束时间。
  timeline?: TimelineInteraction;
}

// R01 固定项目工作栏，导入 busy 在两个按钮处同步反映。
// R02、R03、R04 作为兄弟节点放入同一上区。
// 素材列表滚动不应带走节目控制栏或项目工作栏。
// R05独立占据八像素，指针捕获与键盘事件共用同一布局边界。
// 分隔条通过aria范围说明当前高度，不能以禁用语义掩盖已接通的布局调整。
// R06–R09 使用原时间轴装配，不复制三条轨道 JSX。
// 正式会话传空 clips，仍保留可辨认的空轨道和初始标尺。
// 空工程的实际时长为零，初始三十秒只是未来放置视口。
// R10 不随轨道滚动，工程设置始终可查看。
// 素材时长不能在这里相加为工程时长。
// 共享外壳不直接引用 DEMO 常量，所以真实调用方不会意外读到样图。
// 静态调用方仍可传完整确定性工程，保留原视觉验收基准。
// 没有把弹窗或媒体业务塞进展示外壳。
// 这个组合是真实的两个调用处共用，不是仅为拆分文件创建包装。
// 主题色全部来自原 CSS Module 与语义变量。
// 不为 LIVE-01 新增另一套亮暗主题开关。
// 按钮和占位保留旧组件的可访问名称与禁用说明。
// children 顺序由宿主明确装配，不能按文件类型暗中重排面板。
// 导入结束不会重建整个工作区，源播放器状态仍由其自身 key 控制。
// 正式调用注入LIVE片段，静态调用仍传独立演示数组，两者不共享业务会话。
// 离开路由后外壳与内部组件一起卸载，不永久隐藏整份编辑器。
// 保存状态仍为未保存，不能用共享项目栏宣称已自动持久化。
// 真实视频播放器和演示封面在同一 R03 几何中互斥出现。
// 这层不会创建第二个导航或系统标题栏。
export function EditorWorkspace({ children, project, clips, assets, currentTime, onImport, busy, onCancelImport, timeline }: EditorWorkspaceProps) {
  // 共享的panelActions只放预览标题内的入口，不把完整上区业务搬进布局Hook。
  // children函数由正式页和演示页分别装配，差异是数据和回调，不是重复外框。
  // root测上下预算，upper测横向断点，两份ref对应两个明确几何职责。
  // upperId由useId生成，两个工作区的aria-controls不会误指向同一个固定ID。
  // 入口通过buttonRef记录实际触发按钮，面板关闭能够准确返回本实例。
  // aria-expanded表达临时开合，pressed不用于面板，避免读屏误认为是工具选择。
  // 素材和属性按钮一直来自同一个actions节点，节目源切换不另造一套入口规范。
  // 同一时刻只渲染一个节目预览分支，所以不会产生两个重复focus返回目标。
  // 临时关闭按钮位于上区标题角落，不跟属性体或素材列表一起滚走。
  // Escape先看defaultPrevented，让字段的“取消草稿”优先于“关闭整个面板”。
  // 若字段已经消费Escape，用户仍在面板里查看恢复后的数值，不突然失去上下文。
  // 组按钮等未消费Escape的目标则由workspace关闭，焦点回实际入口。
  // 临时区仅覆盖upper，不影响下方轨道拖动、缩放按钮和底部项目信息条。
  // 显式高度只替换grid行分配，区域顺序与滚动所有者不随调节改变。
  // 仍保留minmax(202px,1fr)保护时间轴，不把可用轨道高度压成不可操作细线。
  // split.max和值来自同一宿主预算，aria范围不能引用浏览器完整窗口高度。
  // 指针down/move/up/cancel都挂在同一分隔节点，捕获释放不会跨组件丢失。
  // 入口和关闭使用EditorAction，主题、禁用原因和焦点规范与其他区域一致。
  // 这里不响应文件拖入，外层正式会话拥有文件路径解析和批次错误恢复。
  // 布局外壳不关心音轨分离，所以公共布局修改不会另改工程编辑规则。
  const { t } = useTranslation();
  const root = useRef<HTMLDivElement>(null), upper = useRef<HTMLDivElement>(null), upperId = useId();
  const panels = useWorkspacePanels(upper), split = useWorkspaceSplit(root);
  const actions = <div className={styles.compactPanels}><EditorAction icon={PanelLeft} label={t("toolBox.editorUi.media")} buttonRef={panels.media} expanded={panels.open === "media"} controls={upperId} onClick={() => panels.toggle("media")} /><EditorAction icon={PanelRight} label={t("toolBox.editorUi.inspector")} buttonRef={panels.inspector} expanded={panels.open === "inspector"} controls={upperId} onClick={() => panels.toggle("inspector")} /></div>;
  return <div ref={root} className={styles.workspace} style={split.height === null ? undefined : { gridTemplateRows: `44px ${split.height}px 8px minmax(202px, 1fr) 30px` }}>
    {/* R01：窄窗口隐藏素材栏时，项目栏仍保留同一个导入入口。 */}
    <ProjectToolbar onImport={onImport} busy={busy} onCancelImport={onCancelImport} />
    {/* R02–R04：临时面板仅覆盖上区；Escape先让字段处理，未消费时才关闭面板。 */}
    <div ref={upper} id={upperId} data-editor-upper data-open-panel={panels.open ?? undefined} className={styles.upper} onKeyDown={event => { if (event.key === "Escape" && panels.open && !event.defaultPrevented) { event.preventDefault(); panels.close(); } }}>{typeof children === "function" ? children(actions) : children}{panels.open && <div className={styles.panelClose}><EditorAction icon={X} label={t("toolBox.editorUi.closePanel")} compact onClick={panels.close} /></div>}</div>
    {/* R05：布局拖动不改变工程，指针取消与Escape都恢复本次调整前高度。 */}
    <div data-editor-region="R05" className={styles.splitter} role="separator" tabIndex={0} aria-orientation="horizontal" aria-valuemin={260} aria-valuemax={split.max} aria-valuenow={Math.round(split.value)} aria-label={t("toolBox.editorUi.resize")} title={t("toolBox.editorUi.resizeHint")} onPointerDown={split.down} onPointerMove={split.move} onPointerUp={split.finish} onPointerCancel={split.finish} onKeyDown={split.key}><GripHorizontal size={20} aria-hidden="true" /></div>
    {/* R06–R10：独立时间轴视口与固定信息条不被上区临时面板覆盖。 */}
    <EditorTimeline clips={clips} assets={assets} project={project} currentTime={currentTime} interaction={timeline} />
    <ProjectInfoStrip project={project} />
  </div>;
}

/* host 读取可用编辑器宽度，导航展开/收起改变父宽时容器查询自然重新计算。 */
/* 不把 main 的导航宽度再减一次，不使用 position:fixed 覆盖全局应用外壳。 */
/* 编辑器默认表面复用工作区颜色，浅蓝、文字和边框跟随现有主题系统。 */
/* 局部强调色沿用 accent，而不是工具页面向 FFmpeg 的 primary 青色覆盖。 */
/* 项目内容不足 544px 高时由 host 滚动，不能压到时间轴和走带按钮消失。 */
/* overscroll 隔离只作用于这个视图，返回普通工具后由原有滚动容器接管。 */
.host { container: video-editor / inline-size; height: 100%; min-width: 0; overflow: auto; overscroll-behavior: contain; color: var(--foreground); background: var(--workspace-surface, var(--background)); --editor-video-fill: color-mix(in srgb, var(--accent-fill) 26%, var(--background)); --editor-audio-fill: color-mix(in srgb, #2ca8ad 32%, var(--background)); --editor-playhead: var(--accent-stroke); }
/* 一套五行 grid 管理整体高度，避免上区和时间轴各自使用 vh 导致高度相加溢出。 */
/* 项目栏 44px、分隔条 8px、信息条 30px 均固定，剩余高度按 1.65:1 分给上下区。 */
/* 44+260+8+202+30=544，最小总高度与 grid 的下限相同，避免产生隐藏的负剩余空间。 */
/* 1600×1000 的 host 有充分高度，素材标题与属性标题不靠视口固定偏移对齐。 */
/* 1280px 边界仍三栏，只有严格小于该值才收起属性，符合文档区间定义。 */
/* 1040px 边界仍保留素材，严格小于才切成节目单区，避免断点重叠。 */
/* 页面改变尺寸不改变项目时长、片段 start/end 或预览暂停时间。 */
/* 缩放视图是后续 UI-06 行为，这里不为填满空间擅自拉长每段工程时长。 */
/* 浏览器的 box-sizing 继承全局 Tailwind 重置，边框包含在区域宽高里。 */
/* 单轨 68px 中片段 48px，顶部 10px 与底部 10px 相等，不出现额外下沉。 */
/* 片段顶部不依赖上一行内容自然高度，音频波形再高也不会挤歪 V1/A1/A2 基线。 */
/* 标尺行 36px 单独计入时间轴 grid，播放头从其中 22px 起贯穿下方内容。 */
/* 轨道头的 opaque 背景使横滚时片段不会透出来，沿用此前 nav 防转场穿透的原则。 */
/* 稀疏工程的时间轴底部可留下中性空区，空区不是额外的轨道或虚构片段。 */
/* 刻度区域没有左右 12px 内边距，原图中的边缘视觉通过标签文本偏移实现。 */
/* 因而 0 秒内容起点与第一个视频片段左边界完全相同，不差一个 padding。 */
/* 内容列与轨道头的合计最小宽度决定内部横滚；紧凑轨道头下该值为 896px。 */
/* 轨道的纵向滚动和节目画面互不影响，滚动不会把项目名带出视口。 */
/* CSS 不设置 will-change 或持续动画，静态样例不会为了装饰产生常驻合成层。 */
/* 使用 cqw 的宽度只在已声明 container 的 host 内解析，不影响普通工具页。 */
/* 搜索框、素材封面和数值字段都使用 border-box，不会增加侧栏的隐含最小宽度。 */
/* 时间轴选中描边也用内边框，保证几何测试可按 start/end 准确验证。 */
/* 焦点样式服务可用导航、纯 UI 控件与滚动入口，静态分隔条不进入 Tab。 */
/* 仅等待图标新增旋转，底部 reduced-motion 规则关闭它而保留状态文字。 */
/* 正常宿主中上区约 62%，接近原图；最低高度分别保障预览和至少一条轨道可见。 */
/* 这些是骨架初始值，后续可拖动分隔条只需替换比例，不改区域 DOM。 */
/* 13px 基础正文沿用应用字体，数字在专属时间码元素中启用等宽。 */
/* min-width:0 允许 grid 列实际收缩，长文件名不能撑开宿主 main。 */
.workspace { display: grid; grid-template-rows: 44px minmax(260px, 1.65fr) 8px minmax(202px, 1fr) 30px; height: 100%; min-height: 544px; min-width: 0; font-size: 13px; }
/* 项目工作栏拥有内部操作，边框只分隔其下方工作区，不画穿应用 nav/head。 */
/* gap 与 padding 均使用既有 4/8/12 梯度，按钮命中区域不随标题变长缩小。 */
/* 名称与菜单可收缩，但导出和真实导航链接保持在工作栏内可达。 */
.projectBar { display: flex; align-items: center; gap: 12px; min-width: 0; padding: 4px 12px; border-bottom: 1px solid var(--border); }
/* 返回、旧版两个真实链接共用样式，操作语义仍由 Link href 决定。 */
/* 焦点轮廓来自现有 accent 语义色，不能仅用 hover 表示可操作。 */
/* 不用按钮的 disabled 颜色覆盖链接，用户能区分可用导航和未接通功能。 */
.navigation { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 32px; flex-shrink: 0; border-radius: 6px; padding: 0 6px; text-decoration: none; }
/* 辅助链接的 hover 仍使用全局主题表面，深色不出现纯白块。 */
/* 焦点用 2px 实线而非阴影，窄屏也能明确看出键盘当前所在位置。 */
.navigation:hover { background: var(--accent); }
/* outline-offset 防止焦点与面板细边框重合，观察和键盘操作更清楚。 */
/* 只有真实可聚焦元素使用该样式，disabled 按钮不伪造可用焦点路径。 */
.navigation:focus-visible, .timelineScroll:focus-visible { outline: 2px solid var(--accent-stroke); outline-offset: -2px; }
/* 项目名可省略，未保存状态保持独立文本，长名称不会覆盖状态。 */
/* 图标由父级固定尺寸，文件/项目语义不借用云同步图案。 */
/* 顶栏主项目区保留最少空间，菜单过长时由后续收缩规则先收起菜单。 */
.projectName { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1; }
/* 标题仅视觉省略，DOM 完整文字和 title 保留可访问名称。 */
/* 文件名等内容不会通过 white-space 的全局覆盖影响其他区域。 */
.projectName strong { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
/* 未保存使用辅助文字，不用成功色或云图标冒充已保存/已同步。 */
/* nowrap 保证它不把 44px 顶栏撑成两行，紧凑模式再按明确规则隐藏。 */
.projectName > span { font-size: 12px; white-space: nowrap; color: var(--muted-foreground); }
/* 菜单在宽工作区并排显示，不为 UI-01 创建未定义的弹层或焦点栈。 */
/* 旧版链接保持靠近导出，方便用户使用仍可用的原单片段处理流程。 */
.projectMenus { display: flex; gap: 4px; }
/* 同一个禁用动作外层持有 title，悬停仍能查看尚未接通原因。 */
/* 禁止容器 flex 压扁按钮，工具栏不足时应滚动或执行明确收缩策略。 */
.actionHint { display: inline-flex; flex-shrink: 0; vertical-align: middle; }
/* 按钮保留 32px 高度与 16px 图标，未接通状态降低饱和度但标签仍可读。 */
/* 不设置 pointer-events:none，原因提示能够响应悬停。 */
/* 共用边框与圆角令项目导出、预览帧导出和属性重置保持一致。 */
/* opacity 不是唯一禁用表达，生产 DOM 同时有原生 disabled 属性。 */
.action { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 10px; border: 1px solid var(--input); border-radius: 6px; background: transparent; color: inherit; white-space: nowrap; cursor: not-allowed; opacity: .62; font-size: 12px; }
/* 图标按钮宽度与高度相同，compact 不会缩成仅 16px 的小命中区域。 */
/* 分组内的间距交给容器，调用方不用覆盖按钮内部 DOM。 */
.iconAction { width: 32px; padding: 0; }
/* 强调按钮映射现有 accent 颜色，保持原图蓝紫气质而不创建第二套主题状态。 */
/* 强调表面的前景色使用应用配对变量，深浅主题都不强行写白字。 */
/* 主色按钮悬停需要配对处理前景与背景，不能保留浅字却改成浅底。 */
/* 选择器同时包含action与accentAction，优先于后面的普通按钮hover规则。 */
/* 普通工具按钮仍使用muted悬停，导入等强调动作保持主色层级。 */
/* 这个局部修复不覆盖图像卡片背景，也不将整站危险按钮统一成主色。 */
/* 细边框只调整border-color，不临时加两像素border改变按钮占位。 */
/* 禁用按钮不进入hover强调，加载中的导入仍由原disabled和aria-busy控制。 */
/* 焦点使用独立细线规则，不能用仅鼠标hover反馈代替键盘可见焦点。 */
/* 浅深主题读取原accent配对变量，不额外假定白字在所有主题都可读。 */
.action.accentAction:not(:disabled):hover { color: var(--accent-fill-foreground, var(--primary-foreground)); background: var(--accent-fill); border-color: var(--foreground); }
.accentAction { color: var(--accent-fill-foreground, var(--primary-foreground)); background: var(--accent-fill); border-color: var(--accent-stroke); }
/* 宽屏素材栏像固定书架：宽度增长有上限，额外空间优先留给中间播放器。 */
/* 素材栏按容器25%增长，到420px停止；不能在超宽窗口继续吞掉一半主区。 */
/* 属性栏继续保持原有300–353px边界，避免通过挤压字段伪造更大的节目画面。 */
/* 剩余列minmax(0,1fr)才是节目区，视频源比例不能反过来撑开整个网格。 */
/* 这里读取实际编辑器容器，导航开合后会自然重排，不额外扣一次导航宽度。 */
/* 1280以下由原紧凑面板规则接管，扩大节目区不改变面板互斥或焦点生命周期。 */
/* 保留position:relative供紧凑入口定位，不覆盖全局应用外壳。 */
.upper { --inspector-width: clamp(300px, 22.3cqw, 353px); position: relative; display: grid; grid-template-columns: clamp(300px, 25cqw, 420px) minmax(0, 1fr) var(--inspector-width); min-height: 0; min-width: 0; }
/* 面板标题为统一 40px，节目、素材和属性顶部基线一致。 */
/* 标题不在列表滚动体中，滚动素材时仍能识别所属区域。 */
/* 14px/600 为面板级标题，不让其字号超过应用级 head。 */
.panelTitle { display: flex; align-items: center; height: 40px; flex-shrink: 0; margin: 0; padding: 0 16px; font-size: 14px; font-weight: 600; }
/* 素材与属性栏只保留细分隔，拒绝为每个区域再堆一个带阴影的浮卡片。 */
/* min-height:0 是内部列表滚动能生效的前提，不允许内容撑高整条上区。 */
/* 面板背景透明继承 host，避免列表和标题变成不一致的白灰块。 */
.mediaPanel, .inspector { display: flex; flex-direction: column; min-height: 0; min-width: 0; }
/* 左栏边界只画在右侧，和主区网格连接，不制造重复双线。 */
/* 该规则局限编辑器模块，不改变 GIF 素材面板或公共卡片。 */
.mediaPanel { border-right: 1px solid var(--border); }
/* 导入和搜索同一行，搜索允许收缩，按钮仍保持自己的最小命中宽度。 */
/* 元素高度由共享 action 和 search 控制，不靠图片加载后撑出布局。 */
.mediaTools { display: flex; gap: 8px; padding: 0 12px; }
/* 搜索标签共享现有 input 边框和主题，不调用默认浏览器搜索装饰。 */
/* min-width:0 防止 placeholder 较长时把整个左栏推宽。 */
.search { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; padding: 0 8px; height: 32px; border: 1px solid var(--input); border-radius: 6px; color: var(--muted-foreground); }
/* 搜索输入保留原生键盘编辑，焦点在下方规则中明确描边。 */
/* 透明背景继承面板，主题切换不会残留原生 input 的白底。 */
.search input { width: 100%; min-width: 0; background: transparent; border: 0; font-size: 12px; }
/* 分类为同一按钮模板，四项在素材区里固定，不跟着长列表滚动。 */
/* 筛选与素材选择分别保存，切换类型不改变时间轴选中对象。 */
.filters { display: flex; gap: 6px; padding: 12px; }
/* 圆角 pill 是分类的稳定几何差异，仍使用共享 action 的禁用和主题机制。 */
/* 去掉实边框只针对素材分类组，不改变项目栏和导入按钮。 */
.filters .action { height: 28px; padding: 0 12px; border-radius: 18px; border-color: transparent; background: var(--muted); }
/* 分类高亮跟随 pressed，选音频后“全部”不能仍保留静态强调。 */
/* 颜色源自 accent-soft，深色下也沿用同一主题变量。 */
.filters .action[aria-pressed="true"] { background: var(--accent-soft); color: var(--accent-text); border-color: var(--accent-stroke); }
/* 唯一素材滚动区位于固定工具区下方，滚动时不带走导入入口。 */
/* list-style 与 margin 在模块内重置，不覆盖其他工具的 ul。 */
.mediaList { flex: 1; min-height: 0; overflow: auto; list-style: none; margin: 0; padding: 0 10px 12px; }
/* 所有媒体共用 70px 行高与间距，视频/图片/音频仅替换左侧内容。 */
/* disabled 不额外降整行透明度，静态素材名称仍需清楚可读。 */
/* 文本收缩由第二列 minmax(0,1fr) 保障，不让长名撑出横向滚动。 */
.mediaItem { display: grid; grid-template-columns: 96px minmax(0, 1fr); align-items: center; gap: 12px; width: 100%; min-height: 70px; margin-bottom: 6px; padding: 4px; border: 1px solid transparent; border-radius: 7px; text-align: left; color: inherit; cursor: not-allowed; }
/* 选中边框与浅底共同出现，保留 aria-current 的可访问选择信息。 */
/* 不给整张图片加彩色滤镜，原参考图内容保持原色。 */
.mediaItem[aria-current="true"] { border-color: var(--accent-stroke); background: var(--accent-soft); }
/* 缩略图和属性封面共用定位外壳，Image fill 不会撑高素材行。 */
/* 相同圆角和裁切规则也服务无图的音频波形槽。 */
.mediaCover, .selectedCover { position: relative; display: flex; align-items: center; justify-content: center; aspect-ratio: 16 / 9; overflow: hidden; border: 1px solid var(--input); border-radius: 6px; color: var(--accent-text); }
/* 说明区是可收缩列，类型行与文件名保持固定的上下关系。 */
/* gap 为 8px 对应原图密度，不让音频文件比图片多出一行空白。 */
.mediaDescription { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
/* 文件名和轨道名统一单行省略，title 保留真实内容。 */
/* 规则列明作用区域，不用全局 strong/span 覆盖影响应用其他页面。 */
.mediaDescription strong, .trackHeader > span, .selectedClip strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* 素材次行用图标加类型文字，不单靠颜色分辨音频与视频。 */
/* 12px 辅助字与现有 muted-foreground 对齐主题。 */
.mediaDescription small { display: flex; align-items: center; gap: 6px; color: var(--muted-foreground); font-size: 12px; white-space: nowrap; }
/* 波形槽不创建真正音频元素，也不在主题变化时重算采样。 */
/* 原始 SVG 只有展示作用，尺寸由使用场景的容器控制。 */
.waveform { width: 100%; height: 100%; min-height: 24px; }
/* 节目区分三行：40px 标题、可收缩画面、64px 控制条。 */
/* 预览的 minmax(0,1fr) 确保任意横纵比都不挤掉控制条。 */
/* padding 只留原图预览的 12px 窄边，面板本身不另加外卡片。 */
.previewPanel { display: grid; grid-template-rows: 40px minmax(0, 1fr) 64px; min-width: 0; min-height: 0; padding: 0 12px 8px; }
/* 中间画布固定填满剩余空间，图片用 object-contain 保持 16:9 原比例。 */
/* 深色是预览未占满部分的中性底，不是编辑器全局主题。 */
.previewSurface { position: relative; display: grid; place-items: center; container-type: size; min-width: 0; min-height: 0; overflow: hidden; border-radius: 5px; background: #222a37; }
/* 预览标题与文件名共享原来的 40px 标题行，不能为长名称另撑一行。 */
/* 文件名不抢占标题和素材返回入口，剩余宽度不足时单行省略。 */
/* min-width:0 让标题内容在原上区网格中收缩，不反过来撑宽宿主。 */
.previewHeading { display: flex; align-items: center; gap: 8px; min-width: 0; }
/* 标题复用 panelTitle，额外名称只作为当前查看对象的辅助说明。 */
/* title 保留全名，视觉省略不意味着素材被重命名或路径被截断。 */
/* muted-foreground 在深浅主题都与现有辅助信息保持同一层级。 */
/* 文件名之后可以有宿主动作槽，不能再用last-child误把名称样式丢掉。 */
/* 名称像一段可收缩空白，动作按自身宽度占位，避免两者互相覆盖。 */
/* 右对齐保持原有标题方向；完整名称依旧由title提供。 */
.previewName { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-align: right; font-size: 12px; color: var(--muted-foreground); }
/* 比例框从 surface 的容器尺寸推导，像把相框放进更大的中性画板。 */
/* width 取可用宽与可用高推算宽的较小值，始终完整保留项目比例。 */
/* 这不是根据窗口固定定位，所以导航开合与窄窗口都走同一条布局规则。 */
.previewFrame { position: relative; display: grid; place-items: center; min-width: 0; max-width: 100%; max-height: 100%; background: #11151d; color: #dbe1ed; }
/* 媒体占位复用现有外壳，画布中只调整继承色与文字宽度。 */
/* 固定深色画布不随浅色主题变成白底，状态文字必须仍能清楚阅读。 */
/* 长反馈允许换行并在本画布内滚动，不挤走走带工具栏。 */
.previewFrame > [data-editor-placeholder] { width: 100%; max-height: 100%; overflow: auto; padding: 12px; color: inherit; text-align: center; overflow-wrap: anywhere; }
/* 控制条在画面下固定，不能按画面高宽比被拉伸成整块空白。 */
/* 最小控件宽度由内部按钮保障，窄宽度不足时本条内部横向滚动。 */
/* nowrap 只作用于时间码和控制按钮，不改变上层 grid 高度。 */
.transport { display: flex; align-items: center; gap: 8px; min-width: 0; overflow-x: auto; padding: 8px 0; }
/* 时间码使用等宽数字，当前值加粗，总时长和帧率保持辅助层级。 */
/* 当前 12 秒与总 30 秒放在同一内容块，不能被工具按钮隔开。 */
.timecode { display: flex; align-items: center; gap: 8px; flex-shrink: 0; white-space: nowrap; font-size: 12px; font-variant-numeric: tabular-nums; }
/* 非当前时间的文本略弱化，但仍使用主题语义色，不硬编码淡蓝文字。 */
/* 后续 UI-07 将对完整状态测对比度，本轮不声称已做颜色可访问性验收。 */
.timecode > span, .timecode small { color: var(--muted-foreground); }
/* 走带按钮作为中间组自然占用剩余空间，左右控制保持原图的关系。 */
/* 窄容器不隐藏播放状态，而是通过 transport 横向滚动查看。 */
.transportActions { flex-shrink: 0; display: flex; gap: 4px; margin-inline: auto; }
/* 属性面板只有左细线，与预览之间不叠加阴影或两条边框。 */
/* 其内独立滚动，外层不设置 overflow:auto 防止标题跟着滚走。 */
.inspector { border-left: 1px solid var(--border); }
/* 当前片段头固定在标题下方，缩略图、文件名和链接图标共享中线。 */
/* 名称占剩余可收缩宽度，图标不会被长文件名推到面板外。 */
.selectedClip { display: flex; align-items: center; gap: 12px; flex-shrink: 0; min-width: 0; padding: 10px 16px 16px; border-bottom: 1px solid var(--border); }
/* 小封面固定 72px 宽，避免右栏标题因 Image fill 而变成任意高度。 */
/* 高度由共享 16:9 比例推导，后续换真实素材仍保持字段起点稳定。 */
.selectedCover { width: 72px; flex-shrink: 0; }
/* 属性内容拥有自己的纵向滚动，不与素材列表共享 scrollTop。 */
/* min-height:0 使其在固定上区高度内正确收缩。 */
.propertyBody { min-height: 0; overflow: auto; }
/* 分组以单条底线区分，不把每个字段另包一张卡片。 */
/* 16px 水平边距沿用原图属性区的紧凑对齐。 */
.propertySection { padding: 8px 16px 12px; border-bottom: 1px solid var(--border); }
/* 组标题、下拉箭头与重置按钮同一行，字段不参与标题高度计算。 */
/* 重置按钮通过 margin-left:auto 靠右，不依赖绝对窗口坐标。 */
.propertySection h3 { display: flex; align-items: center; gap: 6px; margin: 0 0 6px; font-size: 13px; font-weight: 600; }
/* 只选择本组标题直接子动作，避免未来嵌套字段按钮也被错误推右。 */
/* 样式归公共组布局，不由具体“速度/淡入”调用方各写一份。 */
.propertySection h3 > .actionHint { margin-left: auto; }
/* 标签列保持 84px，值列使用剩余空间，所有属性共用同一字段对齐。 */
/* 浮点或单位属于值字符串，本轮没有整数解析或输入校正事件。 */
.propertyRow { display: grid; grid-template-columns: 84px minmax(0, 1fr); align-items: center; gap: 8px; margin-top: 8px; color: var(--muted-foreground); }
/* 属性输入使用现有主题背景，避免原生 disabled 的灰块违背参考图。 */
/* 数值仍可清楚阅读，disabled 语义不以降低文字对比度作为唯一提示。 */
/* 所有字段同为 32px 高，速度/淡入不额外使用默认浏览器下拉。 */
.propertyRow input { min-width: 0; width: 100%; height: 32px; padding: 0 10px; border: 1px solid var(--input); border-radius: 6px; background: transparent; color: var(--foreground); font-size: 13px; font-variant-numeric: tabular-nums; }
/* 分隔槽 8px 来自整体 grid，抓手视觉细，不画成粗重工具栏。 */
/* 目前禁用，不设置 row-resize 鼠标或拖动事件误导用户。 */
.splitter { display: flex; align-items: center; justify-content: center; border-block: 1px solid var(--border); color: var(--muted-foreground); background: var(--muted); }
/* 时间轴自身只有工具栏与滚动体两行，信息条属于更外层的固定 grid 行。 */
/* overflow:hidden 仅隔离内部滚动，不能掩盖 workspace 的最小高度溢出。 */
.timeline { display: flex; flex-direction: column; min-height: 0; min-width: 0; overflow: hidden; }
/* 工具栏固定 44px，控件不足时独立横向滚动，轨道不会被按钮挤高。 */
/* 缩放组在宽容器靠右，紧凑容器保留所有入口的滚动可达性。 */
/* 44px 总高扣掉边框和两侧 4px 留白仍容纳 32px 按钮，避免出现 1px 纵向滚动。 */
.timelineToolbar { display: flex; align-items: center; gap: 8px; height: 44px; flex-shrink: 0; overflow-x: auto; padding: 4px 12px; border-bottom: 1px solid var(--border); }
/* 缩放组与编辑动作之间的自动间距等同原图左编辑、右缩放的排列。 */
/* range 保持固定长度，不能占满整条工具栏挤掉适合全部标签。 */
.timelineZoom { display: flex; align-items: center; gap: 4px; margin-left: auto; padding-left: 12px; }
/* 原生 range 禁用，不通过 CSS 伪造正在缩放的可交互 thumb。 */
/* accent-color 使用已有强调色，主题切换后与播放头仍保持同一视觉体系。 */
.timelineZoom input { width: 80px; accent-color: var(--accent-stroke); }
/* 时间轴唯一横纵滚动视口，轨道头与内容不需要两套 scroll 同步代码。 */
/* Tab 可聚焦滚动区域，用户无需鼠标也能用方向键查看超出部分。 */
/* flex:1 与 min-height:0 将其限制在宿主分配的时间轴预算内。 */
.timelineScroll { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; }
/* 轨道头约 220px，内容至少 720px，宽屏时轨道内容自动填满剩余。 */
/* 第 1 行刻度 36px，三行轨道默认各 68px，余高只留在底部背景。 */
/* grid 总宽度与内容起点共用 --track-header，不能给播放头另写固定像素偏移。 */
/* 内容列上的百分比统一指向 30 秒项目时长，因此所有时间元素天然对齐。 */
.timelineGrid { --track-header: 220px; position: relative; display: grid; grid-template-columns: var(--track-header) minmax(720px, 1fr); grid-template-rows: 36px; grid-auto-rows: 68px; min-width: calc(var(--track-header) + 720px); min-height: 100%; }
/* 左上角同时固定上下左右，防止横向滚动时刻度钻到轨道编号后面。 */
/* z-index 只在时间轴内部排序，远低于应用菜单与通知。 */
.rulerCorner { position: sticky; top: 0; left: 0; z-index: 5; background: var(--workspace-surface, var(--background)); border-bottom: 1px solid var(--border); border-right: 1px solid var(--border); }
/* 标尺与轨道共用第二列，背景每 1/30 宽度表示一秒细分。 */
/* sticky top 使轨道纵向滚动时保留主刻度，不创建独立时间坐标。 */
/* 线条用 input 语义边界色，不采用过重黑线破坏浅色密度。 */
.ruler { position: sticky; top: 0; z-index: 3; background-color: var(--workspace-surface, var(--background)); background-image: repeating-linear-gradient(to right, var(--input) 0 1px, transparent 1px calc(100% / var(--timeline-range, 30))); background-size: 100% 10px; background-repeat: no-repeat; background-position: bottom; border-bottom: 1px solid var(--border); }
/* 主刻度标签按 0/5/10…秒定位，辅助线图案不参与秒数计算。 */
/* 中间标签向左右各半偏移，让文字中心对应精确工程时刻。 */
.ruler > span { position: absolute; top: 6px; transform: translateX(-50%); font-size: 11px; color: var(--muted-foreground); }
/* 首末标签向内容区内部放置，滚动容器不能裁掉 0s 或 30s 的一半。 */
/* 这只影响文本位置，刻度线与片段边界仍使用原来的百分比。 */
.ruler > :first-child { transform: none; padding-left: 4px; }
/* 30 秒位于精确的右边界，不为文字额外增加一段假的工程时长。 */
/* 向左移整段标签使末尾可读，又不改变示例音乐终点。 */
.ruler > span:last-of-type { transform: translateX(-100%); padding-right: 4px; }
/* 轨道头固定在左，行高由同一个 grid 轨道定义，与内容一一对应。 */
/* 背景不透明，横向滚动时片段不会透到轨道编号下面。 */
/* 局部 z-index 仅高于片段和播放头，不覆盖上区或应用导航。 */
.trackHeader { position: sticky; left: 0; z-index: 2; display: flex; align-items: center; gap: 4px; min-width: 0; padding: 0 10px; border-right: 1px solid var(--border); border-bottom: 1px solid var(--border); background: var(--workspace-surface, var(--background)); }
/* 编号不随轨道名截断，V1/A1/A2 仍然可以直接定位。 */
/* 文本强调来自语义色，不区分两套主题中的不同轨道身份。 */
.trackHeader > strong { min-width: 25px; color: var(--accent-text); }
/* 独奏使用 S 全词条可访问标签，但视觉宽度与图标动作一致。 */
/* 缩小的是内部轨道工具排列，不影响项目栏常规按钮尺寸。 */
.trackHeader .action { width: 28px; height: 30px; padding: 0; }
/* 轨道名称只有一个可收缩槽位，按钮不因中文名长短挪动。 */
/* 名称 title 保留完整内容，窄版轨道头仍有可核对的文字。 */
.trackHeader > span { margin-left: 4px; min-width: 0; }
/* 片段的定位上下文就是轨道内容列，背景露出的宽度表示真实空隙。 */
/* 行内上下 10px 留白不影响横向时间宽度，所有轨道保持相同基线。 */
.trackLane { position: relative; min-width: 0; border-bottom: 1px solid var(--border); background: color-mix(in srgb, var(--muted-foreground) 7%, transparent); }
/* 所有媒体片段复用同一外壳：绝对定位、圆角、描边与文本裁切。 */
/* left/width 由秒数计算后注入，CSS 不擅自为文件名增加时间宽度。 */
/* 正式时间轴传真实修剪回调，样板不传时不会出现可操作边缘。 */
.timelineClip { position: absolute; top: 10px; height: 48px; display: flex; align-items: center; min-width: 0; overflow: hidden; border: 1px solid color-mix(in srgb, var(--accent-stroke) 40%, var(--input)); border-radius: 2px; }
/* 视频和图片共享蓝色语义填充，媒体内容本身仍是原色。 */
/* 该 token 仅属于编辑器，不能改变外部模型卡片选中状态。 */
.visualClip { background: var(--editor-video-fill); }
/* 音频使用青绿填充区分媒体类别，并有波形和文件名共同表达身份。 */
/* 边框混合已有 input 色，深色下不出现大面积刺眼荧光。 */
.audioClip { color: var(--foreground); background: var(--editor-audio-fill); border-color: color-mix(in srgb, #2ca8ad 65%, var(--input)); }
/* 封面只占片段左端，不把整个 8 秒内容做成没有来源的多帧缩略带。 */
/* 宽度不足时自然裁切，不能为了完整显示封面推长工程时间区间。 */
.clipCover { align-self: stretch; width: 78px; max-width: 45%; flex-shrink: 0; background-size: cover; background-position: center; border-right: 1px solid var(--input); }
/* 名称在片段里单行裁切，title 可查看完整文件名。 */
/* 内边距属于内容视觉，不改变 timelineClip 的工程起点和终点。 */
.clipName { position: relative; z-index: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0 12px; font-size: 12px; }
/* 音频波形绝对铺在底部，文字留在独立层，不让波形把标签挤出行高。 */
/* opacity 只弱化装饰图形，声音大小并非由此表示或计算。 */
.audioClip > svg { position: absolute; inset: 15px 0 2px; height: 30px; color: #218c95; opacity: .6; }
/* 音频名称靠近顶边，模拟原图波形下面留出的展示区。 */
/* 不使用 button 嵌套，后续统一片段选择可挂在外壳上实现。 */
.audioClip .clipName { align-self: flex-start; padding-top: 4px; }
/* 选中边框通过内描边呈现，不扩大 10–18 秒的布局宽度。 */
/* 左右把手同时提供形状线索，避免选中仅靠填充颜色区分。 */
/* 选中边框固定一像素且使用主题前景混合色，深色呈浅线，浅色呈可辨认细线。 */
/* 悬停或键盘焦点不再叠另一圈粗描边，几何宽度仍与工程起止百分比一致。 */
/* 修剪热区是透明可操作覆盖层，不铺白色厚条，也不改变内部帧带宽度。 */
/* 左右边缘分别使用w-resize和e-resize，鼠标移动到边界才提示对应方向。 */
/* 片段主体仍保留移动语义，不能把整个视频块都设为单向修剪光标。 */
/* 原生边缘命中区域大于可见线宽，细边框不以牺牲可抓取性为代价。 */
/* 不把选中状态写成新的margin，多个相邻片段不会因点击而互相挤开。 */
/* 整体圆角压到两像素，帧带靠近时间边界时不会被大圆角裁出明显缺口。 */
.timelineClip[aria-current="true"], .timelineClip[aria-current="true"]:hover, .timelineClip[aria-current="true"]:focus-visible { border-color: color-mix(in srgb, var(--foreground) 82%, var(--background)); box-shadow: none; outline: none; }
/* 装饰把手固定贴片段内边界，不占据工程时间坐标外的额外宽度。 */
/* 修剪层优先命中边缘，pointerdown阻止冒泡，主体的移动抓取点不会同时被更新。 */
.trimStart, .trimEnd { position: absolute; top: 4px; bottom: 4px; width: 12px; border-radius: 2px; color: var(--foreground); background: color-mix(in srgb, var(--background) 75%, transparent); cursor: ew-resize; opacity: 0; z-index: 2; touch-action: none; }
/* 自定义光标的竖线代表源边界，箭头分别朝外；系统不支持SVG光标时回退到方向缩放。 */
/* 黑色内线外包白色描线，在浅色和深色视频帧上都能识别，不依赖画面背景色。 */
.trimStart { left: 0; cursor: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M17%204v16%20M12%207l-5%205%205%205%20M7%2012h10%22%20fill%3D%22none%22%20stroke%3D%22white%22%20stroke-width%3D%223.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3Cpath%20d%3D%22M17%204v16%20M12%207l-5%205%205%205%20M7%2012h10%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E") 12 12, w-resize; }
/* 右把手位于实际 end 边界内侧，不会跨过 18–20 秒的空隙。 */
/* 选中外观仍保留同一个 clip 宽度，不通过 margin 产生定位误差。 */
.trimEnd { right: 0; cursor: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2224%22%20height%3D%2224%22%20viewBox%3D%220%200%2024%2024%22%3E%3Cpath%20d%3D%22M7%204v16%20M12%207l5%205-5%205%20M7%2012h10%22%20fill%3D%22none%22%20stroke%3D%22white%22%20stroke-width%3D%223.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3Cpath%20d%3D%22M7%204v16%20M12%207l5%205-5%205%20M7%2012h10%22%20fill%3D%22none%22%20stroke%3D%22black%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E") 12 12, e-resize; }
/* 播放头容器覆盖第二列从标尺到三条轨道，排除固定轨道头宽度。 */
/* 它不参与 grid 行高或宽度分配，pointer-events:none 令下方片段事件可达。 */
/* z-index 高于片段低于固定刻度角与轨道头，滚动时不会穿进左侧编号。 */
.playheadColumn { position: absolute; inset: 22px 0 0 var(--track-header); pointer-events: none; z-index: 1; }
/* 40% 来自 12/30 的秒数比值，线宽不计入时间范围。 */
/* 竖线贯穿轨道区，不需要每条轨道各计算一次偏移。 */
.playheadColumn > i { position: absolute; top: 0; bottom: 0; width: 1px; background: var(--foreground); }
/* 顶部小三角标识播放位置，与主线共用颜色，不额外绑定可拖动行为。 */
/* 纯伪元素不会进入 Tab 顺序或被读屏解释为未命名按钮。 */
.playheadColumn > i::before { content: ""; position: absolute; top: -1px; left: -5px; width: 12px; height: 12px; background: var(--editor-playhead); clip-path: polygon(0 0, 100% 0, 100% 60%, 50% 100%, 0 60%); }
/* 固定信息条底线与项目栏同色，表面复用 host，不再加一套任务状态。 */
/* nowrap+ellipsis 保证窄工作区仍为 30px 高，完整参数由 title 可查看。 */
/* 只读参数等宽数字方便和预览控制条核对。 */
.infoStrip { display: flex; align-items: center; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; padding: 0 16px; border-top: 1px solid var(--border); font-size: 11px; font-variant-numeric: tabular-nums; }
/* 三栏时不生成多余侧栏开关占位；紧凑形态只在上区角落呈禁用入口。 */
/* 后续临时面板功能明确后再实现焦点进入/退出，本轮不放一个无效遮罩。 */
/* 入口现在属于预览标题行，宽度按内容计算，不依赖绝对坐标。 */
/* 禁止flex压扁入口，优先压缩前面的辅助文件名。 */
/* 深浅主题与焦点样式继续由已有EditorAction提供。 */
.compactPanels { display: none; flex-shrink: 0; gap: 4px; }
/* 容器不足 1280px 先收起属性，保留素材和节目两栏，不照搬创建页 760px 断点。 */
/* 这只是骨架安全收缩，完整临时属性面板和状态演示保留 UI-07 待办。 */
/* 作用对象仍是编辑器实际宽度，导航开合会自然触发，无需额外监听 window。 */
@container video-editor (width < 1280px) {
  /* 中列继续占剩余，素材初始 280px，属性不再占布局空白。 */
  /* 不用 visibility:hidden，否则会保留一整列造成用户所说的多余空区。 */
  /* 双栏的书架也有上限，空间足够就增加播放器，而非把素材卡拉大。 */
  /* 280px下限可容纳两张112px卡片、间距和滚动条，搜索仍能收缩。 */
  /* 低于1040时沿用原单栏入口，不在窄窗口硬塞两块不可操作的面板。 */
  .upper { grid-template-columns: clamp(280px, 28cqw, 340px) minmax(0, 1fr); }
  /* display:none 同时移除属性展示和焦点路径，节目画面获得其空间。 */
  /* 禁用输入原本不能 Tab，后续可编辑字段也会遵守该容器显示边界。 */
  .inspector { display: none; }
  /* 紧凑入口仅占上区标题行的右侧，绝不盖住下方时间轴。 */
  /* 当前禁用，不显示虚假弹窗或遮挡原工作区的透明层。 */
  /* 只切换显隐，不把按钮从标题流中抽走，避免窄窗名称遮挡。 */
  .compactPanels { display: flex; }
  /* 双栏已有素材，不重复显示“素材”入口，仅保留未实现的属性入口。 */
  /* 入口外层在未来可绑定焦点回退，UI-01 不先维护面板栈。 */
  .compactPanels > :first-child { display: none; }
  /* 项目菜单收起为后续视图任务的边界，返回、旧版与导出继续可达。 */
  /* 并非把保存等能力藏掉：这些功能本轮原本就未接入且明确禁用。 */
  .projectMenus { display: none; }
}
/* 1040px 以下节目优先，临时素材/属性功能留在上区，主轨道永远在下方。 */
/* 没有复制一份移动版时间轴，依旧使用同一 DOM 与滚动坐标。 */
@container video-editor (width < 1040px) {
  /* 单列仍使用可收缩网格，不能以固定宽度把画面撑到 nav 下面。 */
  /* 上区高度不变，收起侧栏不会重置演示播放头和片段。 */
  .upper { grid-template-columns: minmax(0, 1fr); }
  /* 真正移除素材占位，预览不会在左边保留空洞。 */
  /* UI-03 的查询状态后续应由业务组件保持，不依赖永久挂载列表。 */
  .mediaPanel { display: none; }
  /* 单栏两个临时区入口都展示为禁用，不盖住原预览控制条。 */
  /* 这些入口不会跳路由或克隆 AppShell。 */
  .compactPanels > :first-child { display: inline-flex; }
  /* 轨道头只压缩到约定 176px，时间内容仍至少 720px 并允许滚动。 */
  /* 使用同一变量同步刻度角、片段列与播放头内容起点。 */
  .timelineGrid { --track-header: 176px; }
  /* 轨道名可省略，编号与有效状态图标保持可辨认的按钮大小。 */
  /* 不隐藏音频独奏入口导致 A1/A2 与 V1 的语义混乱。 */
  .trackHeader { padding-inline: 6px; gap: 2px; }
}
/* 极窄容器不把顶栏拆成两行，优先保留返回、项目名、旧版链接和导出。 */
/* 该收缩只控制次要文字，后续 UI-07 才做完整键盘和系统缩放验收。 */
@container video-editor (width < 600px) {
  /* 返回图标仍有链接和 title，省略的只是工具箱文本。 */
  /* 未保存仍可通过项目完整文案和禁用原因判断，不用错误的成功状态补位。 */
  .optionalText, .projectName > span { display: none; }
  /* 项目栏留边减为 8px，按钮维持 32px，不能用整体 transform 缩小界面。 */
  /* 文件名继续截断，保留所有真实路由操作的可达性。 */
  .projectBar { gap: 4px; padding-inline: 8px; }
  /* 旧版链接使用更小文字但命中高度不变，让可用功能仍有明确入口。 */
  /* 不把链接变成没有 accessible label 的孤立箭头。 */
  .legacyLink { font-size: 11px; }
}

/* UI-02 局部 token 映射：沿用应用语义色，不新建编辑器主题状态。 */
/* 这些增量规则服务已有工作区和状态样板，作用域不延伸到 GIF。 */
/* 可用按钮恢复 pointer，原有只读骨架的整体灰度不再覆盖局部交互。 */
/* 颜色从 accent-soft/stroke/text 三个现有语义信号读取。 */
/* 背景、描边和文字各有用途，不把深色主题简单反相。 */
/* pressed 样式独立于 hover，所以鼠标离开后开关状态仍可辨认。 */
/* disabled 选择器先排除不可用控件，不能让悬停暗示可以保存。 */
/* focus-visible 只在键盘等需要焦点提示的操作中显示，不制造鼠标常驻描边。 */
/* 片段保留选中内描边，外侧焦点圈另行表达键盘当前位置。 */
/* 素材行和片段不共用布局尺寸，只共享符合语义的焦点规则。 */
/* 标题开关与重置按钮同排，不能把重置嵌入可折叠按钮的命中范围。 */
/* 箭头旋转不参与布局，展开不会让标题和右侧动作突然错位。 */
/* 组内容建立新的格式化上下文，使首行 margin 进入高度测量。 */
/* 这一修正属于调用方内容边界，不改 CollapsiblePanel 的全局动画机制。 */
/* 字段槽同时容纳输入与错误文本，错误增加行高而不叠在下一项上。 */
/* 单位的 flex-shrink 为零，数值输入承担横向收缩。 */
/* 输入的 min-width 沿用零下限，长草稿不会反向撑大属性面板。 */
/* 输入边框由外槽统一绘制，防止原 propertyRow 规则叠出双圈。 */
/* focus-within 覆盖输入和单位整体，用户能看出当前正在编辑哪个数值。 */
/* 错误以文字和 aria-invalid 共同表达，不只依赖红色深浅。 */
/* 错误颜色优先读取应用 destructive，回退色仅用于缺省语义变量。 */
/* 占位容器的 anywhere 断行只处理状态文字，不切碎实际文件名数据。 */
/* compact 只缩小状态密度，图文结构和无障碍状态不变。 */
/* error 与 missing 不共用红色，缺封面不一定代表素材完全不可用。 */
/* Spinner 是装饰动画，完成与否仍由调用方状态决定。 */
/* reduced-motion 关闭旋转后仍保留等待图标与文字，不留下空白按钮。 */
/* 样板网格采用 auto-fit，不创建另一份移动版 JSX。 */
/* min(100%,320px) 保证窄内容区也不会被固定最小列宽撑破。 */
/* 样板页 padding 是本页内容留白，不改变默认编辑器铺满展示区的规则。 */
/* 实例外框仅用于对照两个状态作用域，不增加项目窗口或工程存储。 */
/* 两个实例使用同一套间距，状态不同不应导致控件尺寸不一致。 */
/* action 区域允许换行，长翻译下仍保留所有不可用原因的提示入口。 */
/* sampleLane 明确高度后，绝对定位片段才不会覆盖其后的空态内容。 */
/* 锁定降低透明度只作用于对应片段，不使整条音轨或另一实例变暗。 */
/* 样板没有自设最大高度，统一宿主滚动可同时查看最后的片段和空态。 */
/* 窄屏图文比例不靠 transform 缩小，字体和按钮命中尺寸保持稳定。 */
/* 媒体缩略图继续由原 mediaCover 管尺寸，错误图标不另建一套图片外框。 */
/* CSS Module 名称只描述 UI 角色，不用 isAudio 等业务开关复制表面样式。 */
/* 样板与默认工作区共享局部变量，主题菜单一次切换即可同步所有调用方。 */
/* 同一规则同时用于默认工作区和独立样板，避免仅在样板中修焦点。 */
/* 默认 cursor 不再表示全部不可用，可用性以原生 disabled 为准。 */
.action:not(:disabled), .mediaItem:not(:disabled), .timelineClip:not(:disabled) { cursor: pointer; opacity: 1; }
/* 悬停只在可用控件生效，禁用不能因 hover 看起来重新可点击。 */
/* 选中与按下有明确信号，颜色只是辅助，aria-pressed 同时更新。 */
.action:not(:disabled):hover, .mediaItem:not(:disabled):hover { background: var(--muted); border-color: var(--border); }
/* 按下仍用已有强调色，不改变按钮或素材行尺寸，松开后选中状态继续独立表达。 */
/* 只匹配可用控件，加载与未接通动作不会出现可执行的按压反馈。 */
/* action 同时服务主工作区与样板，修正只维护这一条公共规则。 */
.action:not(:disabled):active, .mediaItem:not(:disabled):active { background: var(--muted); }
/* 片段有各自的视频/音频底色，悬停只改描边，避免抹掉媒体类型。 */
/* 锁定或未接通片段不应用悬停描边，鼠标经过不会暗示可修剪。 */
/* 不增加阴影厚度或移动位置，工程时间坐标与主时间轴保持一致。 */
.timelineClip:not(:disabled):hover { border-color: var(--accent-stroke); }
.action[aria-pressed="true"] { border-color: var(--accent-stroke); color: var(--accent-text); background: var(--accent-soft); }
/* 同一焦点圈覆盖按钮、素材、片段和分组，不依赖特定区域选择器。 */
/* outline-offset 保留边框本身，既有选中边框仍可同时辨认。 */
.action:focus-visible, .mediaItem:focus-visible, .timelineClip:focus-visible, .groupToggle:focus-visible { outline: 1px solid color-mix(in srgb, var(--accent-stroke) 65%, var(--foreground)); outline-offset: -1px; }
/* 分组标题是真按钮，重置保持兄弟节点，键盘不会进入嵌套按钮。 */
/* 开合仅旋转箭头，不通过改变文本宽度推挤右侧动作。 */
.groupToggle { display: flex; align-items: center; gap: 6px; min-height: 32px; text-align: left; border-radius: 4px; }
.closedChevron { transform: rotate(-90deg); }
/* 数值行的顶部 margin 留在测量容器内，否则 scrollHeight 少算首行留白。 */
/* flow-root 阻止父子 margin 合并，折叠容器展开时末行才不会被裁掉。 */
.groupContent { display: flow-root; }
/* fieldBody 包含输入和就地错误，错误出现只增高本行，不覆盖下方字段。 */
/* 单位在输入右侧固定，宽度不足由输入收缩，不让单位挤出面板。 */
.fieldBody { min-width: 0; }
.fieldInput { display: flex; align-items: center; border: 1px solid var(--input); border-radius: 6px; padding-right: 8px; }
/* 已有属性行输入规则不再叠第二圈边框，公共槽负责统一外观。 */
/* disabled 的输入保留可读性，错误与焦点状态由字段槽集中表示。 */
.fieldInput input { border: 0; outline: 0; }
.fieldInput small { flex-shrink: 0; }
.fieldInput:focus-within { outline: none; border-color: color-mix(in srgb, var(--accent-stroke) 65%, var(--foreground)); }
/* 漫画属性选择淡细焦点，视频各调用处不传参数时继续保留原样。 */
/* 通过本组件的语义参数注入，不依赖父页面覆盖私有DOM样式。 */
/* 轮廓仍存在以支持键盘定位，不用outline:none抹去全部焦点反馈。 */
/* 错误的红色边框保持独立，不被这个浅色轮廓覆盖。 */
.propertyRow[data-focus-tone="subtle"] .fieldInput:focus-within { outline: none; border-color: color-mix(in srgb, var(--accent-stroke) 65%, var(--foreground)); }
.fieldInput:has(input[aria-invalid="true"]) { border-color: var(--destructive, #b34b60); }
.fieldError { display: block; margin-top: 4px; font-size: 11px; color: var(--destructive, #b34b60); }
/* 反馈外壳共用图文布局，缺图与错误不再留下破图标或空白。 */
/* 文字可折行，长名状态不会反向撑宽预览或素材列。 */
.placeholder { display: flex; align-items: center; justify-content: center; gap: 8px; min-height: 64px; padding: 8px; color: var(--muted-foreground); font-size: 12px; overflow-wrap: anywhere; }
.compactPlaceholder { width: 100%; min-height: 0; font-size: 10px; }
.placeholder[data-editor-placeholder="error"] { color: var(--destructive, #b34b60); }
/* 加载动画仅表达等待，不驱动任何完成状态或虚构处理百分比。 */
/* 系统减少动态效果时关闭旋转，状态文字仍能完整表达等待。 */
.spinner { animation: editor-spin 1s linear infinite; }
@keyframes editor-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinner { animation: none; } }
/* 独立样板页拥有自己的滚动体，不把长状态清单塞进默认编辑器三栏。 */
/* 两个实例复用同一尺寸规则，窄容器改为单列而不缩小点击目标。 */
.samplePage { padding: 16px; }
.samplePage h1 { font-size: 18px; margin: 12px 0; }
.samplePage > p { font-size: 12px; color: var(--muted-foreground); }
.sampleGrid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)); gap: 16px; margin-top: 16px; }
/* 每个实例的边框是展示范围，不代表创建了第二个编辑器工程。 */
/* 列表不重复铺满整窗高度，样板页统一纵滚，分组内部可按内容扩展。 */
.sampleInstance { min-width: 0; border: 1px solid var(--border); border-radius: 8px; padding: 12px; }
.sampleInstance h2 { font-size: 14px; }
.sampleActions { display: flex; flex-wrap: wrap; gap: 8px; margin-block: 12px; }
/* 片段示例用相同的绝对时间坐标，容器明确高度保证不会压到下一组。 */
/* 锁定外观仅降低当前片段，不影响邻近可选片段或其他实例。 */
.sampleLane { position: relative; height: 68px; margin-top: 12px; background: var(--muted); border-radius: 6px; }
.timelineClip[data-editor-locked] { opacity: .5; }
/* R02 内层 ul 只负责行结构，外层 mediaList 才拥有滚动条。 */
/* 同一滚动槽可装列表或占位，错误/空库时控件仍留在固定位置。 */
/* 清除条件按钮也在该槽里，不绝对定位覆盖列表最后一行。 */
.mediaRows { list-style: none; margin: 0; padding: 0; }
/* 可见焦点沿用其他编辑器控件的轮廓色，深浅主题不硬编码颜色。 */
/* outline 不占布局宽度，不让聚焦时搜索框把导入按钮挤走。 */
/* 只覆盖搜索输入，不更改 GIF 或旧剪辑器的字段样式。 */
.search input:focus-visible { outline: 1px solid color-mix(in srgb, var(--accent-stroke) 65%, var(--foreground)); outline-offset: -1px; }
/* 状态样板也使用真实 MediaPanel，高度固定才能验证列表独立滚动。 */
/* 默认工作区仍遵守 UI-01 的容器断点，这里不提前实现 UI-07 面板抽屉。 */
/* 样板页的窄列保持面板可见，便于单独验收 R02 的内部收缩。 */
.mediaSample .mediaPanel { display: flex; height: 380px; border: 1px solid var(--border); border-radius: 8px; }
/* 样板操作属于演示页，不塞进默认素材区工具栏占用用户空间。 */
/* 同一组按钮允许换行，窄窗口不缩小命中尺寸或产生横向整页滚动。 */
/* 标题与控制区沿用 sampleInstance 的间距，不复制另一套 Card 外观。 */
.mediaSample { min-width: 0; }
/* 节目样板复用默认面板，固定展示高度使状态切换不改变下方选项位置。 */
/* samples 的长页面由 host 滚动，preview 自己只容纳比例框和控制条。 */
/* 窄容器仍用同一个 DOM，不隐藏时间码；控制条原有横向滚动负责可达性。 */
.previewSample > .previewPanel { height: 360px; border: 1px solid var(--border); border-radius: 8px; }
/* 样板素材行是实际 MediaItem，选择状态由该样板单独持有。 */
/* 两列仅是样板的排列差异，缩略图和标题外观不复制素材行规则。 */
/* 极窄列回到单列，长文件名继续由公共行的 minmax 和省略处理。 */
.previewSampleMedia { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 4px; list-style: none; padding: 0; margin: 12px 0 0; }

/* LIVE-01 的素材事实分行显示，长文件名仍沿用同一行控件的省略规则。 */
.mediaMetadata, .mediaNotice { overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
/* 状态不占用封面宽度，错误文字在独立滚动的素材栏内阅读。 */
.mediaNoticeBar, .dropHint { margin: 6px 12px; font-size: 11px; color: var(--muted-foreground); overflow-wrap: anywhere; }
/* 全工作区接收外部文件，不依赖窄屏时隐藏的素材栏。 */
/* 文件导入不挂大遮罩，内部片段拖动不会覆盖上方预览。 */
.workspace { position: relative; }
/* 视频铺进既有预览相框，contain 保留完整画面，不把竖片拉伸为横屏。 */
.liveVideo { width: 100%; height: 100%; min-width: 0; min-height: 0; object-fit: contain; }
/* 解码状态盖在播放器上，保留媒体节点供重试，不丢掉已有元数据。 */
.playerOverlay { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #11151d; overflow: auto; }
/* 未选片段时右侧展示空态，选择素材不会伪造 scene_02 的片段属性。 */
.inspectorEmpty { display: grid; place-items: center; flex: 1; min-height: 0; }

/* LIVE-02候选沿用片段相同的工程列，只叠加轮廓，不拦截真正drop。 */
/* 有效与无效同时用文字和颜色区分，不能让红绿色成为唯一反馈。 */
/* 文字保持单行，完整原因同时在时间线固定状态栏内可读。 */
/* 草稿不改变轨道高度，也不影响原片段的点击与选择。 */
/* negative起点可以露出左缘警告，但只有真正有效结果才允许提交。 */
/* 候选使用虚线边框，与已经提交的实线选中片段有视觉区别。 */
/* 无效候选仍显示预计秒数，方便用户从冲突位置向旁边调整。 */
/* 草稿文本不参与片段名称排版，长原因不会反向拉长占位宽度。 */
/* 草稿宽度与素材实际可显示帧无关，缺封面也能按时长正确落点。 */
/* 固定反馈栏占据独立高度，提示从成功变错误不会挤压轨道行。 */
/* 轨道头和lane的高度由同一grid行统一管理，横滚不产生上下错位。 */
/* 页面导航展开会改变容器宽度，真实手势在resize时取消而非使用旧比例。 */
/* 选中描边在border-box内，视觉突出不会增加碰撞区域。 */
/* 名称采用省略号，但title仍保留完整源文件名供查看。 */
/* 播放头为pointer-events:none，用户能在它覆盖的片段处继续抓取。 */
/* 本轮未加入全屏遮罩，拖动时应用导航仍维持原宿主可用性。 */
/* 拖动反馈只存在于当前编辑器CSS模块，GIF样式不读取这些状态。 */
/* 窄容器保留最小内容宽度，横向滚动归timelineScroll而非整个main。 */
.timelineDraft { position: absolute; top: 8px; height: 52px; border: 1px dashed var(--accent-stroke); background: var(--accent-soft); pointer-events: none; z-index: 2; border-radius: 5px; }
/* 失败仍保留预计时间，用户知道往哪边移动能够避开已有安排。 */
/* 与公共错误占位使用相同的destructive回退，主题未定义该变量时仍有红色警示。 */
.timelineDraft[data-valid="false"] { border-color: var(--destructive, #b34b60); color: var(--destructive, #b34b60); }
/* 只缩短候选文字，不截断固定状态栏，长失败原因仍有阅读位置。 */
/* overflow留在这个展示span，不把整条时间线改成clip掩盖横滚问题。 */
.timelineDraft > span { display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; padding: 4px; font-size: 11px; }
/* 状态栏固定在滚动体外，自动横滚不会带走取消与失败说明。 */
/* 最小高度避免从提示变为成功时重新挤压轨道行。 */
/* 长内容允许自然换行，窄窗口仍可读，不与导出或播放状态混用。 */
.timelineNotice { margin: 0; padding: 3px 12px; min-height: 24px; font-size: 11px; color: var(--muted-foreground); }


/* 属性说明跟随内容换行，不挤占标题或覆盖后面的数值框。 */
/* 来源说明用主题辅助文字，不另写一套只适用于浅色的灰色。 */
/* 允许断开很长的无空格内容，避免英文错误或文件名撑宽右栏。 */
/* 说明在属性滚动体之外，正式页一直可见未接效果的能力边界。 */
.propertyNotice { margin: 8px 12px; color: var(--muted-foreground); font-size: 11px; overflow-wrap: anywhere; }
/* 项目事实使用同一属性滚动区，空选择时不留上一对象的字段。 */
/* 两列对应名称与值，项目分辨率不是额外可编辑表单。 */
/* gap给时间、帧率留读取间隔，不用空格字符在翻译里凑对齐。 */
/* 外侧padding属于内容，紧凑面板打开后依然与公共字段保持相同边距。 */
.projectFacts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 12px; }
/* 样板固定自己的展示高度，正式检查器仍由工作区分配，不新增移动版实现。 */
/* 480px用于稳定展示独立输入样板，超出的组在已有propertyBody内滚动。 */
/* 不把这个高度应用到upper里的正式检查器，避免分隔调整后右栏超出预算。 */
/* 复用同一inspector类才能让深浅表面、字段焦点和省略规则同步生效。 */
.inspectorSample > .inspector { display: flex; height: 480px; border: 1px solid var(--border); }

/* 播放定位只捕获标尺，轨道上的贯穿线仍不拦截片段选择和拖动。 */
/* 三角命中区比可见尖角大，键盘与鼠标都能定位，不给细线绑定整列命中。 */
/* margin-left抵消半个按钮宽，使尖角中心和实际工程时间完全对齐。 */
/* clip-path只裁可见外形，坐标仍按同一个内容列百分比决定。 */
/* touch-action:none将定位交给pointer capture，避免触摸时同时横滚页面。 */
/* 这里用accent-text而不是低对比填充，让深浅主题下的小手柄仍清楚。 */
/* 播放头细线和顶部抓取柄共用时间位置，不使用两套独立left值。 */
/* 白色外观在深色由foreground提供，浅色自动切成可辨认的深线。 */
/* 可见线宽一像素，抓取柄仍保留可用热区，不能只留一个难以点击的像素。 */
/* 柄的margin补偿使中心对准时间坐标，改变外形不移动实际播放时间。 */
/* clip-path只裁外形，不决定拖动落点，落点仍通过公共尺子换算。 */
/* 横向滚动后柄和线随同一列移动，不通过document鼠标位置追赶。 */
/* 锁轨不锁节目书签，查看位置与修改片段内容属于不同权限。 */
/* 播放头是节目起始书签，不改变素材自己的入点或文件内容。 */
.playheadHandle { position: absolute; top: 18px; height: 18px; width: 12px; margin-left: -6px; background: var(--foreground); clip-path: polygon(0 0,100% 0,100% 68%,55% 100%,45% 100%,0 68%); cursor: ew-resize; touch-action: none; }
/* 使用内描边以免三角裁切掉外侧焦点圈，聚焦仍可与当前时间线位置区分。 */
/* 负outline-offset把圈画在按钮内部，不借扩大按钮尺寸改变时间定位几何。 */
/* 焦点颜色取foreground，与手柄填充形成轮廓，不能只依赖悬停色。 */
.playheadHandle:focus-visible { outline: 2px solid var(--foreground); outline-offset: -3px; }
/* 正式手柄在标尺层，静态样板仍保留旧纯装饰三角，两者不叠成两个指针。 */
/* data-interactive只由是否注入seek能力决定，不根据工程名字猜测正式或样板。 */
/* 贯穿竖线仍显示，只关闭旧伪元素三角，不隐藏真正的播放位置。 */
.playheadColumn[data-interactive="true"] > i::before { display: none; }
/* 轨道锁定同时禁用片段回调与拖动，浅深主题使用同一个只读填充。 */
/* 锁轨底色与片段选中边框职责不同，选中不等于当前轨道可编辑。 */
/* 实际权限由原生disabled和提交校验控制，此背景本身不充当安全边界。 */
.trackLane[data-locked] { background: var(--muted); }
/* 缩放滑杆现在是实际视口控制，显示焦点但不改工程像素或媒体帧率。 */
/* 焦点在公共滑杆上，不给整条工具栏添加假的可点击光圈。 */
/* outline不占布局空间，键盘聚焦不会挤动相邻放大和适合全部按钮。 */
.timelineZoom input:focus-visible { outline: 2px solid var(--accent-text); outline-offset: 2px; }

/* 临时面板复用原节点：仅在对应容器断点覆盖上区，不创建body遮罩或第二个导航。 */
/* 同时只允许一个data-open-panel值，互斥由工作区状态控制，时间轴不被覆盖。 */
@container video-editor (width < 1280px) {
  /* absolute的包含块是upper，top/bottom零只填上区，不覆盖AppShell。 */
  /* width上限353沿用常驻属性密度；极窄上区以100%封顶，不向nav外延伸。 */
  /* 背景必须是不透明语义表面，不能让节目视频透过输入文字降低可读性。 */
  /* border-left保留与节目区的边界，z-index只高过上区内容，不是全窗口遮罩。 */
  .upper[data-open-panel="inspector"] > .inspector { display: flex; position: absolute; right: 0; top: 0; bottom: 0; width: min(353px, 100%); z-index: 4; background: var(--workspace-surface, var(--background)); border-left: 1px solid var(--border); }
}
/* 1040以上素材本就常驻，不额外浮起它，避免双栏时重复覆盖节目。 */
@container video-editor (width < 1040px) {
  /* 素材仍在左侧，类型筛选和搜索继续使用原面板的内部滚动归属。 */
  /* display:flex只恢复布局，不创建副本，因此当前筛选和高亮能原样保留。 */
  /* 没有open标记时继续沿用前面的display:none，隐藏控件不参与Tab布局。 */
  /* 两个临时面板通过单一状态互斥，不需要用更高z-index压住另一个已展开层。 */
  .upper[data-open-panel="media"] > .mediaPanel { display: flex; position: absolute; left: 0; top: 0; bottom: 0; width: min(342px, 100%); z-index: 4; background: var(--workspace-surface, var(--background)); border-right: 1px solid var(--border); }
}
/* 关闭按钮位于当前面板标题角落，不随属性体或素材列表滚动离开。 */
/* 这是同一枚按钮的位置规则，面板差异不值得再造另一种关闭控件。 */
/* 只比当前面板高一层，不能挡住时间轴右键菜单或应用窗口控制。 */
.panelClose { position: absolute; right: 6px; top: 4px; z-index: 5; }
/* 左面板与右面板使用相同关闭按钮，只由位置参数选择所在标题角落。 */
/* 左栏不足342px时用100%-38收回按钮，避免关闭入口被裁到窗口外。 */
/* 按钮固定在标题角，不通过transform缩小点击区域来适应窄窗。 */
.upper[data-open-panel="media"] > .panelClose { right: auto; left: min(calc(100% - 38px), 304px); }
/* 分隔命中至少八像素，touch-action阻止系统纵滚与指针捕获争抢。 */
/* user-select只限制抓手区域，素材名称和属性文本仍可按原规则选择或复制。 */
/* ns-resize表示已接通的上下布局动作，不能给未接剪辑把手套这个鼠标样式。 */
.splitter { cursor: ns-resize; touch-action: none; user-select: none; }
/* 焦点使用与其他控件同一主题色，不能只靠鼠标悬停发现布局可调整。 */
/* 内描边保留八像素行高，方向键调节不会因为focus增加额外高度。 */
/* 分隔没有入场动画，减少动态设置下也不会依赖过渡延迟才能操作。 */
.splitter:focus-visible { outline: 2px solid var(--accent-text); outline-offset: -2px; }

/* 节目构图：根层跟项目相框等大，像素值在内部换百分比，不靠屏幕缩放修改工程。 */
/*
 * 项目底色固定黑色，主题只改变编辑器外壳，不能把透明像素染成面板背景色。
 * root铺满现有frame，不在这里设新的宽高比，避免横竖工程互相挤压。
 * crop仅裁媒体像素，选框作为兄弟层保留项目外的操作反馈。
 * 内容层不响应指针，所以实际video不会抢走上方选框的拖动捕获。
 * 交互层透明覆盖自身画面尺寸，项目黑边不是额外的拖动热区。
 * content与selection共享相同left/top/width/height/rotate，避免两套盒模型漂移。
 * 媒体填满的是已按源比例计算的基础盒，因此fill不会在常规探测尺寸下拉伸。
 * 若再对video套一次contain，会出现层内留边，导致选框包含并非真实画面的区域。
 * 绝对定位不改变frame文档流，移动内容不能反过来撑大项目容器。
 * transform-origin保持中心，位置字段无需随角度补偿左上角。
 * 选择细线使用inset阴影，不新增边框宽度，不影响几何测量。
 * focus-visible另有外描边，键盘焦点不会只依赖选中颜色提示。
 * 选中和聚焦是两种状态，失去焦点仍可保留当前片段高亮。
 * aria-disabled配合事件权限检查，视觉光标本身不能阻止程序调用。
 * 锁定仍允许查看和选中，禁止的是构图写入，所以不使用pointer-events:none。
 * touch-action限制本对象手势的浏览器默认行为，不禁用整个工具页滚动。
 * 没有transition拖慢跟手，指针候选即时对应媒体和字段。
 * 没有对选中对象提高层级，未来轨道叠放必须由合成规则明确决定。
 * 透明度只由内容style设置，交互按钮不继承opacity，零透明仍能恢复。
 * 选框没有图像资源或canvas内容，未来输出管线不能采集此操作界面层。
 */
.canvasRoot { position: absolute; inset: 0; pointer-events: none; }
/* 媒体和交互分两层：只裁真实画面，细选框可以跨过项目边界供操作辨认。 */
.canvasCrop { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
/* 基础尺寸已经contain，媒体自身铺满同宽高比例的内容盒，不再进行第二次适配。 */
.canvasContent { position: absolute; transform-origin: center; }
.canvasContent > video, .canvasContent > img { display: block; width: 100%; height: 100%; object-fit: fill; }
/* 透明按钮只承载命中与焦点，不以边框改变真实媒体盒宽高；0透明画面仍能选回。 */
.canvasSelection { pointer-events: auto; position: absolute; padding: 0; border: 0; background: transparent; outline: 0; transform-origin: center; touch-action: none; cursor: move; }
/* 选框使用内部描边，不使基础适配尺寸因边线增减，减少拖动时一像素跳动。 */
.canvasSelection[data-canvas-selection="true"] { box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent-text) 55%, transparent); }
/* 焦点仍清楚可见；锁轨只禁止写入，允许点击辨认当前画面，不把锁当成隐藏。 */
.canvasSelection:focus-visible { outline: 1px solid var(--accent-text); outline-offset: 2px; }
.canvasSelection[data-canvas-locked="true"] { cursor: default; }

/* 修剪把手贴实际边缘，悬停/键盘焦点显示；不再叠加第二圈选中边框。 */
.timelineClip:hover .trimStart, .timelineClip:hover .trimEnd, .trimStart:focus-visible, .trimEnd:focus-visible { opacity: 1; outline: 1px solid var(--border); }
.fieldInput input[data-number-scrub="true"] { cursor: ns-resize; touch-action: none; }
.trackSettings { flex-shrink: 0; padding: 0 12px; border-bottom: 1px solid var(--border); }
.trackSettings p { font-size: 11px; color: var(--muted-foreground); }

/* 节目底板只画一次黑色；各轨透明相框才能透出下面的真实视频。 */
/* 黑底归预览容器，缩小上层素材不会把下层内容擦成灰色。 */
/* 不在每个ClipCanvas设置底色，否则上层相框会遮住所有低层。 */
.previewFrame:has([data-clip-canvas], [data-program-composite]) { background: #000; }

/* 数值框由包含单位的外框提示焦点，内部input不再重复画第二圈。 */
/* 同一个键盘位置只保留一个一像素外轮廓，文字编辑和拖值共用。 */
/* 这里带局部类名，满足CSS Modules纯选择器要求，不改其他输入框。 */
:global(:root) .fieldInput input:focus-visible { outline: none; }

/* 拖动时出现新轨会增加纵向内容，预先预留滚动条位置，横向秒尺才不会突然变窄。 */
/* 不用当前候选反算起点比例，抓取时与落下时始终使用同一条实体标尺。 */
/* 原有横滚仍归timelineScroll，gutter不增加第二个滚动区。 */
.timelineScroll { scrollbar-gutter: stable; }

/* 线条规则说明：按钮保留原边界，焦点只向内画一像素，不叠加发光阴影。 */
/* accent按钮依旧表达主操作，细描边统一并不意味着把导入和危险操作都涂成灰色。 */
/* 悬停颜色取muted，与本地模型更换封面使用同一主题语义变量。 */
/* 按下使用现有aria-pressed，不能为了悬停效果把业务开关状态清掉。 */
/* 片段选中不再叠一个inset光圈，原一像素边框承担选择反馈。 */
/* 细选框不占时间宽度，片段的工程百分比不能被边框粗细撑大。 */
/* 修剪热区保持十二像素易抓取，但显示的边线只有一像素，两者职责不同。 */
/* 热区绝对定位，不参与标题排版，因此短片段仍保持准确的时间占位。 */
/* opacity隐藏把手不禁用其键盘入口，获得焦点后必须明确显露。 */
/* locked片段不挂把手，所以隐藏不是绕开权限的唯一保护。 */
/* ns-resize只提示数字可上下拖，不取代普通文字输入与单位说明。 */
/* touch-action避免拖数触发页面纵向手势，页面其他区域滚动沿用原规则。 */
/* 轨道设置位于滚动区外，内容再多也不带走上限入口与视口工具。 */
/* 时间网格动态行高由同一声明控制，不能给候选行单独改成另一种高度。 */
/* 透明canvasRoot只承担定位；真正裁切由canvasCrop负责。 */
/* 操作层不被内容裁切层剪掉，旋转或移出边界仍能看到选择反馈。 */
/* 内容层按项目边界裁切，操作选框不能进入未来导出画面。 */
/* 多个canvasRoot共用inset，容器变化后所有层仍依同一个项目比例重新投影。 */
/* 画布根关闭pointer-events，未被上层图像覆盖的部分才能命中下层。 */
/* 每层选择按钮重新启用pointer-events，真实图像范围仍可以直接抓取。 */

/* 片段胶片带只画真实采样帧；画布不接收事件，选择与边缘热区仍归同一片段壳。 */
/* 片段长度缩放时整带随宽度变化，标题不压入帧图，源文件不会因展示变化被改写。 */
/* 单张封面仍用于无法解码的回退，不能重复封面并将其宣称为视频的连续帧。 */
.clipFilmstrip { position: absolute; inset: 16px 0 0; width: 100%; height: calc(100% - 16px); pointer-events: none; object-fit: fill; }
/* 标题占独立窄条，像胶片盒上的标签，不遮住下方每个时间采样的画面。 */
/* 背景沿用编辑器视频填充，长文件名只省略显示，不影响工程片段身份。 */
.visualClip .clipName { position: absolute; inset: 0 0 auto; height: 16px; line-height: 16px; text-align: left; font-size: 10px; padding: 0 5px; }
/* 倍速输入复用数值字段的草稿、范围与错误规则；窄预览仍有独立固定槽位。 */
/* 不给整个播放器缩放，确保键盘焦点和图标命中尺寸不受视频比例影响。 */
/* 倍速字段保留数值单位，不用一个只有数字的匿名input让用户猜测含义。 */
/* 字段宽度固定是控制条布局约束，实际值仍可手动输入两位小数。 */
/* 超范围草稿的错误由公共fieldError显示，不能隐藏overflow把错误也裁掉。 */
/* transport本身承担横向滚动，所以右侧适应与帧导出仍可被滚动访问。 */
/* 不为新增字段缩小整个预览区的字号，保持其他按钮命中尺寸。 */
/* 深浅色字段都使用原语义input与foreground，没有新增独立暗色开关。 */
/* 字段的聚焦边框与属性区一致，避免播放器里又出现一圈粗蓝框。 */
/* 这里没有CSS动画驱动时间码，真实播放进度只来自媒体事件。 */
.previewRate { display: flex; align-items: end; gap: 4px; width: 176px; flex-shrink: 0; }
.previewRate > label { flex: 1; min-width: 0; }
/* 键盘或鼠标靠近片段边缘时只有方向光标，整片选中边框不因热区显示而增粗。 */
/* 热区保留十二像素便于抓取，但不再铺一块厚实的背景遮住真实帧。 */
.trimStart, .trimEnd { top: 0; bottom: 0; background: transparent; color: transparent; }

/* 素材网格继续由MediaItem的cards参数开启，列表样板与业务状态保持独立。 */
/* 像一排固定相框：列宽112px不分配尾部余量，面板增宽只增加列数。 */
/* 卡片高94px由74px封面、4px间距和16px文件名组成，不显示额外三行参数。 */
/* 自动填列以实际列表可用宽为准，纵向滚动条出现后也不产生半张横向溢出卡。 */
/* 空库、搜索无结果和导入失败继续使用原占位逻辑，不生成虚构卡片补齐空位。 */
.mediaCards { display: grid; grid-template-columns: repeat(auto-fill, 112px); gap: 12px; align-content: start; }
/* 外按钮不画整卡底色或边框，选中反馈只围绕封面，文件名留在左下方。 */
/* outline不叠加在整卡上；键盘焦点改由下方封面轮廓显示，不取消可见焦点。 */
/* 定位宿主是按钮，两侧短白线只提示选中，不变成能修剪源文件的拖动手柄。 */
/* 按钮overflow可见供短线伸出，源画面裁切仍只由mediaCover管理。 */
.mediaItem.mediaCard { position: relative; display: flex; flex-direction: column; align-items: stretch; gap: 4px; margin: 0; padding: 0; border: 0; border-radius: 0; width: 112px; height: 94px; overflow: visible; background: transparent; outline: none; }
/* 通用行hover规则优先级较低，这里明确覆盖，鼠标经过不会重新铺一整卡灰底。 */
/* 选中状态也保持透明，避免原浅紫底与新细青框同时出现两套视觉反馈。 */
/* 此规则只命中cards派生类，旧列表行的高亮、点击和键盘路径不改变。 */
.mediaItem.mediaCard:hover, .mediaItem.mediaCard[aria-current="true"] { background: transparent; }
/* 横竖源都完整放进同一个暗底槽，object-contain保留画幅，不能裁掉竖视频的上下。 */
/* 封面边框始终预留1px，选中只换颜色，不会让图片和文件名随点击跳位。 */
/* 封面圆角与参考一致，图片和错误占位都被限制在这一小块固定区域。 */
/* 小封面来自导入首帧的有限尺寸JPEG，不为每张卡片挂载隐藏的播放实例。 */
.mediaCard .mediaCover { width: 112px; height: 74px; flex: 0 0 74px; border: 1px solid transparent; border-radius: 5px; background: #222a37; }
/* 青色沿用编辑器已有音轨色相，只用于素材选框，不改变应用全局强调色。 */
/* focus-visible与选中用同一个1px框，键盘经过时也能辨认当前操作对象。 */
/* 缺图卡片仍能显示选框，图片成功与选中身份是两个独立状态。 */
.mediaCard[aria-current="true"] .mediaCover, .mediaCard:focus-visible .mediaCover { border-color: #2ca8ad; }
/* 参考图左右两根短白线属于装饰，pointer-events:none确保内部拖动仍落到按钮。 */
/* top居中于74px封面，不居中于含文件名的整个94px按钮，避免短线位置偏低。 */
/* 辅助线不创建DOM按钮或Tab停靠点，素材选择与时间线修剪不会混淆。 */
/* 只在当前选中时生成；切换素材后原卡片马上恢复普通封面。 */
.mediaCard[aria-current="true"]::before, .mediaCard[aria-current="true"]::after { content: ""; position: absolute; top: 31px; width: 3px; height: 12px; border-radius: 1px; background: #fff; box-shadow: 0 0 1px #222a37; pointer-events: none; z-index: 1; }
.mediaCard[aria-current="true"]::before { left: -2px; }
.mediaCard[aria-current="true"]::after { right: -2px; }
/* 时长小字叠在右上角，深色半透明底使白字在明暗封面上都可辨认。 */
/* 时长不参与flex排版，超长文件名只能在下方省略，不能把角标挤走。 */
/* pointer-events:none使角标不截获素材拖放；它不是可调整区间的字段。 */
/* 源总长通过现有分秒工具格式化，卡片不按项目fps制造第二份时间模型。 */
.mediaDuration { position: absolute; top: 2px; right: 2px; padding: 0 2px; border-radius: 2px; background: rgb(0 0 0 / 55%); color: #fff; font-size: 10px; line-height: 14px; pointer-events: none; }
/* 名称左对齐单行，title仍保留原始文件名，不能为省空间改掉真实素材身份。 */
/* 只限制视觉行高，不截断拖动载荷中的名称；键盘可访问文本仍是完整字符串。 */
/* 正常元数据留在sr-only文本供读屏与状态核对，卡片不展示额外属性行。 */
/* 分辨率、帧率和音轨仍保存在素材metadata，不能因视觉压缩删除探测结果。 */
.mediaCard .mediaDescription { gap: 0; width: 100%; }
.mediaCard strong { font-size: 11px; font-weight: 400; line-height: 16px; }
/* 连续帧真正成功才收起左端单封面，辅助解码失败仍留真实封面作为回退。 */
/* 封面与胶片带不另增片段宽度，时间线几何始终由工程区间控制。 */
.timelineClip:has([data-filmstrip-ready="true"]) .clipCover { visibility: hidden; }

/* 正式媒体片段按参考分为16px标题、40px连续帧和16px声音槽，加两像素边框。 */
/* 源时间仍由原left/width给出，增加高度不会延长片段或改变时间线密度。 */
/* 仅timecode参数开启此变体，静态A/B样板、旧视频与GIF不被改成新行高。 */
/* 使用同一grid自动行高，轨道头和内容共同变高，不能只把某条视频绝对撑出去。 */
/* 一旦正式轨道有媒体，所有轨道保持90px，避免音轨与视频轨头出现纵向错位。 */
/* 空工程仍用原行高，不凭空铺一条演示片段来触发布局。 */
/* 90px行高给74px片段上下各留8px，手柄热区不越过相邻轨道的命中范围。 */
/* 同一个grid同时决定头与内容高度，所以纵滚不需要两列分别监听再追赶位置。 */
/* :has只查看当前时间线实例，旁边独立样板的行高不会因正式工程导入而改变。 */
/* 条件依据真实片段类，不依据鼠标hover，指针移出时不会突然缩回旧行高。 */
.timelineGrid:has(.referenceClip) { grid-auto-rows: 90px; }
.referenceClip { top: 8px; height: 74px; border-radius: 1px; padding: 0; color: #e4f6f6; background: #06494b; border-color: #388b8d; }
/* 青色面板取参考中的声音轨色相，媒体缩略图始终保留源像素，不随主题染色。 */
/* 选中在深色用浅线、浅色用深线，沿用原细框语义，不增加粗outline或布局宽度。 */
/* hover只改变细边框，不能通过降低透明度让帧带或文字突然消失。 */
/* 标题条与波形条有固定底色，因此源画面非常亮时也不会吞掉文件名。 */
.referenceClip .clipName { position: absolute; inset: 0 0 auto; height: 16px; line-height: 16px; padding: 0 5px; display: flex; gap: 6px; align-items: center; text-align: left; font-size: 10px; color: #e4f6f6; background: #06494b; }
/* 名称只截断自己的槽，时长不被长文件名挤掉，窄片段由外壳裁切。 */
/* 不设置标题最小宽度，标题不能反过来撑大按秒计算的工程宽度。 */
/* 标题span不创建新焦点停靠，方向键、菜单键继续由同一片段按钮处理。 */
/* 时长跟随名称排在左侧，不使用space-between把短文件的时间码推到最右端。 */
/* 名称和时长共用16px行高，避免不同数字字形导致两段文字基线错位。 */
/* 字体采用等宽数字仅作用于时间码，文件名仍沿用应用字体。 */
/* 超短片段无法显示完整名称时不另开浮层，用户可用原title或放大时间轴查看。 */
.referenceClip .clipName > span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.referenceClip [data-clip-timecode] { flex-shrink: 0; font-variant-numeric: tabular-nums; }
/* 帧带只占中间40px，底部声音有独立空间；取消请求时仍有原封面可回退。 */
/* canvas缓冲仍由原有界抽帧器管理，CSS不把16:9图片按片段总宽无限拉长。 */
/* 封面回退只占同一中间槽，不会把标题或声音盖住，也不冒充连续帧。 */
.referenceClip .clipFilmstrip { top: 16px; bottom: 16px; height: 40px; }
.referenceClip .clipCover { position: absolute; inset: 16px auto 16px 0; height: 40px; }
/* 分离音轨没有视频帧，声音槽改用标题下面的全部空间，继续同源区间映射。 */
/* 原音符不再叠在波形上，静态演示音轨仍保留自己的旧占位。 */
/* 音轨分离标记不改变源metadata.hasAudio，视频块仍能显示源声音摘要。 */
.referenceClip.audioClip > svg { display: none; }
.referenceClip.audioClip .clipWaveform { top: 16px; height: auto; }
/* 声音包络是真实8kHz下混后的振幅概览，不使用随机线条或CSS动画伪造采样。 */
/* data状态区分加载、失败、无音轨和就绪，失败保留标题与片段操作能力。 */
/* 中心线让真实静音可见；读到的零值保持直线，不能为视觉丰满补出音量。 */
/* pointer-events:none确保底部仍可拖动片段，靠近两侧仍命中原修剪手柄。 */
/* SVG局部1000×32坐标只负责显示，项目像素、源秒和工程帧都不由CSS改写。 */
/* 轻声开方压缩在路径生成时处理，不影响实际播放音量或音高。 */
.clipWaveform { position: absolute; inset: auto 0 0; height: 16px; background: #06494b; color: #71bbbd; pointer-events: none; overflow: hidden; }
.clipWaveform > svg { display: block; width: 100%; height: 100%; fill: currentColor; stroke: currentColor; stroke-width: .5px; }
.clipWaveform > small { display: block; padding: 0 4px; font-size: 9px; line-height: 16px; color: #b2d5d6; white-space: nowrap; }

/* 修剪光标由黑芯白边的箭头与竖线组成，明暗视频画面上都能看清。 */
/* 数据SVG随CSS分发，不依赖网络或用户机器有没有安装某套光标。 */
/* 热点固定在12×12，视觉箭头改变不会让实际抓取边界偏移。 */
/* 不支持自定义光标的平台回退到对应方向的标准resize，修剪行为保持可用。 */

/* 紧凑数值布局由公共字段自己维护，播放器不穿透子节点重写属性组件。 */
/* 一列两行让标签与输入各有完整宽度，不再被属性区84px标签列压扁。 */
/* 默认inline调用不受影响，漫画与属性检查器继续采用原横排。 */
/* 错误文本仍跟输入留在同一字段内，非法自定义速度不会藏到控制栏外。 */
.stackedField { grid-template-columns: minmax(0, 1fr); gap: 2px; margin-top: 0; }
.stackedField > span:first-child { font-size: 10px; white-space: nowrap; }

/* 合成内容与操作各用一层透明底板；顺序只由tracks反向铺放决定。 */
/* 不设isolation或选中z-index，下面选框的状态不能改动上面视频的颜色。 */
/* 两个plane本身不拦指针，只有ClipCanvas中的可编辑选择矩形会恢复命中。 */
/* 没有给选中picture提高z-index，否则下层被选中会篡改合成颜色。 */
/* 节目底板的黑场不跟主题改变，深浅切换只调整外框与操作文案。 */
/* 未就绪时用visibility隐藏内容而非display:none，以保留解码节点生命周期。 */
/* 播放按钮组保持固有宽度，过窄时由原走带区横向滚动，不把图标压成零宽。 */
/* 静音提示使用nowrap，避免中文被挤成竖排而遮住进度或倍速字段。 */
/* 提示放在标题动作槽，素材查看不传该提示，原有声音入口继续独立展示。 */
/* CSS没有在各层设置背景，透明位置才会透出下方真实视频。 */
/* 这组样式不修改应用外壳高度或导航宽度，不给工具创建第二套窗口布局。 */
/* 内容栈与操作栈共用同一inset，响应式变宽不需要复制项目坐标。 */
.compositePlane { position: absolute; inset: 0; pointer-events: none; }
/* 静音说明放在标题动作槽，不依赖悬停提示，文字保持单行。 */
.programMuted { white-space: nowrap; flex-shrink: 0; color: var(--muted-foreground); font-size: 10px; }

"use client";

/** 正式时间线片段菜单：复用创建页公共右键容器和菜单行，按实例注入业务回调。 */
// 菜单像一张当前片段的操作单，只写目标ID，不拥有工程数组。
// 具体复制、删除与分离必须回到会话共同校验，菜单不能直接修改媒体。
// Portal、窗口边缘定位、点击外部及Escape关闭复用ContextMenuShell。
// 不复用旧版剪辑菜单的速度/切分业务，旧菜单处理的是另一种区间结构。
// 保留菜单容器复用而分别注入业务，避免强行把两种工程契约混在一起。
import { ContextMenuShell } from "@/components/context-menu-shell";
import { useTranslation } from "@/i18n";
import { useState } from "react";
import { AudioLines, Copy, Trash2, Wrench, ChevronRight, FlipHorizontal2, RotateCw, Snowflake, Rewind, Crop } from "lucide-react";
// 菜单项直接复用创建图片右键的共享行，去掉普通工具按钮的边框外观。
// 文字、图标、危险项与底部对象名称不再由本菜单单独拼样式。
import { ContextMenuItem, ContextMenuSeparator, ContextMenuCaption, CONTEXT_MENU_SIZE_CLASS } from "@/components/context-menu-item";
import type { EditorMediaAsset } from "./editor-panels";
import type { LiveTimelineClip, TimelineEdit } from "./live-timeline-model";

// trigger仅用于关闭后还原焦点，不会进入工程保存结构或IPC参数。
// id是片段ID，文件名相同的两个实例仍会打开各自的操作单。
// 坐标使用client像素，与公共菜单的fixed定位保持同一个坐标系。
export interface LiveClipMenuAnchor { id: string; x: number; y: number; trigger: HTMLButtonElement; }
// 片段和素材只读传入，菜单不能更改素材元数据来伪造音轨存在。
// clip不存在就不渲染，过期菜单不会回落操作工程中的第一个片段。
// onAction只接受有限动作，不能从显示文字反推要运行哪个方法。
// onClose由拥有锚点的会话提供，不触发导航或清空其他页面实例。
interface LiveClipMenuProps {
  anchor: LiveClipMenuAnchor; clip?: LiveTimelineClip; asset?: EditorMediaAsset;
  onClose: () => void; onAction: (action: TimelineEdit) => void;
}

// 可用性依赖真实probe结果，mp4扩展名与视频封面都不能证明有音轨。
// 已分离视频禁用再次分离，避免重复声音或多次创建同一源音轨安排。
// 音频实例不能再次拆分音轨，仍可以独立复制、删除和水平移动。
// 原始素材没有被删，删除按钮只移除当前工程片段，不删除磁盘文件。
// 复制的含义明确为放到同轨末尾，不暗示存在系统剪贴板或粘贴功能。
// 所有操作继续显示工程未保存提示，不向用户报告虚假的文件写入成功。
// 分离不生成wav；音频片段引用原视频中的真实音轨，支持独立试听。
// 没有生成波形样本时只显示音频图标，不能把演示波形当探测结果。
// 禁用原因通过共享菜单行的title及aria-describedby保留可访问性。
// 不另写一套hover、焦点或主题样式，六类右键入口共享同一个菜单行规范。
// Tab按DOM顺序经过可用按钮，原生disabled会自动跳过不能分离的项。
// ContextMenuShell打开后聚焦第一项；关闭后的焦点由会话恢复到触发片段。
// 底部只保留文件名用于辨认，长名称省略并在title中提供完整内容。
// 浅深主题使用公共容器变量，不新增浮层专属颜色或全局状态。
// 滚动或调整窗口会关闭公共菜单，避免锚点对应到已经移动的旧位置。
// 此处没有媒体元素、异步请求或计时器，关闭不会留下后台导出任务。
// 基本编辑沿用公共菜单行，细边框、危险色和禁用态只维护一份。
// 展开菜单只改变当前浮层的局部状态，不创建工程编辑历史。
// Right键展开、Left键收起，原生Tab可走到已启用的真实动作。
// 子项内联挂载，窄窗口由公共容器内部滚动承接，不把子菜单藏到屏幕外。
// 这与桌面剪辑软件的悬浮二级菜单布局不同，现阶段优先保证相同动作可达。
// 镜像作用于实际视频内容层，选框仍表示原位置和尺寸，不反转拖动坐标。
// 旋转按当前角度加90并归到一周内，属性显示随后读取同一确认值。
// 两项操作保留片段时间和源区间，不能以旋转后重建片段来伪造效果。
// 音频菜单禁用画面动作，并保留明确原因，不把音频图标当成可旋转画面。
// 定格需要独立源帧与时长语义，目前不能用暂停播放器冒充已建立定格片段。
// 倒放需要反向解码或转码，负playbackRate不被当前Chromium可靠支持。
// 裁剪需要非破坏裁切区域与导出一致性契约，不能只缩小选框冒充完成。
// 未接入的三项使用原生disabled，点击不会关闭并显示假的成功通知。
// 已有分离音轨仍依赖真实probe音轨信息，不能只根据文件扩展名判断。
// 锁轨在菜单打开和命令提交处均复核，旧锚点不能绕过新锁状态。
// 菜单只保存片段ID与触发按钮，源路径和私密元数据不会作为菜单标识。
// 重复文件名不会混淆菜单目标，同源不同实例继续使用不同UUID。
// 删除仍只删工程引用，原始素材文件与素材库记录都保留。
// 没有把AI、上传或导出条目伪装为本地基础编辑，业务边界保持明确。
// 关闭后焦点回到仍存在的触发片段，删除后不存在的按钮不强行聚焦。
export function LiveClipMenu({ anchor, clip, asset, onClose, onAction }: LiveClipMenuProps) {
  // 本组件不缓存reason，当前片段完成分离后再次打开会立即显示最新禁用原因。
  // 音频实例已是分离后的通道，禁用说明不能谎称这份媒体“没有音轨”。
  // 只有视频且真实hasAudio为false时，才显示源文件无音轨的说明。
  // 相同素材的另一个未分离实例按自己的标记计算可用性，不继承当前禁用结果。
  // 业务校验仍在applyTimelineEdit执行，菜单禁用只是可发现性而非唯一保护。
  // A1/A2占用情况可能随操作变化，所以最终碰撞不在菜单打开时缓存。
  // 用户点分离遇到轨道占用时，固定状态栏解释重叠并保留原安排。
  // 菜单关闭是界面状态变化，不能拿它当作分离成功的反馈。
  // 复制和删除的按钮仍使用原生button，Enter/Space由浏览器触发相同回调。
  // role使用dialog，配合普通Tab路径，不伪称实现了原生menu的方向键选择协议。
  // 菜单里的说明文字不带tabIndex，不会夹在每个操作之间形成无意义焦点站点。
  // disabled的分离项不会响应程序click，也不会在正常Tab顺序里占位。
  // 图标与文字同时显示，音频动作与删除动作不只靠颜色区分。
  // 删除的作用由菜单容器提示限定到工程片段，用户不必猜测是否会删源文件。
  // 容器宽度为188px，长操作名省略，原生按钮的无障碍名称保留完整值。
  // 标题是用户文件名，不送入翻译器，也不把它当作菜单动作身份。
  // 不显示尚未接通的修剪/切分条目，避免新增一套无效操作清单。
  // 旧版区间菜单仍拥有原来的速度与效果规则，这里只共享稳定的外壳机制。
  const { t } = useTranslation();
  const [basic, setBasic] = useState(false);
  if (!clip) return null;
  const reason = clip.audioOnly ? t("toolBox.editorUi.alreadyAudio") : clip.audioDetached ? t("toolBox.editorUi.alreadyDetached") : !asset?.metadata?.hasAudio ? t("toolBox.editorUi.noAudioTrack") : undefined;
  return <ContextMenuShell role="dialog" x={anchor.x} y={anchor.y} label={t("toolBox.editorUi.clipActions")} onClose={onClose} className={CONTEXT_MENU_SIZE_CLASS}>
    {/* 片段右键：同一组按钮按真实通道能力注入回调，未实现项不出现在菜单里。 */}
    <div data-live-clip-menu title={t("toolBox.editorUi.detachHint")}>
      <ContextMenuItem icon={AudioLines} label={t("toolBox.editorUi.detachAudio")} disabledReason={reason} onClick={() => onAction("detach")} />
      <ContextMenuItem icon={Copy} label={t("toolBox.editorUi.duplicateAtEnd")} onClick={() => onAction("duplicate")} />
      <ContextMenuSeparator />
      {/* 基础编辑：复用同一菜单行，展开项支持点击和键盘，不复制按钮外观。 */}
      <ContextMenuItem icon={Wrench} label={t("toolBox.editorUi.basicEdit")} aria-expanded={basic} aria-haspopup="menu" onClick={() => setBasic(value => !value)} onKeyDown={event => { if (event.key === "ArrowRight") { event.preventDefault(); setBasic(true); } }}><ChevronRight size={14} /></ContextMenuItem>
      {basic && <div role="menu" data-clip-basic-menu onKeyDown={event => { if (event.key === "ArrowLeft") { event.preventDefault(); setBasic(false); } }}>
        <ContextMenuItem icon={FlipHorizontal2} label={t("toolBox.editorUi.mirror")} disabledReason={clip.audioOnly ? t("toolBox.editorUi.visualOnly") : undefined} onClick={() => onAction("mirror")} />
        <ContextMenuItem icon={RotateCw} label={t("toolBox.editorUi.rotate90")} disabledReason={clip.audioOnly ? t("toolBox.editorUi.visualOnly") : undefined} onClick={() => onAction("rotate")} />
        <ContextMenuItem icon={Snowflake} label={t("toolBox.editorUi.freezeFrame")} disabledReason={t("toolBox.editorUi.basicUnavailable")} />
        <ContextMenuItem icon={Rewind} label={t("toolBox.editorUi.reverse")} disabledReason={t("toolBox.editorUi.basicUnavailable")} />
        <ContextMenuItem icon={Crop} label={t("toolBox.editorUi.crop")} disabledReason={t("toolBox.editorUi.basicUnavailable")} />
      </div>}
      <ContextMenuSeparator />
      <ContextMenuItem icon={Trash2} destructive label={t("common.delete")} onClick={() => onAction("delete")} />
      <ContextMenuCaption>{asset?.name ?? ""}</ContextMenuCaption>
    </div>
  </ContextMenuShell>;
}

/** 真实V1的纯计算：按项目帧放置，创建与移动共用同一碰撞门槛。 */
// 素材像货架上的原件，片段像借用原件的一张安排表；移动安排不改文件。
// 所有位置存秒数，先换到整数帧再比较，避免浮点尾差制造假重叠。
// DOM坐标只在交互边界换算，业务计算不依赖窗口、导航宽度或浏览器缩放。
import { DEFAULT_TRACKS, DEFAULT_TRACK_LIMITS, nextTrack, isVideoTrack, sameTrackKind, type TrackId, type TrackLimits } from "./timeline-track-model";
import type { EditorMediaAsset } from "./editor-panels";
import type { EditorTimelineClip } from "./editor-timeline";

// sourceDuration保留ffprobe事实，end-start是向上取整后的项目占位。
// 两者不同不表示发生了转码或补帧，源文件仍保持原样。
// sourceIn本轮固定为零，后续修剪不能误把工程start当作源入点。
// id属于实例，assetId属于素材，同一个assetId可以引用多次。
// 以3.25秒的视频为例，30fps工程需要98帧占位，片段长度就是98/30秒。
// 素材列表仍显示原探测时长3.25秒，不能把98/30写回源信息。
// sourceDuration记录这份事实，后续解码器无需反推取整前的值。
// sourceIn是源文件内部的起点，工程中移动到10秒也仍从源0秒看起。
// 继承的start/end则是工程坐标，两套时间不能互相覆盖。
// 视频封面属于asset，片段只存引用，重复入轨不会复制Base64封面。
// 多个片段修改的是各自的小记录，共享源文件仍由素材会话管理。
// 这里的数据结构不包含播放器对象，能够作为纯业务函数的输入。
// 也不包含File对象，浏览器拖放结束后不会因此扣住文件载荷。
// 片段ID在创建意图发起时产生，鼠标每次hover不会制造另一份身份。
// audioOnly是对源音轨的独立安排，audioDetached使原视频实例保持静音。
// 它们属于工程引用，不会删除原文件中的音轨，也不复制视频字节。
// 同源其他视频实例不受影响，用户仍可在素材库查看完整原文件。
export interface LiveTimelineClip extends EditorTimelineClip { sourceDuration: number; sourceIn: number; }
// 创建需要调用者提供新身份；验证预览不能偷偷生成并浪费另一份UUID。
// 移动只接收片段身份，不允许顺便替换源素材或轨道。
// 两种意图都经过同一个函数，不在键盘和鼠标中各写碰撞规则。
// start是候选秒数，还不是已经提交的有效位置。
// add的id用于新的安排，assetId用于找到原件，这是两个不同的必需身份。
// move沿用旧安排的id，不能通过传另一个assetId偷换其内容。
// 调用者不能给命令指定轨道，当前创建只产生V1安排。
// 这样键盘末尾添加与鼠标拖入不会在轨道默认值上出现分歧。
// 候选起点允许暂时超出工程末端，由工程在成功提交后延长。
// 当前位置不要求是整数秒，例如一帧移动会给出1/30秒。
// 业务层先对齐帧，再处理碰撞，而不是各事件处理器自行舍入。
// 命令没有文件路径字段，名称和目录变化不属于时间线移动操作。
export type TimelineCommand = { kind: "add"; id: string; assetId: string; start: number; track?: TrackId } | { kind: "move"; id: string; start: number; track?: TrackId };
// 原数组只在成功时返回新快照，失败结果没有可误用的半成品片段。
// 原因是有限枚举，UI按语言显示，不把异常栈当用户提示。
// invalid覆盖未知身份、非就绪源、非法时间与重复实例身份。
// overlap单独报告，用户可以换一个落点而非误以为文件损坏。
export type TimelineResult = { ok: true; clips: LiveTimelineClip[]; clip: LiveTimelineClip } | { ok: false; reason: "invalidPlacement" | "overlap" };

// 总长按最晚结束时间计算，不把多个源时长相加。
// 空工程返回零；视口的初始三十秒由展示层另外提供。
// 移到更早的空隙后，总长允许收缩，不留下固定演示时长。
// reduce不修改数组，同源多个实例仍保留独立引用。
export function timelineDuration(clips: readonly EditorTimelineClip[]) { return clips.reduce((end, clip) => Math.max(end, clip.end), 0); }

// 将源时长向上补齐到一个项目帧，只改变时间线的占位长度。
// 起点则四舍五入到最近项目帧，两者的取整方向不同。
// 例如24fps源进入30fps工程，仍展示源24fps，不改元数据。
// 负数先被拒绝，不能通过四舍五入把负起点悄悄改成零。
// 源必须为ready视频，封面缺失不影响已探测源的使用。
// 同名文件不用名称查找，只有明确assetId才能引用。
// 非有限值不允许流入百分比CSS，避免NaN污染整条标尺。
// sourceIn固定零体现本轮未接修剪，不假装支持源入出点。
// 移动复制旧实例，只替换start/end，保留源入点与真实时长。
// 片段身份找不到就失败，不能默认移动首个片段。
// 创建身份与已有身份相同时拒绝，避免React复用错误节点。
// fps由工程提供，不随每次拖过不同源而改变。
// 先检查起点符号，再取整，防止负0.001秒在30fps下被四舍五入为合法零。
// fps必须为正有限数，否则除法可能产生Infinity并污染样式。
// 移动时先以实例ID定位旧记录，没有记录就返回空，而不是默认首项。
// 旧片段长度先乘fps再取整数帧，避免多次移动累积浮点尾差。
// 新终点用“新起点帧+长度帧”计算，保证移动前后帧数相等。
// 创建先确认源存在，再检查视频类型与ready状态，条件缺一不可。
// error、loading和cancelled行不能只凭存在duration就变成可入轨素材。
// 没有封面不在拒绝条件内，探测成功而封面缺失仍能安排源视频。
// 零时长不构成可见片段，负时长也不能靠绝对值变成有效源。
// 同名素材只要assetId不同就可以各自使用，名称不用于去重。
// 反过来，同一个clipId即使引用不同素材也必须拒绝重复创建。
// 源帧率不用于工程位置对齐，24fps素材仍在30fps工程格点上放置。
// 这只决定安排表的格子，不能宣称源文件被转码成30fps。
// 移动时目标轨道可省略，旧调用方因此仍留在原轨，不改变键盘平移语义。
// 显式目标必须与原片段类型相同，不能把视频改成音轨来逃过同轨碰撞。
// 创建新素材只允许视频轨，传入A编号时拒绝，而不是悄悄回落V1。
// 新实例的sourceIn初始化为零，后续修剪只改实例自己的入点。
// 移动spread保留sourceIn，所以修剪后再平移不会从文件开头重新播放。
// 移动长度仍按整数项目帧复制，不因目标轨宽度或当前缩放改变时长。
// 重复ID创建拒绝，新的同源实例必须使用不同clipId。
// 素材kind与state一起校验，不能仅用.mp4文件名判断已完成真实探测。
function candidateClip(clips: readonly LiveTimelineClip[], assets: readonly EditorMediaAsset[], command: TimelineCommand, fps: number): LiveTimelineClip | null {
  if (!Number.isFinite(command.start) || command.start < 0 || !Number.isFinite(fps) || fps <= 0) return null;
  const start = Math.round(command.start * fps) / fps;
  if (command.kind === "move") {
    const old = clips.find(clip => clip.id === command.id);
    return old && (!command.track || sameTrackKind(old.track, command.track)) ? { ...old, track: command.track ?? old.track, start, end: (Math.round(start * fps) + Math.round((old.end - old.start) * fps)) / fps } : null;
  }
  const asset = assets.find(item => item.id === command.assetId);
  if ((command.track && !isVideoTrack(command.track)) || !asset || asset.kind !== "video" || asset.state !== "ready" || !asset.duration || asset.duration < 0 || !Number.isFinite(asset.duration) || clips.some(clip => clip.id === command.id)) return null;
  return { id: command.id, assetId: asset.id, track: command.track && isVideoTrack(command.track) ? command.track : "V1", start, end: (Math.round(start * fps) + Math.ceil(asset.duration * fps)) / fps, sourceIn: 0, sourceDuration: asset.duration };
}

// 碰撞使用半开区间：[开始,结束)，前一段终点等于后一段起点合法。
// 比如0–6秒与6–12秒可以相邻，5–11秒则与第一段重叠。
// 对比整数帧，避免0.1+0.2和0.3的二进制差异被认成碰撞。
// 移动时排除自己的id，不能让片段与原位置撞到自己。
// 其余同源实例仍参与检查，assetId相同不是排除条件。
// 只比较同轨，未来扩轨不会把别轨安排当作本轨碰撞。
// 本轮候选始终V1，音频轨在交互边界也会拒绝。
// 所有判断先完成再构造数组，没有先移动再回滚的中间工程。
// 预览调用本函数只读结果，松手才真正写入。
// 键盘末尾添加和按帧移动也使用本函数，不绕开门槛。
// 失败后原数组、选择和总长均由调用方保持不变。
// 成功数组沿用原顺序，视觉位置由start决定而非数组下标。
// sourceDuration不参与碰撞，碰撞比较的是取整后的工程占位。
// 这像停车位的边线，车长按格子算，但不因此改写车辆真实尺寸。
// 两个条件共同表达相交：候选起点早于对方终点，候选终点晚于对方起点。
// 任一条件不成立就没有交集，故相邻边界不会被当成重叠。
// 例如长度98帧的首段占[0,98)，新段从98帧开始合法。
// 新段从97帧开始则有一帧交集，必须返回overlap。
// 移动时只排除相同clipId，而非相同assetId，这是同源多实例的关键。
// 复制数组之前先检查全部同轨记录，失败时没有可见半次写入。
// 成功移动使用map替换命中实例，其他实例对象引用保持稳定。
// 成功创建追加到数组末尾，实际视觉顺序由start百分比表示。
// 因此数组顺序不是播放顺序，也不需要为拖动反复排序原数组。
// 本函数既用于草稿验证，也用于最后提交，二者使用同一组帧规则。
// 它不生成UUID，重复计算同一候选不会改变身份或产生副作用。
// 它不访问React状态，鼠标、键盘和后续独立回归能共享相同结果。
// 它不抛业务异常，拒绝结果通过有限原因交给界面翻译。
export function applyTimelineCommand(clips: readonly LiveTimelineClip[], assets: readonly EditorMediaAsset[], command: TimelineCommand, fps: number): TimelineResult {
  const clip = candidateClip(clips, assets, command, fps);
  if (!clip) return { ok: false, reason: "invalidPlacement" };
  const overlaps = hasTimelineOverlap(clips, clip, fps);
  if (overlaps) return { ok: false, reason: "overlap" };
  return { ok: true, clip, clips: command.kind === "add" ? [...clips, clip] : clips.map(other => other.id === clip.id ? clip : other) };
}

// 放置像在停车场找最近的完整车位：不能停进别人的车，也不能截短自己的车。
// 负起点贴到零，碰撞时同时检查障碍前后边界，不总是跳到工程末尾。
// 所有候选再经过严格命令校验，鼠标草稿、松手和键盘共用同一个解决结果。
// 与严格apply分开，是为了分离音轨等原子操作仍能明确拒绝而不偷偷移位。
// 非有限起点与非法帧率先拒绝，不能通过夹紧把NaN变成可写工程的秒数。
// 不改变障碍片段、长度、源入点或轨道；相同距离优先较早的空位。
// 所有边界先换成项目帧，避免小数误差导致首尾相接仍被当作相交。
export function resolveTimelineCommand(clips: readonly LiveTimelineClip[], assets: readonly EditorMediaAsset[], command: TimelineCommand, fps: number): TimelineResult {
  // 先确认start与fps有限，NaN不该通过Math.max变成貌似合法的放置意图。
  // wanted保存整数帧，不是格式化为两位小数的提示文案。
  // 负起点夹零发生在这里，严格candidateClip仍保留拒绝负数的独立语义。
  // candidate先确认引用、状态和完整长度，非法源不必继续搜索空位。
  // 移动旧片段只变起点，长度来自原安排，不从鼠标轮廓宽度反推。
  // obstacles仅取同轨且排除本人，另一音轨同时间出现不会阻挡当前安排。
  // 搜索候选不是每帧遍历，长工程不会因十小时空白而多查一百多万次。
  // 一维区间的最近合法位置只可能是原落点、零或某个障碍的相接边界。
  // 障碍前边界要减完整片段长度，使候选end恰好等于障碍start。
  // 障碍后边界直接取end，使候选start恰好等于障碍end。
  // 不能只比较候选起点是否在障碍内，候选尾部也可能撞上后一个障碍。
  // 每个边界仍交给严格apply验证所有同轨障碍，避免避开一个却撞上另一个。
  // starts用Set去重，相邻障碍共享边界时不重复执行相同验证。
  // 负边界直接剔除，因为不存在工程零之前的可放置空间。
  // 排序先比较与wanted距离，距离相等再比较帧号，重复计算结果稳定。
  // 例如六秒片段要从4开始、障碍从8到14，最近前贴是2，不能缩成四秒。
  // 同样六秒片段想从9开始，障碍后贴14比前贴2更近，应选14。
  // 若短空隙容不下完整片段，两端候选都会严格失败，继续比较其他空位。
  // 候选不要求位于旧工程时长内，拖到末尾之外可以合法延长工程。
  // 最晚障碍之后通常总有空位，仍保留失败结果给非法或将来受限场景。
  // 返回严格apply产生的新数组，不在搜索过程中改原数组再撤回。
  // hover重复运行不会改变后续候选，松手能得到同样的边缘结果。
  // 此策略是碰撞避让，不包含靠近标尺、播放头或异轨边缘的通用吸附。
  // 分离音轨仍用严格碰撞，不借此偷偷移动声音造成音画起点错位。
  // 键盘方向移动也走这里，在障碍处贴边而不绕过同轨完整占位约束。
  // 新建与移动共用结果，避免蓝色草稿显示2秒、松手却提交14秒。
  if (!Number.isFinite(command.start) || !Number.isFinite(fps) || fps <= 0) return { ok: false, reason: "invalidPlacement" };
  const wanted = Math.max(0, Math.round(command.start * fps));
  const candidate = candidateClip(clips, assets, { ...command, start: wanted / fps }, fps);
  if (!candidate) return { ok: false, reason: "invalidPlacement" };
  const length = Math.round((candidate.end - candidate.start) * fps);
  const obstacles = clips.filter(clip => clip.track === candidate.track && clip.id !== candidate.id);
  const starts = [wanted, 0, ...obstacles.flatMap(clip => [Math.round(clip.start * fps) - length, Math.round(clip.end * fps)])];
  const ordered = [...new Set(starts)].filter(frame => frame >= 0).sort((a, b) => Math.abs(a - wanted) - Math.abs(b - wanted) || a - b);
  for (const frame of ordered) {
    const result = applyTimelineCommand(clips, assets, { ...command, start: frame / fps }, fps);
    if (result.ok) return result;
  }
  return { ok: false, reason: "overlap" };
}

// 所有轨道共用整数帧半开区间，鼠标、键盘和右键分离不能各算一套碰撞。
// 轨道像不同层的停车场；相同时段停在不同层不冲突，同层才需要让位。
// 排除的是同一片段ID，不是同源素材，所以同源重复入轨仍会参与碰撞。
// 比较前后两个端点，刚好首尾相接合法，一帧交集也应拒绝。
export function hasTimelineOverlap(clips: readonly LiveTimelineClip[], clip: LiveTimelineClip, fps: number) {
  // 例如候选A1的[4,10)与A1的[8,14)相交两秒，必须拒绝。
  // 相同候选与A2的[8,14)不构成同轨碰撞，两者可同时保留独立安排。
  // start与end都先换成项目帧，30fps项目中的相邻边界不会受二进制小数尾差影响。
  // 片段本身的源帧率可为24fps；它只影响源解码，不改变这里的工程格子。
  // ID自排除只用于移动原实例，新的音轨ID与原视频不同，仍需接受完整检查。
  // 这个方法没有修改数组，因此可以同样用于悬停草稿和最终提交。
  // 先比较轨道能避免把视频与新分离音频同时间的安排当成异常。
  // 结束边界使用严格大于；前段结束恰等于后段开始时交集为空。
  return clips.some(other => other.id !== clip.id && other.track === clip.track && Math.round(clip.start * fps) < Math.round(other.end * fps) && Math.round(clip.end * fps) > Math.round(other.start * fps));
}

// 右键菜单和Delete键共用工程编辑结果，不让UI直接改数组中的对象。
// 成功可能没有选中片段，例如删除，所以与位置命令的结果单独表达。
// 操作不接收文件路径，也不提供转码、删除磁盘文件或保存工程的权限。
export type TimelineEdit = "detach" | "duplicate" | "delete" | "mirror" | "rotate";
export type TimelineEditResult = { ok: true; clips: LiveTimelineClip[]; selectedId: string | null } | { ok: false; reason: "overlap" | "invalidPlacement" | "trackLocked" };

// 分离只建立原源音轨的独立引用，像把同一页乐谱分给另一位演奏者。
// 新片段保留起止、源入点和时长，不能为了塞进空位偷偷挪动或缩短音轨。
// 优先A1，原时段已有冲突则尝试A2；两轨都冲突时原视频也不能被静音。
// 每个候选使用同一个碰撞方法，禁止绕过同轨重叠门槛。
// 探测确认无音轨、未就绪源、音频实例或已分离视频均不允许再次分离。
// 校验依据真实metadata.hasAudio，文件后缀为mp4不代表一定有声音。
// 返回完整新数组后才由会话一次提交，失败不产生“视频已静音、音频没建好”的半次结果。
// 音频片段与视频ID不同，后续移动、复制和删除均独立，不绑定同源其他实例。
// 新ID冲突要拒绝，不能用旧ID覆盖另一条轨道上的片段。
// 静音标记只写当前视频实例，素材对象和源文件都保持不变。
// 删除已分离音频不会自动把原视频恢复有声，符合独立片段的语义。
// 本方法不提取wav，也不制造素材库里不存在的文件；它是无损工程分离。
// 分离复用原编辑命令，只扩充可选音轨集合，不新建另一套分离业务。
// 先按工程音轨顺序找空位，全部占用后才尝试申请一个新的音轨编号。
// 锁定轨道从候选中排除，但源视频已锁仍由外层统一拒绝整个编辑。
// 新增候选也受audio名额限制，不能因为是分离操作绕过五条默认上限。
// 分离保持start/end/sourceIn，声音与修剪后画面引用相同的源区间。
// 清掉transform，因为音轨没有位置、缩放、旋转或画面不透明度。
// 只有找到可用完整区间才给视频加audioDetached，拒绝不留下半次静音状态。
// 已有audioDetached不能再次分离，避免同一个实例重复生成相同声音。
// 源metadata.hasAudio必须来自真实探测，无音轨视频不提供虚假的分离成功。
// 返回实际新音轨实例，由工程提交方登记其轨道，纯模型不修改外部tracks数组。
// 全部目标锁定与单纯占用使用不同失败原因，界面可以给出具体反馈。
// 锁表、轨道顺序和数量限制来自当前工程，旧调用方仍可使用默认参数。
// 候选集合由已有音轨列表加至多一个extra构成，不一次预建到二十轨。
// extra只有nextTrack返回合法编号才加入，设置已满时集合只有现有轨道。
// available的顺序保留A1/A2等工程顺序，find挑第一个无碰撞且未锁定目标。
// 同一工程时段可在不同音轨重叠，这是多音轨安排，不是同轨区间冲突。
// 源视频分离后audioDetached为true，但音频副本audioDetached为false，二者语义不同。
// 音频副本audioOnly为true，即使源asset.kind仍是video也不能出现在节目画面层。
// 删除分离音轨不会自动恢复源视频声音，恢复或链接应是后续明确编辑命令。
// 复制已分离的视频继续保留audioDetached，不能因创建新id悄悄恢复重复声音。
// sourceIn照搬原视频，保证先修剪再分离时声音从相同源入点开始。
// sourceDuration照搬探测总长，之后音频独立修剪仍受原文件边界约束。
// 原视频transform保持原值，生成音轨只清副本构图，不可将源构图一并置空。
// 没有把音轨时长设为源全长，必须保持被分离视频安排的end-start。
// 如果当前所有候选都锁，返回trackLocked而非overlap，用户不必猜是占用还是权限。
// 如果至少一条可编辑但全被片段占用且不能新增，返回overlap保留原视频完整状态。
// 分离不是移动，原视频仍留在原轨、原时段，只有音频静音标记改变。
// 新的音轨id由调用方生成并检查重复，不能沿用视频id导致选择和删除串对象。
// 此模型不调用FFmpeg提取wav，元数据中确有音轨也不代表磁盘新增音频文件。
// 独立音轨预览继续读取原容器音频流，源文件删除会同时影响两种引用。
function detachAudio(clips: readonly LiveTimelineClip[], assets: readonly EditorMediaAsset[], clip: LiveTimelineClip, id: string, fps: number, lockedTracks: readonly string[], tracks: readonly TrackId[], limits: TrackLimits): TimelineEditResult {
  // assetId是稳定引用，名称相同或路径改变不会让分离方法误查另一份素材。
  // state必须就绪，因为探测失败行可能还保留上次尝试的显示文字。
  // 封面是否存在不构成音轨条件，缺图视频只要探测有效仍可分离声音。
  // hasAudio只代表流存在，能否实际播放仍由浏览器媒体事件给出结果。
  // 因此解码失败也保留安排与元数据，用户可以删除该安排或换源查看。
  const asset = assets.find(item => item.id === clip.assetId);
  if (!isVideoTrack(clip.track) || clip.audioDetached || !asset?.metadata?.hasAudio || asset.state !== "ready") return { ok: false, reason: "invalidPlacement" };
// 音轨分离是安排引用的拆分，不是把视频画面变成一张透明图片。
// 清除transform可避免音频记录误继承视频X/Y和不透明度。
// 音量不属于opacity，未来音频效果需要独立契约，不能借画面透明度代替。
// video原实例的构图继续保留，分离只改变声音通道归属。
// 目标轨道仍先排除锁定，再检查完整时长碰撞，不能为分离缩短安排。
// 没有合法音轨时原工程保持不变，不产生带半份参数的音频记录。
// 同源音频与视频仍共享assetId，但拥有不同clip.id和属性类型。
// 属性适配读取audioOnly，文件扩展名仍为mp4不影响音频组判断。
// 清除构图只是工程数据清理，不触发转码、写盘或重新探测。
// 当前单源试听不会将这条音轨与原视频自动混音播放。
  const extra = nextTrack(tracks, "A", limits);
  const available = [...tracks.filter(track => !isVideoTrack(track)), ...(extra ? [extra] : [])];
  const audio = available.filter(track => !lockedTracks.includes(track)).map(track => ({ ...clip, id, track, audioOnly: true, audioDetached: false, transform: undefined })).find(candidate => !hasTimelineOverlap(clips, candidate, fps));
  // 两条候选只改变轨道，映射过程中没有把原clip的track原地改成A1。
  // find只选第一条空闲轨，数组顺序明确了A1优先的产品行为。
  // 即使候选在A2，源起点仍是sourceIn，工程起点仍是start，两套坐标不混用。
  // audioOnly打开后由渲染适配选audio元素，不从这份数据生成另一条文件路径。
  // audioDetached在音频上为false，因为它本身不含需要再拆出去的视频声音。
  // 原视频标记要等audio候选确定后再设置；找不到位置就不产生任何静音副作用。
  // 这是一次原子快照更新：V1静音与新音轨建立要么一起成功，要么一起失败。
  // 不同视频实例即使引用相同assetId，也只有目标id对应那条被置为静音。
  // 新音轨保留sourceDuration，后续真实预览仍能区分源长度和项目帧占位长度。
  // 例如3.25秒源占98帧，新音轨同样占98帧，不能反向更改源时长成98/30秒。
  // 锁像每个抽屉各自的封条，源抽屉没封不代表能往目标抽屉塞东西。
  // A1锁住时可以原时段使用空闲A2，不允许移动时间或缩短声音来规避锁。
  // 两轨都锁时单独报告锁定，不能误报成文件损坏或悄悄静音原视频。
  // 若只剩未锁轨但已有占用，则仍属于碰撞；两种拒绝原因不混为一谈。
  // 候选过滤与碰撞共用这里的纯计算，菜单和快捷键没有各自的目标轨选择规则。
  // 只有成功找到合法目标，下面才一次性返回视频静音与新音轨的完整快照。
  // 失败不返回半成品数组，调用方必须保留原工程与原选择。
  if (!audio) return { ok: false, reason: available.every(track => lockedTracks.includes(track)) ? "trackLocked" : "overlap" };
  return { ok: true, clips: [...clips.map(item => item.id === clip.id ? { ...item, audioDetached: true } : item), audio], selectedId: id };
}

// 右键菜单仅传动作与身份，执行时重新从当前快照查目标，旧菜单不能编辑已删实例。
// 删除只移除工程安排，素材库与磁盘文件依旧存在，其他同源实例不跟着消失。
// 复制放在所属轨道实际末尾，不抢占其他片段位置，也不依赖全工程的空白视口。
// 复制保留源入点、长度和已分离状态；复制一个静音视频不会偷偷恢复声音。
// 音频副本仍在原音频轨，不能通过复制隐式跨轨或返回V1。
// fps非法时拒绝，避免NaN比较把所有碰撞都误认为不相交。
// 分离和复制都要求新身份，生成身份归会话，纯计算重复调用没有额外副作用。
// 命令失败不返回新数组，由会话保留原选择、源预览和时长。
// 删除成功清除选中，避免属性面板仍引用已不存在的片段。
// 本轮没有剪切板、切分、修剪和撤销记录，不把复制称为系统剪贴板粘贴。
// 同一时间的不同轨道不冲突，但相同轨道的所有同源实例都需要比较。
// 复制再次经过共同碰撞方法，为后续时间参数扩展保留一致的提交门槛。
// tracks/limits是可选扩展，仍使用同一个编辑命令返回结构，菜单不新增另一条IPC。
// 默认轨道集合保留历史V1/A1/A2，而新增名额默认每类五条。
// 复制片段时transform继续独立克隆，sourceIn随原值保留，后续修剪互不污染。
// 删除仍仅按实例id，不删除素材文件或其他同源安排。
// 命令失败返回原因而非抛出，父层状态提示可保留原工程与选择。
// 菜单和键盘共用这条编辑命令，不能只在某一种入口检查锁轨。
// 目标片段由实例ID匹配，同名标题和相同源文件都不能替代这个身份。
// 删除不要求生成新UUID，但复制与分离必须保证新身份没有被工程占用。
// 镜像与旋转不创建新片段，传入的新ID参数不会改变原实例身份。
// 视频镜像状态放在片段本身，不会向asset写一个所有副本共用的布尔值。
// 旋转只复制目标transform，后续改副本角度不会改到原片段的同一对象。
// 纯音频拒绝画面动作，不能靠给音轨附带一个transform来声称实现。
// 复制到同轨末尾仍以完整片段长度放置，不按源文件总长重新展开已经修剪的内容。
// 复制同时保留源入点和speed，这样副本读到的内容与原片段一致。
// 分离音频引用真实原视频音轨，保留源时间映射，而不是建立假波形文件。
// 音轨分离的目标轨同样检查锁与碰撞，源轨未锁不代表任意目标轨都可写。
// 没有合法空闲同类轨时拒绝，不能静音源视频后又没有创建独立音轨。
// 新的音轨名额只有成功提交才进入tracks，失败不消耗候选编号。
// 菜单操作完成只代表临时工程更新，未保存提示仍由项目栏保留。
// 原文件删除、重命名、编码导出都不属于这个函数，不接受任意文件路径。
// 结果显式带ok联合，调用方不能把null或空数组理解成成功删除所有素材。
export function applyTimelineEdit(clips: readonly LiveTimelineClip[], assets: readonly EditorMediaAsset[], action: TimelineEdit, target: string, id: string, fps: number, lockedTracks: readonly string[] = [], tracks: readonly TrackId[] = DEFAULT_TRACKS, limits: TrackLimits = DEFAULT_TRACK_LIMITS): TimelineEditResult {
  // 重查目标能处理菜单打开后工程已经变化的情况，未找到就给明确无效结果。
  // 删除不需要新身份，所以仅对复制与分离检查id是否已经存在。
  // 选中ID与源ID不同，删除某个同源副本不会删除共享的素材引用对象。
  // 删除采用filter产生新数组，外层正在读取旧快照的草稿不会被偷偷改写。
  // fps不是字符串输入；依然拒绝非有限值，避免内部调用错误污染工程坐标。
  // 复制的start取本轨最大end，不取数组末项，因为DOM与数组顺序都不是时间顺序。
  // 如果V1末尾为12秒、A1末尾为20秒，复制V1仍应从12秒开始。
  // 总工程时长随后取所有轨的最大end，因此这次复制未必让总长增长。
  // end由整数帧加法构造，避免多次复制把小数误差累加到源长度里。
  // 拷贝对象会保留audioOnly和audioDetached，通道与静音不会因为新ID丢失。
  // 原安排对象不变，用户仍能分别选择原件和副本。
  // 返回selectedId只表达下一次UI应选谁，不让纯函数直接操作DOM焦点。
  const clip = clips.find(item => item.id === target);
  if (!clip || !Number.isFinite(fps) || fps <= 0 || (action !== "delete" && clips.some(item => item.id === id))) return { ok: false, reason: "invalidPlacement" };
  // 在提交入口重查源轨锁，不只依赖按钮disabled，旧菜单也必须服从当前锁。
  // 可选空锁表兼容纯模型旧调用方；正式会话每次提供最新锁表。
  // 复制、删除、分离共享此门槛，不允许某个操作通过另一条入口绕过去。
  // 源轨锁住时不生成副本、不清选择，也不尝试把音轨写入另一轨。
  // 分离还要继续检查目标轨，源和目标是两个独立的写入权限。
  // 此函数不修改锁表，失败不会替用户解锁或改动其他轨道状态。
  // 用实例实际track判断，不拿当前高亮的轨道或素材kind推断权限。
  if (lockedTracks.includes(clip.track)) return { ok: false, reason: "trackLocked" };
  if (action === "delete") return { ok: true, clips: clips.filter(item => item.id !== target), selectedId: null };
  // 基础画面编辑只作用于视频实例；音轨不能获得一个假旋转效果。
  // 保留原时间区间、源入点和轨道，镜像/旋转不重新安排节目时间。
  // 独立复制transform，后续属性编辑不会与同源或复制片段共享可变对象。
  if (action === "mirror" || action === "rotate") {
    if (clip.audioOnly || !clip.transform) return { ok: false, reason: "invalidPlacement" };
    const next = action === "mirror" ? { ...clip, mirrored: !clip.mirrored } : { ...clip, transform: { ...clip.transform, rotation: (clip.transform.rotation + 90) % 360 } };
    return { ok: true, clips: clips.map(item => item.id === target ? next : item), selectedId: target };
  }
  if (action === "detach") return detachAudio(clips, assets, clip, id, fps, lockedTracks, tracks, limits);
  const start = timelineDuration(clips.filter(item => item.track === clip.track));
// 复制保留数值但分开对象，像复印构图记录而不是让两份表共用同一张便签。
// 只展开clip还不够：嵌套transform会继续指向原记录，后续原地写入容易串值。
// 这里显式展开五个标量，副本与原片段的相等数值不代表相同引用。
// 旧样板没有transform时保持undefined，由正式创建边界提供默认中心。
// 新id仍由原复制命令生成，不能用源素材id替代安排身份。
// 复制不改assetId，所以不会在素材库再生成一份视频文件。
// start/end仍按完整帧长度放到同轨末尾，构图继承不能影响时长。
// 原锁与碰撞规则先执行，不能靠复制构图绕过已有轨道保护。
// 修改副本X/Y后原片段的缩放、角度与透明度均应保留。
// 删除副本只删除工程引用，源文件和原片段构图都不受影响。
  const duplicate = { ...clip, transform: clip.transform ? { ...clip.transform } : undefined, id, start, end: (Math.round(start * fps) + Math.round((clip.end - clip.start) * fps)) / fps };
  if (hasTimelineOverlap(clips, duplicate, fps)) return { ok: false, reason: "overlap" };
  return { ok: true, clips: [...clips, duplicate], selectedId: id };
}

// DOM矩形的left已包含横向滚动带来的负位移，不能再加一次scrollLeft。
// 抓取偏移用秒数保存，片段中间被抓住时起点仍保持原有距离。
// 坐标换算保留负数供上层判断；交互命令统一在resolve入口贴零与避让。
// 返回项目帧位置，轮廓、预计时间与最终提交共用同一结果。
// pixelsPerSecond在手势开始时冻结，工程边界变化不能追着鼠标缩放。
// 这里只换算，不读取或改写任何素材、片段及播放器。
// 例如每秒32px，内容左边为400px，鼠标落在560px，对应工程5秒。
// 若在片段内部第1秒抓住，则片段起点应为4秒，而非5秒。
// 横滚160px后内容left变为240px，同一屏幕鼠标对应工程10秒。
// 此时再加scrollLeft会把滚动算两遍，得到错误的15秒。
// 抓取偏移在手势开始时冻结，因此滚动不会改变“抓住哪一处”。
// 最后乘fps并四舍五入，把连续像素落点变为工程可表示的帧。
// 负数仍返回，严格校验可拒绝；交互放置层会把它解析为零边界。
// 函数不替调用者读取导航宽度，所有外部布局已折算进DOM矩形。
export function timelineDropTime(clientX: number, laneLeft: number, pixelsPerSecond: number, offset: number, fps: number) {
  return Math.round(((clientX - laneLeft) / pixelsPerSecond - offset) * fps) / fps;
}

// 内部载荷只传身份，不传本地路径、完整视频或封面字节。
// MIME和session两层隔离，另一页或另一编辑器不能拿同名ID越界引用。
// getData在拖过期间可能被浏览器保护为空，最终读取必须在drop发生。
// parse只接受本轮明确的两个操作类型，不把网页纯文本当内部安排。
export const TIMELINE_DRAG_TYPE = "application/x-illusion-realm-timeline";
export interface TimelinePayload { session: string; kind: "asset" | "clip"; id: string; }
// JSON异常、数组或null都返回空值，不让拖放事件抛错导致页面导航。
// 字段逐个缩窄，不用any或强行把未知对象断言成可信载荷。
// 会话比较放在解析层，每个入口不必重复一份身份判断。
// ID是否真实存在继续由工程验证，能解析不代表能执行。
// JSON能解析不等于可信，例如null和数组也都是合法JSON文本。
// 每个属性都在存在性与类型检查后才读取，不依赖强制类型断言。
// session必须等于本组件会话，复制上一页的载荷不会继续生效。
// kind只允许asset和clip，未知操作不能回落为默认创建。
// id的存在性还会在工程命令中再次检查，解析器不查素材库。
// 解析失败返回null，由drop给就地反馈，不能让异常穿透React事件。
// 文本中额外字段不会成为命令参数，返回值只取三项已认可身份。
// 即使伪造了会话和ID，drop还要求当前确实存在同身份起始手势。
export function readTimelinePayload(text: string, session: string): TimelinePayload | null {
  try {
    const value: unknown = JSON.parse(text);
    if (!value || typeof value !== "object" || !("session" in value) || value.session !== session || !("id" in value) || typeof value.id !== "string" || !("kind" in value) || (value.kind !== "asset" && value.kind !== "clip")) return null;
    return { session, id: value.id, kind: value.kind };
  } catch { return null; }
}

// 节目时钟像乐队指挥：工程只有一根指挥棒，每个视频按自己的入点对齐。
// 素材的 play/timeupdate 不能回写工程，防止多个播放器争抢播放头。
// 这里只计算时间和调度实际媒体，不持有第二份片段工程，也不负责导出。
import type { EditorPreviewClip } from "./editor-panels";

// 表项登记的是片段实例，不是素材身份；同源在不同轨道可以同时读不同源时间。
// video是实际解码节点，工程数据里不保存DOM引用，也不将节点传到IPC。
// state承接源加载器事实，failed单独承接play拒绝或寻帧失败。
// 初次loadeddata不能重置failed，否则失败的play可能被迟到加载事件冲掉。
// request只说明已对当前定位发出设置，不代表目标已经解码完成。
// deadline属于当前请求，正常就绪时续期，连续卡住时不会无期限等待。
// starting只保护尚未完成的play承诺，不代替video.paused这一真实状态。
// 表项不是持久化字段，离开页面后必须释放，不能写入用户JSON。
// 媒体表不保存整文件数据，实际读取与解码由浏览器localfile管线承担。
// 同id重试会用新节点替换表项，旧Promise需要核对身份再决定后续动作。
export interface ProgramMedia {
  video: HTMLVideoElement;
  state: "loading" | "ready" | "error";
  request: number;
  deadline: number;
  failed: boolean;
  starting: boolean;
}
export interface ClockLayer { clip: EditorPreviewClip; }
// time是唯一工程游标，源currentTime不能直接覆盖它。
// version来自工程明确定位命令，request还可以覆盖内部回零和重试。
// 重试不需要伪造一次外部定位，因此两种编号有不同职责。
// last记录上一次有效节拍的单调时间，不使用可被系统校时跳动的日期时间。
// intent表达用户想播放，媒体暂时缓冲并不意味着用户主动暂停。
// media由当前实例持有，第二个工作区不会取到第一个工作区的解码节点。
// 轨道锁、选择与属性不在时钟内；它们不能决定哪些层推进。
// 轨道显隐在装配前过滤，时钟只看到应参与当前节目的视频。
// 工程总长从片段数组读取，不由第一个视频的duration代替。
// 没有音频混合状态，这不是一个隐含的音频总线。
export interface ProgramClock {
  time: number;
  version: number;
  request: number;
  last: number;
  intent: boolean;
  media: Map<string, ProgramMedia>;
}
export type ProgramPhase = "loading" | "ready" | "error";

// 工程秒不等于源秒；例如入点2秒、工程起点8秒，在工程9秒应读源3秒。
// 旧片段已有倍速时继续遵守其映射，本轮不新增变速编辑能力。
// 极末尾向下留一点余量，避免工程帧向上取整后请求不存在的源帧。
// 映射必须在每个片段自己的起点上计算，跨轨重叠不要求源时间相同。
// 片段sourceIn是源秒数，不是项目帧编号，也不是素材库的全局裁切点。
// 同源副本有不同sourceIn时，两个解码器仍读取同一个文件的不同区段。
// 时间线修剪已确认的入点直接复用，不能在此额外加一份UI偏移。
// 源速度属于已有安排契约，预览观看倍率不应被重复乘进这个映射。
// 观看倍率已经改变工程时钟步长，再乘一次会使节目和源二次加速。
// 返回值只用于定位媒体，不写回片段起止或探测时长。
// 末尾余量以源秒计，避免duration恰等于请求时间时触发ended而停在空白。
// 工程占位向上对齐的尾部可以保持源末帧，但不能生成或冒充额外源帧。
// 负值只作为防守夹限，正常调用已由活动区间确保工程时间不早于起点。
// 本函数不接受选择状态，选择不能改变源映射。
// 元数据尚未读出时调用方先等待，不能把NaN时长当成有效定位目标。
// 真实视频解码仍由浏览器判断，这个数值结果本身不是帧已呈现的证据。
// 未来导出可消费相同源映射，但当前不定义编码时间基或输出误差。
export function programSourceTime(clip: EditorPreviewClip, time: number, duration: number) {
  return Math.max(0, Math.min(duration - .001, (clip.sourceIn ?? 0) + (time - clip.start) * (clip.speed ?? 1)));
}

// 终点不包含：相接片段在同一秒只会命中后一个，不会闪回上一段末帧。
// 上下轨顺序已经由调用方的tracks排好，这里过滤不能重排、更不能看selected。
// 区间相接只共享数学端点，不共享可显示帧：旧段end时刻属于后段。
// 即使片段被选中，在start之前和end之后都不能继续留在节目中。
// 音轨应在装配层按轨道类型排除，不能用是否有视频后缀猜测工程通道。
// 活动过滤不会原地排序，所以不改变时间线数组的稳定身份。
// 返回原片段引用让属性草稿继续找到同一个工程实例。
// 筛选结果是临时列表，不作为另一份可编辑工程保存。
// 上层完全透明仍是活动片段，显示与编辑命中分别处理。
// 隐藏轨道完全不传入列表，省去其解码器而不只是把CSS设为透明。
// 锁定不应被此过滤条件读取，锁定画面仍参与合成。
// 时间落在所有片段之外时返回空，不能回退到最近选中对象。
// 同轨重叠由共同编辑模型拒绝，本处不偷偷选择一个冲突片段遮盖数据错误。
// 跨轨重叠是正常输入，不能对相同时间的不同轨片段做去重。
export function activeProgramLayers<T extends ClockLayer>(layers: readonly T[], time: number): T[] {
  return layers.filter(({ clip }) => time >= clip.start && time < clip.end);
}

// 每次最多走到最近的入点或出点，再等新图层真正解码；不能跨过短片段。
// 黑场也在工程时间内，可以继续走钟，而不是依赖某个视频存在才播放。
// 候选时间来自单调时钟，但边界必须来自全部可见视频安排。
// 相同端点出现多次不会改变最近边界的最小值。
// 上层入场也属于边界，即使下层还能继续播放，仍须等待新增源就绪。
// 上层出场则应释放其节点，让下层继续，不沿用旧上层最后一帧。
// 在黑场中查找下一个入点，不能因活动列表为空就提前判工程结束。
// 只看当前活动段会漏掉未来入点，所以调用方传全部节目层。
// 目标仍受工程duration限制，工程结尾不允许无限走钟。
// 极小容差只跳过刚到达的同一数学端点，不当作编辑吸附阈值。
// 最近边界先发布到工程，再由React挂载下一组媒体。
// 本函数不预先延长短片段，也不缩短素材以方便调度。
// 逐帧明确定位不经过此推进函数，因此不会因中间边界停在用户目标之前。
// 用户快定位按最新版本直接设置time，连续播放才逐站经过边界。
// 源入点不参与边界坐标，时间线边界始终是工程秒数。
// 大量片段时当前实现线性扫描，后续可优化索引但必须保持这些端点语义。
export function nextProgramTime(layers: readonly ClockLayer[], time: number, target: number, duration: number) {
  const boundaries = layers.flatMap(({ clip }) => [clip.start, clip.end]).filter(value => value > time + .000001);
  return Math.min(target, duration, ...boundaries);
}

// 所有暂停入口集中到这里：等待新帧、定位、隐藏、切源及卸载都必须停源。
// 不取消src，因为普通暂停后仍应保留已解码帧；卸载由attachSource释放。
// 暂停遍历整个登记表，而非仅当前命中层，防止刚退出区间的旧源多播一拍。
// video.pause是同步意图，play的异步完成仍需要在Promise回执里再核对intent。
// 此处不移除监听，普通暂停后用户仍应能继续播放同一节点。
// 此处也不清src，清src会丢失当前暂停画面并引发不必要的重新加载。
// 清理职责由registerProgramMedia返回的detach承担，不能两处互相抢资源。
// 空表是正常空工程或切换间隙，不应抛出没有媒体的错误。
// 已经暂停的节点不重复调用pause，减少无意义原生事件。
// 没有任何解除静音操作，暂停和恢复都不改变节目静音约定。
// 这不是撤销时间，暂停必须保留已确认的工程游标。
// 属性构图不会触发这里；改变位置不应打断真实视频帧播放。
export function pauseProgramMedia(clock: ProgramClock) {
  for (const { video } of clock.media.values()) if (!video.paused) video.pause();
}

// 定位令牌像叫号单：旧seeked即便晚到，也只有当前目标帧能通过下面的距离检查。
// 不等待某个事件永远到来；每个请求有15秒上限，超时呈现错误并允许重试。
// 已有元数据才能安全设置currentTime，加载头信息期间继续报告loading。
// 同一request只设置一次明确目标，普通时间报告不能触发反复seek反馈环。
// 源未读出metadata时保留请求，下一节拍继续尝试，而不提前盖上已处理标记。
// 新的外部version会增加clock.request，使每个已存在图层都重新对齐。
// 跨片段边界新挂载的表项从request负一开始，自然执行首次对齐。
// 设置currentTime之前更新请求标记，原生事件同步通知也能读到当前授权。
// 目标与当前时间足够接近时不人为触发seeking，避免零秒首帧无意义重读。
// 这个接近判断仅避免重复设置，最终可显示判定仍由programMediaPhase负责。
// sourceIn修改随工程命令递增定位版本，不会沿用前一个裁切位置。
// 位置和缩放修改不递增版本，因为空间参数不应改变读取源帧的时间。
// 旧seeked没有写工程游标的回调，因此无法把新书签拉回去。
// 多个定位连续到来只覆盖期望目标，不能按排队顺序播放已经过期的请求。
// 超时期限随明确新请求重设，之前等待时间不能误罚刚发出的新定位。
// 源重新加载时表项本身更换，旧deadline不会被新节点继承。
// 当前实现没有向外抛媒体内部错误堆栈，源加载器统一报告error。
function seekProgramMedia(entry: ProgramMedia, clip: EditorPreviewClip, clock: ProgramClock, now: number) {
  if (entry.request === clock.request || entry.video.readyState < 1) return;
  entry.request = clock.request;
  entry.deadline = now + 15000;
  entry.failed = false;
  const target = programSourceTime(clip, clock.time, entry.video.duration);
  if (Math.abs(entry.video.currentTime - target) > .001) entry.video.currentTime = target;
}

// 不能只凭loadeddata宣称定位成功：旧帧加载完成时，新currentTime可能还在寻帧。
// 暂停定位按帧精度校验，连续播放留少量解码时差，超过阈值就停钟重新对齐。
// currentTime、readyState和seeking共同作证，而非把事件到达顺序当作成功依据。
// 解码失败与等待分开，用户能知道现在是还在读帧，还是该源确实无法预览。
// ready必须同时满足有首帧、非寻帧、请求已应用和目标距离四项条件。
// readyState大于等于二表示有当前帧，不能仅因已知宽高就显示成功。
// video.seeking期间即使currentTime已显示目标数值，也不能当成目标帧已到。
// 暂停时按项目帧精度检查，防止高帧率项目定位被粗糙秒级容差糊过去。
// 连续播放允许少量源时差，时差扩大后暂停对齐，而不是任由各自漂移。
// 漂移修正不递增工程版本，避免媒体追赶反过来成为新的用户定位命令。
// 设置currentTime后返回loading，等待下一次真实媒体状态证明已完成。
// 漂移修正不刷新截止线，否则无法解码时会在每次修正中无限延后超时。
// 只有真正ready才续期，连续卡在等待中最终会变成error。
// play被拒绝的failed比首帧ready优先，不能把有封面当成播放已成功。
// 源加载器的error也优先于当前位置数值，坏文件不能靠currentTime碰巧正确通过。
// 当前源duration约束请求尾部，工程末格的读源余量不改变片段长度。
// 暂停时仍校准时间，所以用户快速定位后不用先播放才能看到正确画面。
// 锁层继续走这个流程，保护编辑不应令其帧停在旧时间。
// 这里没有读取CSS透明度，半透明画面和全不透明画面采用同一时钟质量门槛。
// 失败后的素材元数据仍在外部会话，状态不会反向删除文件或清空素材库。
// 暂停与播放使用不同容差不是两套源映射，而是读取媒体时刻的观察误差不同。
// 暂停目标需要接近项目帧格，连续播放时视频解码与控制节拍本来不会完全同时采样。
// 本处没有把秒数round到源fps，VFR或24fps源由浏览器决定该目标对应的帧。
// 工程fps仍固定项目配置，源的帧率事实保存在素材metadata中。
// 局部媒体时间超过源尾时只停在可读最后一点，不篡改ffprobe探测数据。
// 源超时仅影响本次节目预览，素材行可以继续展示封面与尺寸。
// 把ready单独作为输出，避免上层组件自行推断error消失就算成功。
// 状态检查每次读取video.seeking事实，不依赖seeked事件必然按顺序送达。
// 因此连续定位覆盖旧请求时，旧事件没有特殊分支能重新打开播放闸门。
// 若加载器尚未首帧ready，即使currentTime数值正确也仍显示loading。
// 若源进入等待且readyState下降，即使原来播放过也不能宣称当前帧可显示。
// 已经超时的源不会自动续期复活，需要用户显式重试建立新表项。
// entry.failed属于该实例，同文件另一片段不应因此被全局列入黑名单。
// 没有把源解码错误当成文件损坏结论，其他播放器或编码器可能支持它。
// 原始源文件没有被读入JavaScript数组，校验只观察浏览器媒体状态。
// 当前阶段不用Canvas像素读回校验每帧PTS，因此不声明离线逐帧精确合成已实现。
// 呈现等待是保守策略，会暂时遮住已就绪下层，而不是输出缺层构图。
// 这个策略宁可短暂黑色加载反馈，也不把不完整叠放当成完成。
// 本地高码率文件可能有更长寻帧耗时，固定十五秒是明确产品等待边界。
// 后台不可见与解码失败不同：隐藏会取消播放意图，源加载仍按生命周期清理。
export function programMediaPhase(entry: ProgramMedia, clip: EditorPreviewClip, clock: ProgramClock, fps: number, now: number): ProgramPhase {
  seekProgramMedia(entry, clip, clock, now);
  if (entry.failed || entry.state === "error" || now > entry.deadline) return "error";
  const video = entry.video;
  if (entry.state !== "ready" || video.readyState < 2 || video.seeking || entry.request !== clock.request) return "loading";
  const expected = programSourceTime(clip, clock.time, video.duration);
  const drift = Math.abs(video.currentTime - expected);
  if (drift <= (clock.intent ? .2 : .6 / fps)) { entry.deadline = now + 15000; return "ready"; }
  video.pause();
  video.currentTime = expected;
  return "loading";
}

// 多层像一组投影机，任何一台尚未对准当前帧就先遮住整个节目，避免假完成。
// 黑场没有解码器要等，所以空列表是ready；丢失源引用由注册层明确报error。
// 注册尚未来得及发生只算loading，不能因React提交晚一拍就误报解码失败。
// 合成成功需要所有当前层就绪，不能用主层ready掩盖下层加载失败。
// 任一层error就报告整体error，用户可重试，不能静默跳过坏层改变构图。
// 只要尚有loading且无error，整体就处于loading并遮住旧画面。
// 活动层刚变化时React可能尚未登记节点，这一拍只算等待。
// 本地节点登记不是一次独立网络请求，不为其创建第二份异步任务队列。
// 没有当前视频时直接ready，黑场能继续使用工程时钟经过。
// 空活动列表不等于删除选中片段，属性区仍可能有独立编辑目标。
// 列表保持明确轨道顺序，但状态汇总本身不改变任何层的前后关系。
// 每个表项单独检查源时间，不能取第一个视频的currentTime代表所有层。
// 部分层已就绪也不能播放出声音，因为节目全部源始终muted。
// 状态返回是当前节拍快照，下一次明确定位会使UI请求键失效旧快照。
// 本函数不发React更新，纯状态决策与界面通知分开，便于回归等待边界。
// 没有失败后返回ready的兜底，不把超时当成黑场成功。
// 当前没有将未用素材预加载进登记表，状态检查只付出活动视频的解码成本。
export function programPhase(clock: ProgramClock, layers: readonly ClockLayer[], fps: number, now: number): ProgramPhase {
  const phases = layers.map(({ clip }) => {
    const entry = clock.media.get(clip.id);
    return entry ? programMediaPhase(entry, clip, clock, fps, now) : "loading";
  });
  return phases.includes("error") ? "error" : phases.includes("loading") ? "loading" : "ready";
}

// play的Promise也可能在切源后返回；仅仍在登记表且仍有播放意图时才继续。
// AbortError是主动暂停/换源的正常结果，其余失败成为可见错误，不能吞成成功。
// starting防止每个时钟节拍重复调用尚未完成的play，避免积压Promise。
// 预览总倍率与片段已有速度相乘后设置真实playbackRate，不手工伪造源进度。
// 每台源的当前时间不同，但它们的工程推进目标来自同一个clock。
// 已经播放的节点不用重复发play，避免每四十毫秒堆积一次调用。
// starting阻止play尚未完成时再次发起，不依赖按钮连续点击次数。
// Promise成功时仍可能已经切源，因此必须核对表里是否仍是同一表项。
// 即使id相同，重试后的新节点也不能被旧表项的成功回执代表。
// 用户暂停之后才成功的play必须再次pause，避免松手后旧源悄悄响起。
// 节目所有节点本来静音，重入播放也不恢复素材查看的有声状态。
// AbortError表示主动取消加载或播放，正常清理不应污染错误状态。
// 非取消失败写到该表项，由下次状态汇总显示可重试错误。
// finally一定释放starting，失败后允许用户重试，不留下永久忙碌标志。
// 清理不等待这个Promise，旧节点可立即暂停和释放，回执随后只能自我停止。
// 源播放失败不改变片段时间或轨道，用户可继续删除坏引用。
// 该函数不实现音高、混音或响度，设置速率只维持已有媒体行为。
export function playProgramMedia(clock: ProgramClock, entry: ProgramMedia, rate: number) {
  entry.video.playbackRate = rate;
  if (!entry.video.paused || entry.starting) return;
  entry.starting = true;
  void entry.video.play().then(() => {
    if (!clock.intent || ![...clock.media.values()].includes(entry)) entry.video.pause();
  }).catch((error: unknown) => {
    if (!(error instanceof DOMException && error.name === "AbortError")) entry.failed = true;
  }).finally(() => { entry.starting = false; });
}

/** 轨道和修剪的纯规则：同类可换层，源入点与工程起点分别计量。 */
import type { LiveTimelineClip } from "./live-timeline-model";

// 编号只作稳定身份；列表顺序决定上层覆盖下层，点击不会重排列表。
// 编号不是层级数值：V1和V2的字符串只识别轨道，实际覆盖由tracks数组顺序决定。
// 不能按最近点击时间排序，否则点属性就会让一张画面突然盖到前面。
// 视频轨与音轨分别计数，五条视频加五条音频属于两个独立名额池。
// DEFAULT_TRACKS保留原工程的V1/A1/A2布局，不在空工程一次铺满十条空行。
// 只有成功落下或分离音轨才分配新轨，拖到一半取消不消耗名额。
// TrackLimits属于本次页面会话，关闭编辑器后恢复默认值，当前没有工程保存。
// 轨道ID采用正整数形式，A0、V-1和陌生前缀不能被当成合法目标。
// 模板类型只约束TypeScript，运行时入口仍需检查外部事件里的字符串。
// 判定同类时先验证目标格式，再比较前缀，不把VV1等伪编号当视频轨。
// 音频是否来自视频分离与类型无关，audioOnly片段始终属于音轨。
// 原始视频素材的hasAudio仅说明媒体里有声音，不把它自动变成音轨片段。
// 本模块只接收小型时间记录，不读取文件内容或创建播放器。
// 因此拖动时重复校验不会启动FFprobe或复制视频字节。
// 导入失败与修剪失败的恢复边界不同，修剪拒绝只返回null保留原数组。
// 纯函数不读取选中状态，避免鼠标、键盘和菜单得到不同结果。
export type TrackId = `V${number}` | `A${number}`;
export interface TrackLimits { video: number; audio: number; }
export const DEFAULT_TRACKS: readonly TrackId[] = ["V1", "A1", "A2"];
export const DEFAULT_TRACK_LIMITS: TrackLimits = { video: 5, audio: 5 };
export const isVideoTrack = (track: string) => /^V[1-9]\d*$/.test(track);
export const sameTrackKind = (first: string, second: string) => /^[VA][1-9]\d*$/.test(second) && first[0] === second[0];

// 新轨只是候选，松手成功才加入工程；取消不能留下空轨或消耗名额。
// 先计算同类条数，再查最大编号生成新身份，不能用整个轨道数组长度作V编号。
// 例如V1、A1、A2之后新增视频仍叫V2，不叫V4。
// 上限比较条数而不是最大编号，为将来允许删空轨保留正确语义。
// 如果达到上限返回null，调用方据此不绘制可投放的新轨候选。
// 提高视频名额不能改变音频名额，两种设置不共用一个数字。
// 构造结果使用新的字符串，输入数组不被push或排序。
// 该函数不决定插入显示位置，只负责能否分配以及新ID是什么。
// 调用方会在松手时重新计算，避免设置已变化却仍使用旧候选授权。
// 空数组从编号一开始，Math.max的零是编号起点，不是允许创建零号轨。
// 同类筛选与编号提取使用同一前缀，音轨数字不会影响视频编号。
// 上限由正式设置字段约束为1到20，模型不在这里悄悄改写用户设置。
// 当已有轨道多于新上限时拒绝继续新增，不删除已存在的片段。
export function nextTrack(tracks: readonly TrackId[], kind: "V" | "A", limits: TrackLimits): TrackId | null {
  const count = tracks.filter(track => track[0] === kind).length;
  if (count >= (kind === "V" ? limits.video : limits.audio)) return null;
  return `${kind}${Math.max(0, ...tracks.filter(track => track[0] === kind).map(track => Number(track.slice(1)))) + 1}`;
}

// 左边缘向右：工程start和sourceIn一起增加，保留结束时间；向左则找回源前面的帧。
// 右边缘向右：只延长end，不能超出文件剩余内容，也不改变播放速度。
// 像裁纸只收放边缘，不拉长纸上的图案；相邻片段不自动移动，不做波纹编辑。
// start/end使用工程秒数，sourceIn使用源文件秒数；两把尺子的零点不同。
// 把片段当成一条书签：工程起点是把书放在哪，源入点是从第几页开始读。
// 左边缘向右移动一工程秒，start增加一秒，sourceIn增加speed个源秒，end不变。
// 左边缘向左找回内容时，sourceIn最多退到零，不能凭空补源文件前面的帧。
// 右边缘移动只改end，不能改变起点、入点或画面变换。
// 工程边缘先换算成整数项目帧，源入点保留精度，两把尺子不能一起取整。
// 当前片段start/end本来就在项目帧上，因此round保留原工程帧的身份。
// 源文件时长可能落在半帧间，ceil沿用创建时的占位契约，不偷偷减少尾部占位。
// 最短长度是一项目帧，左边缘不能越过end减一帧，右边缘不能越过start加一帧。
// 前方障碍只取同轨且结束不晚于当前start的片段，最近的结束位置就是左边界。
// 后方障碍只取同轨且开始不早于当前end的片段，最近的开始位置就是右边界。
// 其他视频轨可以在同一时刻覆盖，不能因跨轨画面重叠而拒绝修剪。
// 音轨使用同样的时间边界，分离音轨也不能越过它引用的源内容。
// 排除只按clip.id做，不能按assetId排除，否则同源多实例会互相穿过去。
// 前方没有片段时工程零点仍是下限，不能把工程时间写成负数。
// 后方没有片段时用Infinity表示没有邻居限制，但源内容上限仍会生效。
// 右侧上限由工程起点加剩余源内容换算而来，不从当前尾部累计取整误差。
// 已用完源内容时继续向右拖会停在原边缘，不能通过改变速度伪造更长素材。
// 同时受到源与邻居限制时取更近的一侧，不能先过邻居再回弹。
// 夹限发生在共同模型，鼠标候选和键盘提交没有两套边界公式。
// 无效ID、锁轨、非有限秒数或非法帧率直接拒绝，不把错误转换成零秒。
// 锁定的判断读取当前片段所属轨道，跨轨移动后仍由新轨权限控制。
// 有效结果只换目标对象，其余片段保持原引用，源素材与构图对象没有改写。
// spread保留音频分离标记和transform，修剪不应把画面跳回中心或恢复静音状态。
// 原数组不被排序，已有层级和素材插入顺序不会因拖边缘变化。
// 不做波纹编辑：相邻片段不前移补洞，也不后退为本次延长让位置。
// 不做滚动编辑：邻居的入点和出点都保持原值。
// 不做速率伸缩：缩短只改变使用区间，不挤压视频每秒的播放速度。
// 不创建新的媒体文件，原路径和文件字节保持完整，伸回边缘仍能找回未使用部分。
// 返回null不同于空数组，调用方不能把拒绝误解释为删除全部片段。
// 左修剪的推导：旧区间从start到end，使用源从source到source加区间长度。
// 把左边缘改到position后，使用长度变为end减position。
// 为了让原结束画面不变，新的源入点必须增加(position-start)乘speed，不能把工程秒直接当源秒。
// 理论上position等于start-source/speed时源入点归零；实际向上对齐项目帧，避免读到负源时间。
// 左侧源边界使用start减source除speed，不能只夹到工程零点。
// 若前方邻居更晚结束，还必须把这条源边界推到previous。
// 左侧真正下限因此是max(previous,ceil(start-source/speed))，这里全部使用工程帧。
// 左侧上限end-1保证至少保留一项目帧。
// 右修剪的推导：已用源帧是source加(end-start)乘speed，入点与播放跨度都使用源时间。
// 源可用长度是sourceDuration减sourceIn，除speed后再对齐工程帧。
// 右边缘最高位置等于start加这段长度，左边缘调整时这条源终点不变。
// 像把原胶卷放在刻度尺后面：左边只改变露出的起始画面，胶卷没有被拉长。
// 1.37倍速的3.25秒源要占72个30fps工程帧，缩短后也必须能恢复到72帧。
// 若先把源长取整、再把剩余长度向下取整，会错误地只恢复71帧。
// ceil与素材创建、改倍速的末帧占位一致，最后不足一帧只占一格，不能再延长。
// 这个末格属于工程对齐，不会生成超出源结尾的新画面或改动播放速度。
// sourceIn在小数倍速下可能不是整数项目帧，重复取整会让左边零位移也换内容。
// 因此只将工程start/end/request取整，源入点始终按精确秒数换算。
// 若后方邻居先开始，following提供更严格右边界。
// 右侧下限start+1同样保留一帧，不允许倒置区间。
// 请求时间先round到项目帧，边界夹限后除fps回到工程秒数。
// 输出sourceIn只在左边缘改变，右侧调整必须保留原入点。
// 两个方向都保留clip.start/end之外的属性，不丢同源实例的独立构图。
// 同一轨道已有合法非重叠是本编辑器工程不变量，模型不会在修剪时修复坏历史数据。
// 若将来接入工程文件读取，应由读取校验保证这个不变量再进入编辑流程。
// sourceDuration来自成功探测，非法元数据不能通过本函数变成合法素材。
// 这里对time/fps检查有限性是因为它们可能来自指针和键盘计算。
// edge由类型联合与内部手柄固定值提供，不来自任意JSON字符串。
// locked是当前轨道锁列表，不是素材文件只读标记，两种权限不同。
// 修剪只是非破坏引用，磁盘文件只读并不妨碍修改当前临时工程区间。
// 不在模型里弹窗或写用户提示，调用方决定就近展示原因与候选。
// clamp成功即使位置没变也可返回新目标，交互层可以保持边缘反馈。
// 返回原对象数组以外的新数组可让React观察到确认更新，不依赖原地赋值。
// 新对象中transform仍沿用同一不可变值，因为修剪没有改变其内容。
// 复制片段的transform克隆由duplicate负责，不能把这条职责混进修剪。
// 原sourceDuration保持原值，缩短工程不等于文件被裁短。
// 延长回源边界依赖保留的sourceDuration，若错误覆写会无法找回未使用帧。
export function trimClip(clips: readonly LiveTimelineClip[], id: string, edge: "start" | "end", time: number, fps: number, locked: readonly string[]): LiveTimelineClip[] | null {
  const clip = clips.find(item => item.id === id);
  if (!clip || locked.includes(clip.track) || !Number.isFinite(time) || !Number.isFinite(fps) || fps <= 0) return null;
  const frame = (value: number) => Math.round(value * fps);
  const start = frame(clip.start), end = frame(clip.end), source = clip.sourceIn * fps;
  const requested = frame(time);
  const previous = Math.max(0, ...clips.filter(item => item.track === clip.track && item.id !== id && item.end <= clip.start).map(item => frame(item.end)));
  const following = Math.min(Infinity, ...clips.filter(item => item.track === clip.track && item.id !== id && item.start >= clip.end).map(item => frame(item.start)));
  const speed = clip.speed ?? 1;
  const limit = edge === "start" ? Math.max(previous, Math.ceil(start - source / speed)) : start + Math.ceil((clip.sourceDuration - clip.sourceIn) * fps / speed);
  const position = edge === "start" ? Math.max(limit, Math.min(end - 1, requested)) : Math.max(start + 1, Math.min(following, limit, requested));
  const updated = edge === "start" ? { ...clip, start: position / fps, sourceIn: (source + (position - start) * speed) / fps } : { ...clip, end: position / fps };
  return clips.map(item => item.id === id ? updated : item);
}

// 高层先返回用于命中，渲染时反过来画；透明区域自然露出低层，不以selected排序。
// 数组先按视频轨头的物理顺序查找，返回顺序始终是上层到下层。
// 渲染使用反向顺序铺底，浏览器自然让上层的透明像素透出下层。
// contains采用半开区间，结束帧处不再同时绘制前后两个同轨片段。
// audioOnly必须排除，即使旧记录误留视频前缀也不能画一个音频占位覆盖视频。
// 某条视频轨没有覆盖当前时刻就跳过，不用该轨最近选中的片段补空白。
// 不接收selectedId，所以选择不可能在这里改变叠放优先级。
// 返回的是当前工程记录，播放器仍按sourceIn与start换算源内时间。
// 这里没有混音或媒体时钟，视觉层列表不能被描述为音频总线已经接通。
// tracks顺序来自时间线行顺序，新增视频在已有视频下方，所以新层默认是更低层。
// 即使新文件刚导入、刚拖动或刚被选中，也不能因此盖到原上层前面。
// 同轨片段在共同模型保证不重叠，因此每轨通常至多一个当前可见安排。
// 跨轨可以同时覆盖，返回多个记录是合法组合，不属于同轨冲突。
// 未包含在tracks的陌生轨道不参与输出，不能靠伪造clip.track将图层插到最高处。
// A轨即使包含video源也不画画面，因为工程安排audioOnly与素材容器类型不同。
// 输出中保留完整clip对象，CSS变换、透明度和源入点使用同一份确认数据。
// 复制过滤结果不会原地sort clips，属性选择与键盘移动依赖的稳定数组顺序保持。
// 时间恰等于end时不再命中，这和相邻片段接触合法的半开区间契约一致。
// 时间小于start不提前显示封面，不能因该层选中就突破时间覆盖条件。
// 透明度零仍返回该层供操作反馈，内容透明不等于该实例被工程删除。
// 锁轨也不排除该层，锁只保护编辑，不是可见开关。
// 新增hidden参数默认空表，保留已有纯模型和样板调用的默认可见行为。
// 过滤先按真实tracks执行，不把隐藏片段从工程clips永久移除。
// 隐藏表可含音轨ID，但视觉列表始终先识别视频轨，因此不会画出音频占位。
// 锁表刻意不作为入参，锁定和显示契约互相独立。
// 默认参数不建立共享可变数组，函数从不向hidden或tracks写值。
// 相邻同轨片段end/start接触合法，半开区间让同一时刻只出现后段。
// 跨视频轨时间重叠保留多层，不按assetId去重同源实例。
// 层序只由tracks决定，clips数组插入位置不能抬高某个实例。
// 隐藏上轨后下一可见轨自然成为最上层，不需要重写每个clip的层级。
// 显示恢复后原tracks顺序直接恢复，没有最近操作置顶副作用。
// 过滤结果仍保留独立transform与sourceIn，供共享画布和源时间映射读取。
// 每个片段以自身id区分，多份同源安排不共享可修改的变换状态。
// 本函数只选择参与者，像列出本场演员名单；什么时候开场仍由工程时钟决定。
// 演员名单不等于已经演出，真实解码就绪必须由媒体状态另行确认。
// 该纯规则可被未来离线输出消费，但本轮没有编码或输出一致性证明。
export function visualClipsAtTime(clips: readonly LiveTimelineClip[], tracks: readonly TrackId[], time: number, hidden: readonly string[] = []) {
  return tracks.filter(track => isVideoTrack(track) && !hidden.includes(track)).flatMap(track => clips.filter(clip => clip.track === track && !clip.audioOnly && time >= clip.start && time < clip.end));
}

// 候选轨放在同类轨的下边，鼠标下移就能继续落下；取消时不写进工程。
// 候选视频行插在最后一条视频轨下面、第一条音轨上面，符合向下换视频层的直觉。
// 候选音轨放在音轨组末尾，不能插进视频组改变已有层序。
// 候选与正式行复用TrackRow，所以高度、拖放校验和横向秒尺完全一致。
// 没有手势或没有名额时直接沿用原列表，不制造一条永远可见的空候选。
// 只构造显示数组，不把临时ID写进正式工程，Escape无需删除一条假轨道。
// 正式插入也采用同一分组方向，松手后片段不会突然跳到音轨下面。
export function displayTracks(tracks: readonly TrackId[], kind?: "V" | "A", limits = DEFAULT_TRACK_LIMITS): readonly TrackId[] {
  const candidate = kind ? nextTrack(tracks, kind, limits) : null;
  if (!candidate) return tracks;
  return kind === "V" ? [...tracks.filter(isVideoTrack), candidate, ...tracks.filter(track => !isVideoTrack(track))] : [...tracks, candidate];
}

"use client";

// 候选构图只服务一次画布手势；确认数据继续归原时间线工程，不新增全局仓库。
import { useState } from "react";
import { defaultTransform, isTransformKey, TRANSFORM_KEYS, type ClipTransform } from "./clip-transform-model";
import type { LiveTimelineClip } from "./live-timeline-model";
import type { CanvasEdit } from "./clip-canvas";
import type { EditorPreviewProject } from "./editor-panels";
import type { PropertyKey } from "./editor-property-model";

// 仅依赖片段身份、当前锁与变换命令，不获得时间安排/导入/媒体文件的写入权限。
// 同源两次入轨各有独立clip.id，不能以assetId作为候选草稿归属。
// 画布当前播放片段可以不同于属性选中项，必须按各自ID查候选而非全局“当前值”。
// selectedClip用于属性目标，节目中的多个有效图层分别取得canvas回调。
// 素材查看不传canvas回调，仍显示原始源；这里不读取素材列表的高亮。
// 接口不暴露update整个项目的方法，候选层只能请求修改构图或改变片段选择。
// 这种窄接口让时间线仍是唯一确认数据拥有者，避免出现两个工程仓库互相覆盖。
// 图层由实际clip.id建立编辑回调，不从assetId构造一个假的选中片段。
// selectedClip可以为空，此时属性只显示项目事实，不能默认编辑首个素材。
// 锁状态按完整轨道表传入，不能仅让时间线按钮变灰而属性仍可写。
// 视频多轨仍由时间线会话管理，构图接口不能自行申请轨道或修改时间安排。
interface TransformSession {
  selectedClip: LiveTimelineClip | null; lockedTracks: readonly string[];
  speed: (id: string, value: number) => void;
  transform: (id: string, patch: Partial<ClipTransform>) => void; selectCanvas: (id: string) => void;
}
// 草稿记录原始clip对象引用，不只记录id，可识别同ID已被新确认快照替换。
// 例如字段先确认了新缩放，旧手势的origin不再有效，应立即停止显示旧候选。
// 这种失效检查比只比较数值更稳，确认相同值也可能代表一次新的提交边界。
// 候选完整保留五个值，X/Y移动时不会让旋转和透明度暂时恢复默认。
// 它不保存时间线秒数，手势取消不能意外把片段移回另一个时间。
// 候选也不保存源文件路径，生命周期结束不需要删除用户文件。
// 一次只允许当前选中画面的候选有效，不让上一对象的透明纸盖住新对象。
// 真正提交以timeline最新权限为准，候选有效不代表锁定后还有写入权。
// 鼠标移动没有工程成功通知，松手后的共享命令才决定是否接受补丁。
// 外部重置造成对象替换后，旧候选自然失效，不覆盖已经重置的画面。
// 组件退出时局部state销毁，没有全局缓存需要跨页面手动清除。
// 片段身份与源身份分开，重复入轨的第二份对象不会沿用第一份手势基准。
// 播放器时间更新不替换片段对象，所以正常播放不会让当前候选无故失效。
// 切换主题同样不换clip引用，外观变化不属于工程确认命令。
// 锁表另行判定，锁操作无需伪造一个新transform才能使旧候选失效。
interface TransformDraft { original: LiveTimelineClip; value: ClipTransform; }

// 像在透明纸上临时描一份新位置，松手才把它抄回工程，取消只拿走透明纸。
// draft持有开始时的片段引用，确认片段换了就自动失效，不用反向修补旧工程。
// 锁表或选择变化后也不采用旧候选，避免隐藏面板里的草稿继续改画面。
// candidate值同时给预览与属性读取，所以拖动时X/Y变化不是另一份假的数值。
// 属性提交会先丢掉手势候选，再调用同一transform命令，避免候选覆盖新确认值。
// 回调按当前选中ID绑定；切换到另一个实例时不能使用上一实例闭包写入。
// 构图参数与速度分流到各自命令，音量和淡入淡出仍按真实能力禁用。
// 轨道锁的视觉禁用不是最终权限，transform纯模型还会再检一次当前锁表。
// 本Hook不写本地JSON、不修改源文件，也不建立第二套时间线数据。
// 选择对象改变时，旧draft的original仍是旧引用，因此读取新对象会自然回到确认值。
// 同一对象被别的编辑确认后引用也变化，旧手势草稿不能覆盖新确认数据。
// 这像给草稿写上订单编号和原版本，只有仍对应同一张订单时才拿来预览。
// 候选只存在页面hook状态，React刷新画面不等于已经提交工程或保存文件。
// 轨道锁定会让value忽略候选，画布组件随后取消指针捕获，避免旧手势迟到松手。
// 主题切换不改片段引用，因而普通浅深切换不会丢掉确认构图。
// 预览尺寸变化不参与defaultTransform，窗口改变后X/Y数值不重新计算。
// 属性的临时字符串仍由EditorFloatField拥有，候选层只接收已经解析的数值。
// 非法字符串不会进入这里，模型仍保留有限数和范围复核作为最后门槛。
// 构图拖动不维护第二份工程时间，松手后仅替换某条片段的transform对象。
// 没有选择素材的回调，所以画布点击不能覆盖素材列表当前高亮。
// 没有seek回调，所以画布选择和构图不会把节目书签跳回片段起点。
// 与时间线选片段不同，画布选中对象是就地选中，当前正在看的帧保持不变。
// 如果节目当前是黑场，活动层为空，不会构造可编辑画面。
// 音轨不进入节目画面栈，不能为音轨创建可移动视频选框。
// 候选记录只保存小对象，拖动不会复制封面Base64或视频字节。
// 值对象用展开生成，不能将指针变化原地写进clip.transform。
// 这样取消只移除draft，不需要记住一串反向修改来恢复原构图。
export function useClipTransform(timeline: TransformSession, project: EditorPreviewProject) {
  const [draft, setDraft] = useState<TransformDraft | null>(null);
  const locked = (clip: LiveTimelineClip) => timeline.lockedTracks.includes(clip.track);
  const value = (clip: LiveTimelineClip): ClipTransform => draft?.original === clip && !locked(clip) && timeline.selectedClip?.id === clip.id ? draft.value : clip.transform ?? defaultTransform(project);
// 字段提交会明确结束旧候选，防止用户先拖一半再输入X时旧候选还盖住新确认值。
// 字段名来自共用PropertyKey集合，先缩窄到TransformKey才能构造片段补丁。
// 速度走独立时间映射；音量和淡入淡出不会被当成构图字段写入。
// 这里不把超范围数强行夹到边界，字段负责就地错误，模型负责拒绝非法确认。
// 使用当前selectedClip，让属性目标不被节目书签浏览偷换。
// 若对象已经取消选中，回调只清候选，不默认修改另一份片段。
// 锁定是否允许写入由timeline.transform最终复核，不只依赖此刻输入框是否disabled。
// 构图与倍速从同一个字段回调分流，但进入不同业务校验。
// speed不是ClipTransform的一部分，不能为了方便把它混进坐标对象。
// 时间线speed命令会检查碰撞，坐标命令只检查画面范围与轨道锁。
// 两种命令都按当前selectedClip绑定，素材查看不改变属性的工程目标。
// 清掉旧画布草稿以后再确认数值，避免屏上仍显示拖动一半的候选。
// 返回确认值从工程重新读取，失败的速度请求不会停留为假成功显示。
// 数值框草稿source与确认value不同就显示原值，状态条保留业务拒绝原因。
// 音频字段不在构图键集合，不能从这个入口获得画面坐标。
  function commitField(key: PropertyKey, number: number) {
    const clip = timeline.selectedClip;
    setDraft(null);
    if (clip && key === "speed") timeline.speed(clip.id, number);
    if (clip && isTransformKey(key)) timeline.transform(clip.id, { [key]: number });
  }
// 重置按当前组的字段键生成补丁，不把变换重置扩大成所有效果参数清零。
// 基础适配由项目决定，因此重置不是把位置设到源宽高的一半。
// scale恢复100时仍保持contain定义，不会变成按源像素一比一显示。
// 旋转与透明度回到零/一百，X/Y回项目中心，这是一组可预测的无额外构图。
// 组内尚未确认的字符串草稿由InspectorSection的epoch重建清理，业务层只处理确认值。
// 音频的组没有五个构图键，所以不会通过重置意外得到一份视频变换对象。
// 对锁定组的重置同样会被模型拒绝，不因为这是默认值就绕过锁。
// 重置播放速度需要重新计算时长，所以不能只把输入框写成1。
// 如果恢复1倍速会撞上同轨邻居，命令同样可以拒绝并保持原安排。
// 速度组与构图组分开，重置一组不能悄悄影响另一组。
// 构图默认值由项目像素定义，预览窗口大小变化不能改变重置中心。
// 锁轨后的重置仍走工程复核，不因目标是默认值而获得例外权限。
// 被复制片段按自己的id重置，不能把同源所有副本一并重置。
  function reset(keys: PropertyKey[]) {
    const clip = timeline.selectedClip;
    setDraft(null);
    if (!clip) return;
    if (keys.includes("speed")) { timeline.speed(clip.id, 1); return; }
    timeline.transform(clip.id, resetTransform(keys, project));
  }
// 每个CanvasEdit绑定具体实例，不能用最近拖过的assetId找到所有同源记录一起改。
// preview(null)用于结束草稿，不等于把片段删除，也不取消素材列表的选中。
// 画布点击只通知selectCanvas，不重新调用时间线select造成不必要的媒体seek。
// 指针候选保留完整五个值，移动X/Y时缩放、旋转和不透明度不丢失。
// 最终commit仍调用与字段相同的timeline.transform，因此范围、锁和数值精度一致。
// 选框是否选中是展示信息，绝不用于决定视频轨谁盖住谁。
  function canvas(clip: LiveTimelineClip): CanvasEdit {
    return { value: value(clip), selected: timeline.selectedClip?.id === clip.id, locked: locked(clip), select: () => timeline.selectCanvas(clip.id), preview: candidate => setDraft(candidate ? { original: clip, value: candidate } : null), commit: candidate => timeline.transform(clip.id, candidate) };
  }
  return { value: (clip: LiveTimelineClip) => ({ ...value(clip), speed: clip.speed ?? 1 }), canvas, commitField, reset, editable: timeline.selectedClip && !timeline.selectedClip.audioOnly && !locked(timeline.selectedClip) ? [...TRANSFORM_KEYS, "speed" as const] : [], locked: !!timeline.selectedClip && locked(timeline.selectedClip) };
}

// 重置构图只组装当前组允许的字段，速度重置由独立时间映射命令负责。
// 默认值按项目中心生成，不能取源分辨率中心或拿播放器屏幕尺寸代替。
function resetTransform(keys: PropertyKey[], project: EditorPreviewProject) {
  const defaults = defaultTransform(project), patch: Partial<ClipTransform> = {};
  for (const key of keys) if (isTransformKey(key)) patch[key] = defaults[key];
  return patch;
}

"use client";

/** 正式工程会话管理V1与分离音轨的安排；素材入库、媒体读取仍由LIVE-01拥有。 */
// 鼠标轮廓是便签草稿，松手盖章后才写进工程；取消只撕掉便签。
// 工程没有持久化插件，离开页面即释放，样板不会订阅此会话。
import { createElement, useEffect, useReducer, useRef, useState, type DragEvent, type KeyboardEvent, type MouseEvent, type RefObject, type ReactNode, type PointerEvent } from "react";
import { DEFAULT_TRACKS, DEFAULT_TRACK_LIMITS, sameTrackKind, isVideoTrack, nextTrack, trimClip, type TrackId, type TrackLimits } from "./timeline-track-model";
import { useClipTrim } from "./use-clip-trim";
import { changeClipSpeed } from "./clip-speed-model";
import { TimelineSettings } from "./timeline-settings";
import { defaultTransform, updateClipTransform, type ClipTransform } from "./clip-transform-model";
import type { EditorPreviewProject } from "./editor-panels";
import { t } from "@/i18n";
import type { EditorMediaAsset } from "./editor-panels";
import { resolveTimelineCommand, applyTimelineEdit, readTimelinePayload, TIMELINE_DRAG_TYPE, timelineDropTime, timelineDuration, type LiveTimelineClip, type TimelineCommand, type TimelinePayload, type TimelineEdit } from "./live-timeline-model";
// 右键锚点只属于当前页面，菜单关闭后不保留DOM或媒体引用。
// 展示复用公共菜单外壳，工程修改继续在本Hook的共同提交边界完成。
import type { LiveClipMenuAnchor } from "./live-clip-menu";

// 草稿显示位置和失败原因，不能让无效红框成为真正的工程片段。
// start与length使用工程秒数，拖动期间冻结的尺子不会追着候选缩放。
// track保存实际命中行，视频落到A1/A2时也能显示明确的拒绝反馈。
// length是取整后的占位长度，真实源时长始终留在素材与片段上。
// 轮廓的数据量与视频大小无关，一小时视频也只携带起点和长度。
// valid只是此时快照的结论，最终松手仍要重新计算并验证。
// reason已按当前语言翻译，用于轮廓内文本与固定status栏同步显示。
// 负起点轮廓可能部分被滚动边界裁切，固定status仍保留错误说明。
// track用实际命中行，能把A1拒绝反馈留在用户刚经过的位置。
// 草稿不持有asset对象，关闭轮廓不等于从素材库移除文件。
// length不是工程总长，宽度仍需除以统一视口range才能得到百分比。
export interface TimelineDraft { start: number; length: number; track: string; valid: boolean; reason: string; }
// 共同交互接口只表示意图，公共时间线不知道真实导入或文件路径。
// 拖动起止回调同时传给素材行和片段壳，避免复制原生拖放接线。
// keyDown留在片段按钮，不在搜索框输入时抢走方向键。
// range控制标尺、片段和播放头三者的同一个分母。
// scrollRef只交给唯一滚动体，不用第二个隐藏时间轴追赶scrollLeft。
// selectedId属于片段，和素材高亮没有共享状态。
// MediaItem只调用start，不读取项目片段数组，素材行保持领域中立。
// EditorClipShell调用相同start但kind为clip，表示移动已有安排。
// 轨道把over和drop交回同一拥有者，因此共享会话与碰撞规则。
// leave只撤掉当前落点轮廓，继续拖回轨道时手势身份仍有效。
// cancel则结束整个手势，区别于暂时离开一条轨道。
// selectedId是受控值，公共壳不会维护另一份可能过时的局部选择。
// scrollRef只接到唯一滚动节点，自动滚动不查询页面上第一个同名容器。
// keyDown接收片段ID，方向键不会依据素材列表的高亮猜测目标。
// range是当前手势使用的尺子，拖动期间保持不变。
// notice属于工程反馈，不能覆盖LIVE-01的导入结果摘要。
// 接口不提供保存或导出回调，公共时间线不能提前启用这些业务。
export interface TimelineInteraction {
  // 定位和锁定回调属于当前工程实例，视口组件不能直接改片段数组。
  tracks?: readonly TrackId[]; limits?: TrackLimits; settings?: ReactNode; draggingKind?: "V" | "A";
  grab?: (event: PointerEvent<HTMLButtonElement>, id: string) => void;
  trimDraft?: LiveTimelineClip | null;
  trimStart?: (event: PointerEvent<HTMLElement>, id: string, edge: "start" | "end") => void;
  trimKey?: (event: KeyboardEvent<HTMLElement>, id: string, edge: "start" | "end") => void;
  seek?: (time: number) => void;
  hiddenTracks?: readonly string[]; toggleVisibility?: (track: string) => void;
  lockedTracks?: readonly string[]; toggleLock?: (track: string) => void;
  selectedId: string | null; range: number; draft: TimelineDraft | null; notice: string;
  scrollRef: RefObject<HTMLDivElement | null>;
  select: (id: string) => void;
  start: (event: DragEvent<HTMLElement>, kind: "asset" | "clip", id: string) => void;
  over: (event: DragEvent<HTMLDivElement>, track: string) => void;
  drop: (event: DragEvent<HTMLDivElement>, track: string) => void;
  cancel: () => void;
  leave: (event: DragEvent<HTMLDivElement>) => void;
  keyDown: (event: KeyboardEvent<HTMLButtonElement>, id: string) => void;
  // 可选入口保持样板兼容；键盘菜单键与右键绑定相同的实例身份。
  // 公共片段壳只转发事件，不持有菜单或实现工程编辑。
  contextMenu?: (event: MouseEvent<HTMLButtonElement>, id: string) => void;
}
// 手势快照包含工程与素材的引用，不复制视频或改动旧数组。
// 一次手势从同一个快照验证，只有drop才提交到当前会话。
// clips在拖动中不能被键盘并行修改，避免冻结快照覆盖另一条新命令。
// 指针最后位置供自动滚动重新换算，滚动后不会继续沿用旧DOM矩形。
// lane是当前实际行，不把轨道头或导航算进时间原点。
// updated是渲染侧最后一次dragover时间，停止事件后自动滚动会停止。
// 滚动不依赖rAF，后台或遮挡窗口也能按上限结束等待。
// payload只属于当前会话，drop会再次解析实际DataTransfer防伪造。
// 手势快照好比取号时的一张订单：原工程、源身份和抓取位置一起固定。
// clips保存的是开始时数组引用，hover不会把其中对象原地改写。
// assets同样保留引用，验证只查状态和时长，不重新探测文件。
// command预先固定新片段ID，鼠标经过十个位置仍是一份创建意图。
// range用于冻结展示刻度，pixels用于冻结实际换算，两者各司其职。
// pixels是每秒对应的CSS像素，不是设备像素，所以无需再乘DPR。
// offset来自片段按钮内部的实际抓取点，不能用片段中心默认替代。
// lane会随着鼠标进入V1/A1/A2更新，跨行反馈不会沿用旧轨道。
// x保存屏幕客户区坐标，和getBoundingClientRect属于同一坐标系。
// updated用于约束自动滚动的活跃期，不表示视频播放时间。
// 手势并不拥有文件句柄，清理时没有需要重复关闭的FFmpeg任务。
// 播放器属于LIVE-01实例，这个快照不会暂停或seek源视频。
// track在抓取时固定；音频副本也只能在它自己的A1或A2内水平移动。
// 鼠标跨行只得到无效反馈，不让轮廓跟着漂到另一条轨道。
// 一次内部拖放携带来源类型和来源轨道，两者不能混成同一个“当前轨”。
// track保留来源身份，目标从当前lane读取，拖到新层不能先把来源改成目标。
// locked是起点快照，手势中锁定操作会主动取消；提交仍读取实时锁表。
// 素材入轨属于add，没有源轨锁限制；移动属于move，来源和目标都必须可编辑。
// 例如V1锁住时仍可把素材直接放到空闲V2，但不能把V1已有片段拖出去。
// command不提前写目标轨，hover时按实际命中lane构造候选，避免草稿沿用旧轨碰撞结果。
// range和pixels冻结一次拖动的秒尺，新增候选行不应改变这条横向比例。
// 候选增加纵向内容时CSS预留滚动条槽，保证冻结比例的布局前提持续成立。
// 抓取偏移来自片段按下位置，不等于整个片段宽度或固定一半。
// DOM合成dragstart没有真实pointerdown时保留原事件坐标兼容路径。
// 原生DragEvent坐标可能是整数，提前保存PointerEvent的小数偏移可避免一帧漂移。
// 抓取记录属于手势ref，不渲染成工程数据，也不计入项目保存格式。
interface Gesture { payload: TimelinePayload; command: TimelineCommand; clips: LiveTimelineClip[]; assets: readonly EditorMediaAsset[]; fps: number; range: number; pixels: number; offset: number; length: number; lane: HTMLDivElement | null; x: number; updated: number; track: string; locked: readonly string[]; }

// 同一个函数同时服务dragover和自动横滚后的草稿更新。
// lane矩形已经反映滚动量，重复加scrollLeft会让落点越滚越偏。
// 位置先按帧取整，再交给真正提交也使用的纯校验函数。
// 视频源只能入V1；分离音轨只能沿原音轨移动，不通过跨轨暗中转换类型。
// 失败轮廓仍显示预计起点，用户可以看懂是重叠还是轨道不支持。
// assets只用于验证引用身份，不触发ffprobe或解码。
// 总长不会在这里提交，因此无效右拖不会拉长工程信息条。
// view的length来自起点快照，不随当前片段重新测像素宽度。
// pixels是手势开始的秒/像素比例，和本轮标尺保持一致。
// 没有lane意味着鼠标已离开轨道，不凭旧坐标继续画有效落点。
// 自动滚动改变的是lane矩形left，故每次草稿都重新读取该矩形。
// 读取布局只发生在事件或定时回调内，首帧渲染不依赖DOM。
// 先算start再构造候选命令，create和move复用完全相同的坐标入口。
// 候选命令只替换start，不能随鼠标跨行把V1改成音频轨。
// 业务校验成功还不够，实际命中行也必须等于起始轨道才显示有效样式。
// 这避免视频拖到A1或A1音轨拖到V1时误用原轨空隙而显示蓝框。
// 无效原因优先说明轨道限制，其次说明模型返回的碰撞或参数问题。
// 同一草稿既供固定状态栏也供轮廓消费，二者不各算一份时间。
// start保留项目帧精度，显示两位小数只是一种简短提示格式。
// 真正提交不从这段格式化文本读回秒数，避免两位小数丢帧。
// length来自起始快照，不根据CSS最小宽度反推媒体长度。
// 若已经leave使lane为空，就返回null，不在旧轨道继续画残影。
// 先读当前lane的轨道编号，再把该编号交给共同碰撞模型。
// 若先按旧轨计算再换目标，跨轨空位可能被旧轨邻居错误挤到末尾。
// 不同类型的目标仍可展示无效轮廓，但永远不能在drop时创建实例。
// 目标锁定的轮廓必须明确无效，不能等松手才悄悄拒绝一个显示合法的候选。
// reason优先显示锁定，再显示类型，再显示模型碰撞结果，与真实拒绝原因一致。
// start使用解析后的合法起点，遇到同轨障碍仍保留既有最近完整空位行为。
// 草稿track使用目标lane，让用户看见将要进入哪一层，而非留在原层画幽灵。
// length保持原片段时长，跨层移动不能通过缩短自己来伪造合法位置。
// 此方法供鼠标hover和自动滚动共同调用，不能让两者使用不同目标轨。
function gestureDraft(gesture: Gesture): TimelineDraft | null {
  // 起始track是抓取时的事实，不从当前鼠标经过的行推导通道变化。
  // 轮廓像滑在固定导轨上的尺子，横向可动，纵向始终留在原轨道。
  // 当前经过行仍用于判断valid，所以锁住纵坐标不代表跨轨经过可以提交。
  // 即使鼠标在错误轨道上，用户也能从原轨上的无效轮廓看出预计水平起点。
  // 自动滚动与dragover都从这里取同一个结果，不出现标尺动而候选不动。
  // 离开全部轨道时lane为null，轮廓清除而非继续显示一个过期有效落点。
  if (!gesture.lane) return null;
  const start = timelineDropTime(gesture.x, gesture.lane.getBoundingClientRect().left, gesture.pixels, gesture.offset, gesture.fps);
  const track = gesture.lane.dataset.editorTrackLane ?? "";
  const compatible = sameTrackKind(gesture.track, track);
  const locked = gesture.locked.includes(track);
  const result = resolveTimelineCommand(gesture.clips, gesture.assets, { ...gesture.command, track: track as TrackId, start }, gesture.fps);
  // 轮廓锁在所属行，跨轨经过也不会暗示可以垂直移动。
  // 新视频只允许V1，已有分离音频则只允许其当前音轨。
  // 横坐标继续使用真实滚动后的lane矩形，不复制第二套滚动层。
  return { start: result.ok ? result.clip.start : start, length: gesture.length, track, valid: compatible && !locked && result.ok, reason: locked ? t("toolBox.editorUi.trackLocked") : !compatible ? t(isVideoTrack(gesture.track) ? "toolBox.editorUi.videoTrackOnly" : "toolBox.editorUi.sameTrackOnly") : result.ok ? t("toolBox.editorUi.validPlacement") : t(`toolBox.editorUi.${result.reason}`) };
}

// 边缘自动滚动每次最多十八像素，不一次跳到工程末尾。
// 左边界取V1可见内容与滚动体的交集，sticky轨道头不是可落点区域。
// 鼠标停在边缘时仍重新读取lane矩形，所以候选和标尺一起向前。
// 超过一秒没有有效dragover就停，移出窗口不会无限滚动。
// scrollLeft天然受浏览器内容边界限制，不能越过负数或最大滚动量。
// 只有手势存在时调用，结束与卸载由effect清除定时器。
// 这段计时仅服务滚动，不伪造视频播放进度。
// 没有改变range或工程时长，横滚不会触发尺子缩放。
// 滚动区矩形描述可见窗口，lane矩形描述工程内容，两者不可互换。
// 左侧sticky轨道头覆盖内容，故可见边界至少从轨道头右边开始。
// 否则横滚后靠近“V1”文字时不会触发向左滚动，用户难以返回开头。
// 右侧阈值只决定速度方向，实际scrollLeft由浏览器限制到合法范围。
// 每次18px配合60ms节拍，速度有上限，不随视频帧率成倍加快。
// 当鼠标不在边缘32px内时step为零，手势可以停在中间精确落点。
// 没有lane表示不在任何可接收行，不能凭上次x继续自动滚。
// 最后over超过1秒也停止，防止窗口外不再派发事件时一直运行。
// 定时器仅更新视口和草稿，既不提交位置，也不推进源播放时间。
// 取消会清空gesture，下一次tick立即成为无操作，effect随后移除计时器。
function autoScroll(gesture: Gesture | null, scroller: HTMLDivElement | null) {
  if (!gesture?.lane || !scroller || Date.now() - gesture.updated > 1000) return;
  const box = scroller.getBoundingClientRect();
  const header = scroller.querySelector('[data-editor-track-head="V1"]')?.getBoundingClientRect();
  const left = Math.max(header?.right ?? box.left, gesture.lane.getBoundingClientRect().left);
  const step = gesture.x < left + 32 ? -18 : gesture.x > box.right - 32 ? 18 : 0;
  if (step) scroller.scrollLeft += step;
}

// 切换路由前仅提醒真实片段工程，不为仅导入素材伪造已保存状态。
// 普通导航链接在捕获阶段拦截，取消确认仍停在原实例，草稿与媒体保持。
// 新窗口、下载和同页链接不属于离开当前工程，不附加重复弹窗。
// beforeunload由浏览器显示系统提示，不能自造“已自动保存”的消息。
// 监听仅在已有片段时存在，空会话不会增加离开负担。
// 清理配对移除，不让下一个工具继续收到旧工程的确认。
// 确认只保护当前页面会话，没有偷偷写入localStorage或用户JSON。
// 应用主窗口强制退出的系统路径仍由Electron拥有，本层不扩展IPC。
// 页面内导航与系统关闭是两种事件，这里分别使用click和beforeunload。
// 点击监听用捕获阶段，能在Next链接执行路由切换前给用户取消机会。
// 从图标子节点点击也通过closest找到真实链接，不只判断事件target是a。
// Element判断排除纯文本等非元素target，避免对未知对象调用closest。
// Ctrl/Meta打开新页不离开当前工程，因此无需弹出未保存提醒。
// 带target或download的链接也不占用当前实例，保留其原生行为。
// 相同href不代表离开，不为重复点击当前导航制造无用确认。
// 取消时同时阻止默认行为与后续传播，路由不会绕过用户回答。
// 确认时不调用另一份导航API，继续交给原链接保持兼容。
// beforeunload只能请求浏览器显示离开提示，具体文案由浏览器决定。
// dirty只取是否已有片段，导入素材而未安排不会假装存在已保存工程。
// 监听在dirty变化时配对解除，空工程没有遗留的确认拦截。
// 这不是工程保存功能，确认离开后数据按本轮临时会话边界释放。
function useTimelineLeaveGuard(dirty: boolean) {
  useEffect(() => {
    if (!dirty) return;
    const unload = (event: BeforeUnloadEvent) => { event.preventDefault(); };
    // document订阅收到浏览器原生事件，片段右键收到React合成事件，二者不能混用。
    // 显式globalThis避免新菜单的类型import遮住原有DOM类型。
    // 注册与清理保留同一个函数引用，菜单扩展不改变离开确认的生命周期。
    const navigate = (event: globalThis.MouseEvent) => {
      const link = event.target instanceof Element ? event.target.closest("a[href]") : null;
      if (!(link instanceof HTMLAnchorElement) || link.target || link.download || link.href === location.href || event.ctrlKey || event.metaKey || event.button !== 0) return;
      if (!window.confirm(t("toolBox.editorUi.unsavedTimeline"))) { event.preventDefault(); event.stopPropagation(); }
    };
    window.addEventListener("beforeunload", unload); document.addEventListener("click", navigate, true);
    return () => { window.removeEventListener("beforeunload", unload); document.removeEventListener("click", navigate, true); };
  }, [dirty]);
}

// 状态属于本次正式入口；静态样板只使用可选接口，不调用此Hook。
// 会话UUID不放在可见HTML中，预渲染和水合不会因随机文本不一致。
// selectedClipId与素材选择通过不同方法更新，筛选不会改变工程引用。
// viewed区分已选片段与正在查看源，返回节目只结束查看，不清除选择。
// scrollRef只在事件/effect中读，渲染不借ref推导首帧。
// range至少三十秒并留十秒空位，为末尾拖动提供可达空间。
// 空位只是视口，不参与ProjectInfoStrip的真实总长。
// 真实duration仍只按最晚end计算。
// clips、selectedId、viewed和notice构成一次工程界面的最小快照。
// clips描述安排事实，selectedId描述属性目标，两者不能由源播放器决定。
// viewed控制是否正在看该片段源，关闭查看不清除属性目标。
// notice只保存最后一次工程操作反馈，不与导入摘要互相竞争。
// update使用部分字段合并，单独选择不会意外清空已有clips。
// 空初始数组保证LIVE-01导入不会自动带入DEMO_CLIPS。
// 当前状态仅在页面实例内存在，返回正式页会从空工程重新开始。
// 没有把工程塞入素材对象，筛选或更新封面不会改写片段起点。
// tracks是正式轨道顺序，不能把候选行混进去影响画面覆盖。
// limits与clips归同一会话拥有者，设置和实际命令不能各读一份上限。
// dragKind只提供可见候选类型，手势结束后由frozen为空阻止继续绘制。
// 原clips仍是唯一工程安排表，多轨没有建立第二份播放专用时间数组。
// selectedId继续只代表属性目标，层序读取tracks，不再优先显示所选视频层。
// currentTime仍是节目秒数，修剪后源时间由sourceIn补偿，不改变这份时间单位。
// 锁表以轨道编号存储，新增V2不会继承V1的锁，也不反向解锁原轨。
// 工程初始化从DEFAULT_TRACKS复制数组，不能由某个实例修改全局默认列表。
// hiddenTracks属于当前工程会话，不放进全局素材或生成队列状态。
// 该表与lockedTracks分开，隐藏不等于锁定，也不改变原碰撞限制。
// 隐藏轨的片段仍保留在clips，工程总长仍包含它们的时间安排。
// 显隐回调只修改隐藏表，不触发源入点、片段移动或选择切换。
// 视频图层装配先过滤隐藏表，省去隐藏源真实解码资源。
// 音轨可见性不在此启用，音频不参与画面层级。
// 空初始隐藏表表示所有正式轨道可见，不把旧默认轨设成隐藏。
// 同轨禁止重叠仍由resolveTimelineCommand检查，隐藏不是绕过碰撞的理由。
// 锁轨仍由提交边界检查，显示开关不授予字段或右键编辑权限。
// 多轨上限与候选新增入口继续复用原轨道模型，本轮没有第二份加轨状态。
interface ProjectSnapshot { dragKind?: "V" | "A"; tracks: TrackId[]; limits: TrackLimits; currentTime: number; seekVersion: number; hiddenTracks: string[]; lockedTracks: string[]; clips: LiveTimelineClip[]; selectedId: string | null; viewed: boolean; notice: string; }
// currentTime在工程中只有一份，标尺和节目时间码都观察这份书签。
// seekVersion不能由总时长或render次数推导，因为正常播放也会导致重渲染。
// lockedTracks保存轨道业务ID，不保存按钮DOM或某个片段的临时数组下标。
// 锁定V1意味着所有V1实例受保护，后续加进来的片段也需经过共同提交门槛。
// 上区布局不在这个快照里，分隔和临时面板不会改变工程未保存事实。
// viewed只决定是否查看工程源，不替代selectedId，返回节目仍保留属性目标。
// 素材sourceVisible由LIVE-01独立持有，两个领域通过有限回调协调优先级。
// snapshot不包含File或视频字节，复制片段只增加引用记录，不增加整段内存副本。
// reducer合并patch保留未涉及字段，所以锁轨不应把当前书签重置成零。
// currentTime的真实播放报告可以是非帧对齐的媒体秒数，显式seek才按项目帧舍入。
// 不能每次timeupdate都取整再seek媒体，否则会形成持续停顿。
// 工程时长仍从clips推导，不把currentTime当成片段最大结束时间。
interface ProjectContext { project: EditorPreviewProject; state: ProjectSnapshot; update: (patch: Partial<ProjectSnapshot>) => void; assets: readonly EditorMediaAsset[]; fps: number; onSelectClip: () => void; }
interface GestureContext { grab: RefObject<{ id: string; offset: number } | null>; project: ProjectContext; session: string; gesture: RefObject<Gesture | null>; scrollRef: RefObject<HTMLDivElement | null>; range: number; setRange: (range: number | null) => void; setDraft: (draft: TimelineDraft | null) => void; }

// 成功结果一次提交数组、选择和查看状态，失败只更新就地原因。
// 不先移动正式对象再回滚，重叠时工程始终保持原快照。
// 预览关闭与素材查看由宿主协调，本层不改素材高亮。
// 调用方可以传候选意图，但只有这个边界能够替换正式clips快照。
// 失败分支仅更新notice，保持当前选中实例和预览对象不变。
// 成功把新数组与新选择一起提交，避免出现选中尚未存在的片段。
// viewed同时开启，使预览引用的对象就是刚放置的实例。
// onSelectClip结束素材查看优先级，防止右侧预览仍停留在另一份素材。
// 这个回调不修改素材selectedId，列表的高亮不会被片段操作反向覆盖。
// notice通过有限翻译key输出，业务函数不返回磁盘路径或异常栈。
// 末尾添加与按键移动也从这里提交，不再各写一套状态更新。
// 不会调用播放方法，安排成功不等于用户同意开始播放或发出声音。
// 也不会写用户JSON，工程仍明确显示未保存。
// 最终提交重新确认来源与目标属于同一类型，hover通过不能替代这次校验。
// move检查源轨和目标轨，避免从锁轨移走，或往锁轨偷偷插入。
// add没有已有源轨，所以默认V1的锁不应封禁所有视频导入目标。
// 目标不存在时只允许当前nextTrack那一个编号，任意V999不能绕过数量设置。
// 两个条件分别守住已有轨权限和新轨分配权限，不能只看目标前缀。
// 解析结果通过后才插入新轨，任何拒绝或取消都不会留下空轨占名额。
// 源片段已有transform时直接保留，换层不重新套默认中心。
// 新创建片段才补默认构图，same-source的新实例仍得到独立对象。
// 选中与当前时间跟随新安排，素材列表高亮仍由其独立状态持有。
// 播放定位版本变化用于切到新安排起点，不表示保存或导出已经完成。
function commitTimeline(context: ProjectContext, command: TimelineCommand) {
  // 锁定检查放在提交入口，不只依赖片段按钮disabled，键盘末尾添加也需要保护。
  // add固定目标V1，move则从当前实例回查所属轨，不能根据鼠标当前经过行换轨。
  // 未知ID没有可绕过的默认轨道，后续resolve会明确拒绝未知移动。
  // 每次提交用当前state而不是旧gesture.clips，防止迟到事件覆盖最新工程。
  // resolve只产生候选数组，返回ok前不会写入任何正式片段位置。
  // 成功时把选择、预览意图、书签起点与新数组作为一个patch更新。
  // 这样属性和节目不会短暂指向尚未提交的新ID。
  // 书签跳到放置起点是显式查看意图，所以增加seekVersion，媒体随后保持暂停。
  // 选择源文件不在这个patch里，同源多实例移动不会改素材高亮。
  // 拒绝结果只更新notice，不把旧播放器卸载或把成功素材行标成error。
  // 位置提示只是工程内提交，没有磁盘保存、转码或视频文件移动含义。
  // 这一入口同时承接鼠标松手和键盘方向移动，不能给键盘保留旧重叠算法。
  const source = command.kind === "add" ? "V1" : context.state.clips.find(clip => clip.id === command.id)?.track;
  const track = command.track ?? source;
  if (!source || !track || !sameTrackKind(source, track) || context.state.lockedTracks.some(item => (command.kind === "move" && item === source) || item === track)) return;
  if (!context.state.tracks.includes(track as TrackId) && nextTrack(context.state.tracks, isVideoTrack(track) ? "V" : "A", context.state.limits) !== track) return;
  const result = resolveTimelineCommand(context.state.clips, context.assets, command, context.fps);
  if (!result.ok) { context.update({ notice: t(`toolBox.editorUi.${result.reason}`) }); return; }
  // 新安排初始化独立构图；移动只保留旧实例的构图，不按新时间重新居中。
// 新建可视片段才补默认构图，已有transform始终优先保留。
// 用item.transform存在性判断，不以其中x或opacity的真值判断是否初始化。
// 因此合法的x=0和opacity=0不会被当成缺省而恢复中心与不透明。
// audioOnly记录不补构图，即使其assetId仍指向含画面的视频素材。
// 默认对象每次独立创建，两次添加同一个源不共享可变模板。
// 项目尺寸取本工程参数，不从最近导入视频的宽高反推工程尺寸。
// 含已确认构图的复制或移动结果不会再次执行默认居中。
// 这个兼容补值发生在安排提交边界，不在每次render时改写已有数组。
// 失败的时间安排没有result，所以不会因先创建构图而留下半个片段。
// 演示DEMO常量不经过正式提交，不会被补值逻辑原地修改。
  const clips = result.clips.map(item => item.transform || item.audioOnly ? item : { ...item, transform: defaultTransform(context.project) });
  context.update({ tracks: context.state.tracks.includes(result.clip.track) ? context.state.tracks : insertTrack(context.state.tracks, result.clip.track), clips, selectedId: result.clip.id, viewed: true, currentTime: result.clip.start, seekVersion: context.state.seekVersion + 1, notice: t("toolBox.editorUi.placementDone") });
  context.onSelectClip();
}
// 选中现有片段不创建历史或另一份实例，未知ID不改变当前对象。
// 只打开该片段源查看，不把它的assetId写进素材列表的selectedId。
// 选择前检查ID仍在当前工程，过期DOM事件不会选中已不存在的对象。
// 选择只改变属性目标与查看状态，start/end不发生任何变化。
// 同源两个实例名称相同，选中仍由不同clipId分别表示。
// 宿主随后用assetId回查原素材，右侧头部显示实际文件名与封面。
// 素材列表可能正在筛选，片段选择不需要先让该素材行显示出来。
// 因此不会通过“点素材行”间接实现片段选择，避免污染另一套状态。
function selectTimeline(context: ProjectContext, id: string) {
  const clip = context.state.clips.find(clip => clip.id === id);
  if (!clip) return;
  context.update({ selectedId: id, viewed: true, currentTime: clip.start, seekVersion: context.state.seekVersion + 1 }); context.onSelectClip();
}
// 右键复制、分离和键盘删除共用一次工程提交，鼠标菜单没有第二份状态数组。
// 新身份由本会话生成，纯函数只负责检查与生成下一份快照。
// 失败只更新notice，选中对象和源播放器继续保留，不清空已有素材。
// 成功同时替换安排与选择，避免预览短暂引用不存在的音频实例。
// 删除成功没有选中项，因此关闭片段源查看；复制/分离选中新实例。
// onSelectClip只协调查看优先级，不改变素材列表的高亮。
// 分离是非破坏编辑，不调用文件删除、转码或新建输出目录。
// 在拖动结束后执行，避免菜单更新被尚未提交的旧手势快照覆盖。
// 工程时间仍由新数组的最大end计算，删除尾段后可以自然缩短。
// 操作不写用户JSON；关闭页面依旧有未保存提醒，不显示假保存成功。
// 相同动作重复点击会按当前状态重查，例如已分离视频不能再次产生音轨。
// 菜单在执行后关闭，错误原因仍留在时间线状态栏，便于用户换位置。
// 分离音频把当前tracks和limits交给原编辑命令，不再只查固定A1/A2。
// 已有空闲音轨优先使用；都占用时最多申请一个新的候选音轨。
// 结果成功后从实际clips收集新增轨，不能提前假设一定生成A3。
// 新轨插入仍走insertTrack，分离不会把音轨放进视频组破坏视觉层级。
// 删除片段不自动删除轨道，用户已有锁和轨道顺序不会突然消失。
// 复制留在源轨末尾，跨层移动能力不改变原复制菜单的语义。
// 每次编辑检查当前源轨锁，右键和键盘最终共用同一写入边界。
// 失败只更新就近状态提示，原片段的音频分离标记必须保持不变。
function commitTimelineEdit(context: ProjectContext, action: TimelineEdit, id: string) {
  // 菜单打开后可能已经有别的状态更新，因此在执行时重新读轨道锁和目标ID。
  // 复制后预览新副本起点，不沿用旧片段中的0.8秒进度冒充副本开始画面。
  // 分离后新音轨与原视频时间相同，但ID与媒体通道不同，预览生命周期必须独立。
  // 删除后selectedId为null，属性回项目事实，素材库原文件依然存在。
  // 如果被删的是末段，旧书签可能超过新总长，Math.min把它收回有效范围。
  // 如果工程被删空，总长零，书签也归零，不能留下悬在空轨上的旧蓝线。
  // 这里仍不自动恢复已分离视频的声音，音轨删除与视频静音是独立安排事实。
  // 错误分离不更新数组，禁止出现视频已静音却没有成功创建音轨的半次结果。
  // seekVersion增加让当前媒体知道这次查看是明确命令，不是正常进度回报。
  // 选择新对象不等于开始播放，真实play仍要由用户明确点击。
  // lockedTracks保持原值，复制或删除不能顺便解锁整个轨道。
  // 源预览优先级与素材高亮是两套状态；回调只结束素材查看，不改素材selectedId。
  // 选中新音轨后，宿主按该实例的audioOnly适配属性和真实媒体类型。
  // 删除后没有片段目标，属性头回空态，而不是退回上一次已删除的名字。
  // 复制成功的selectedId是新身份，使方向键下一次移动副本而非原片段。
  // 拒绝分离时不调用onSelectClip，原本正在查看的对象不会被无故切换。
  // 未保存提醒根据最终clips长度计算，删到空工程时不继续拦截离开。
  // 状态栏用editDone而非placementDone，删除操作不会误称为位置已移动。
  if (context.state.lockedTracks.includes(context.state.clips.find(clip => clip.id === id)?.track ?? "")) return;
  // 锁表与片段快照在同一次提交中读取，不能传菜单打开瞬间缓存的锁状态。
  // 源轨预检查负责快速退出，纯模型再次检查是最后一道共同门槛。
  // 分离会写目标音轨，所以必须把全部轨道锁交下去，不能只传源轨是否锁定。
  // 目标A1/A2的选择留在模型，菜单和键盘只表达分离意图，不自行猜落在哪一轨。
  // 模型拒绝只更新提示，后面的currentTime、seekVersion和选中实例均不会执行。
  // 这样锁住音轨的失败不会触发播放器切源，也不会把素材列表选中改为音频。
  // 原项目快照仍由会话持有，错误文案不能被当作已完成分离的替代结果。
  // trackLocked与overlap分开显示，让用户知道应解锁轨道还是调整同轨占用。
  // 新UUID只是候选身份，失败时不会插入数组，也没有待清理的媒体文件。
  // 本次仅补锁权限，没有启用多轨同时播放、跨轨移动或源文件提取。
  // 任何后续编辑入口继续调用这里，才能同时继承源轨和目标轨的限制。
  const result = applyTimelineEdit(context.state.clips, context.assets, action, id, crypto.randomUUID(), context.fps, context.state.lockedTracks, context.state.tracks, context.state.limits);
  if (!result.ok) { context.update({ notice: t(`toolBox.editorUi.${result.reason}`) }); return; }
  // 副本/新音轨从新实例起点查看；删掉末段则把书签收回新总长，不能悬在工程之外。
  const currentTime = result.clips.find(clip => clip.id === result.selectedId)?.start ?? Math.min(context.state.currentTime, timelineDuration(result.clips));
  const tracks = result.clips.reduce((current, clip) => current.includes(clip.track) ? current : insertTrack(current, clip.track), context.state.tracks);
  context.update({ tracks, clips: result.clips, selectedId: result.selectedId, currentTime, seekVersion: context.state.seekVersion + 1, viewed: result.selectedId !== null, notice: t("toolBox.editorUi.editDone") });
  context.onSelectClip();
}

// 右键锚点与工程状态分开，关闭菜单不会丢失选择、位置或真实媒体元数据。
// 菜单引用当前片段ID，执行时仍由共同提交函数重新校验，不信任旧菜单快照。
// 打开菜单先取消拖动，防止一个手势同时产生右键编辑和延迟松手两份提交。
// 右键按实例选中，与左键选中采用同一方法；素材选择仍保持独立。
// 客户区坐标直接交给ContextMenuShell，公共外壳会处理窗口四边与Portal裁切。
// Shift+F10和菜单键从按钮矩形定位，不假造鼠标事件或读取全局鼠标位置。
// Delete只在片段按钮聚焦时处理，搜索框里的删除键仍用于编辑文字。
// 组合键Ctrl/Meta/Alt不劫持，系统快捷键继续交给原应用或操作系统。
// Escape与点击外部由公共菜单外壳负责，本Hook只处理关闭后的焦点恢复。
// 触发按钮已被删除时不恢复到脱离DOM的节点，避免无效焦点请求。
// 鼠标点到外部输入框会按浏览器默认行为获得焦点，不添加模态遮罩。
// 各页面实例分别持有锚点，不以全局变量记“最近右键的片段”。
// 音频菜单和视频菜单共享开关流程，能力差异由片段参数与真实音轨信息决定。
// 内部没有网络请求或文件句柄，卸载时React释放锚点，公共外壳清理全局监听。
// 开始新的拖动也关闭旧菜单，防止菜单遮住轨道落点或保留旧目标。
// 键盘开菜单后焦点进入第一项，关闭后回到原按钮，保持可继续逐帧移动。
// 删除和复制回调不接受任意数组写入，只接受有限动作名称。
// 标尺与播放头都没有从右键菜单读位置，修改工程后仍由同一range驱动。
// 键盘入口只解释按键，锚点和焦点恢复继续交给拥有菜单状态的Hook。
// 菜单键按当前按钮矩形定位；Delete与方向键仍调用原工程命令，不复制时间模型。
// 单独保留这个事件边界，避免菜单状态编排把键盘分支和锁轨判断堆成过长函数。
// open由当前实例注入，不能通过全局“最近菜单”查找目标。
// 普通输入框不调用此方法，Delete不会误删正在输入的素材名。
// Shift只用于F10或原移动步长，Ctrl/Alt/Meta保留给应用和系统。
// 删除仍要求没有活跃手势，旧拖动结束不能覆盖刚完成的删除。
// 未识别按键由moveByKey继续判断，不添加全局preventDefault截断Tab路径。
function timelineClipKey(context: GestureContext, event: KeyboardEvent<HTMLButtonElement>, id: string, open: (id: string, x: number, y: number, trigger: HTMLButtonElement) => void) {
  if (event.target !== event.currentTarget || event.ctrlKey || event.altKey || event.metaKey) return;
  if (event.key === "ContextMenu" || (event.shiftKey && event.key === "F10")) {
    event.preventDefault();
    const rect = event.currentTarget.getBoundingClientRect();
    open(id, rect.left, rect.bottom, event.currentTarget);
  } else if (event.key === "Delete" && !context.gesture.current) {
    event.preventDefault();
    commitTimelineEdit(context.project, "delete", id);
  } else moveByKey(context, event, id);
}
function useTimelineMenu(context: GestureContext) {
  // anchor.trigger保存的是被右键的按钮，不能用document.activeElement猜同名目标。
  // 片段右键可能发生在封面span上，绑定处提供currentTarget保证拿到完整按钮。
  // 打开菜单时选择片段会更新属性，但不会立刻播放或开启声音。
  // ContextMenuShell的聚焦发生在Portal布局后，菜单尚未挂载前不抢焦点。
  // 关闭恢复使用preventScroll，避免时间线突然横滚回触发按钮的默认位置。
  // 目标被删除时isConnected为false，跳过恢复，不向旧DOM发送方向键。
  // Shift+F10定位在片段左下角，公共外壳会在窗口底边自动向内调整。
  // Delete操作先检查是否有活跃手势，不能边拖边删再把旧快照提交回来。
  // 菜单打开动作主动取消旧手势，因此点击菜单不必再等待dragend。
  // perform执行有限动作后关闭锚点，迟到的第二次点击不能继续使用旧菜单实例。
  // 外部文件拖入不进入此菜单状态，继续由LIVE-01统一导入并逐文件反馈。
  // 左右方向键分支仍回到moveByKey，音轨没有一套独立的帧步长实现。
  const [anchor, setAnchor] = useState<LiveClipMenuAnchor | null>(null);
  const close = () => { setAnchor(null); if (anchor?.trigger.isConnected) anchor.trigger.focus({ preventScroll: true }); };
  const open = (id: string, x: number, y: number, trigger: HTMLButtonElement) => {
    if (context.project.state.lockedTracks.includes(context.project.state.clips.find(clip => clip.id === id)?.track ?? "")) return;
    // 先结束仍聚焦的字段草稿，再打开菜单；否则失焦提交可能在菜单挂载后触发滚动关闭。
    // preventScroll保留横向时间位置，右键选择不把片段强行滚回视口中心。
    trigger.focus({ preventScroll: true });
    cancelGesture(context); selectTimeline(context.project, id); setAnchor({ id, x, y, trigger });
  };
  const contextMenu = (event: MouseEvent<HTMLButtonElement>, id: string) => { event.preventDefault(); open(id, event.clientX, event.clientY, event.currentTarget); };
  const keyDown = (event: KeyboardEvent<HTMLButtonElement>, id: string) => timelineClipKey(context, event, id, open);
  const perform = (action: TimelineEdit) => { if (anchor) commitTimelineEdit(context.project, action, anchor.id); close(); };
  return { anchor, close, perform, contextMenu, keyDown };
}
// reducer合并当前快照，避免近乎同时的选择和反馈互相覆盖。
// 正式数组初始为空，不读取DEMO或用户持久化工程。
// reducer使用当前快照合并patch，不依赖闭包里更旧的notice或viewed。
// 数组仍由命令函数产生，reducer不在合并时偷偷排序、去重或改时间。
// 初始选择为空，属性区由宿主显示未选片段而不是第二个演示素材。
// assets由LIVE-01会话传入，只读使用，不创建第二份媒体缓存。
// fps由工程配置传入，当前固定30，不跟随选中的24fps源改变。
// onSelectClip是宿主协调函数，Hook本身不认识素材列表的内部状态结构。
function useTimelineProject(assets: readonly EditorMediaAsset[], fps: number, onSelectClip: () => void, project: EditorPreviewProject): ProjectContext {
  const initial: ProjectSnapshot = { tracks: [...DEFAULT_TRACKS], limits: { ...DEFAULT_TRACK_LIMITS }, currentTime: 0, seekVersion: 0, hiddenTracks: [], lockedTracks: [], clips: [], selectedId: null, viewed: false, notice: "" };
  const [state, update] = useReducer((current: ProjectSnapshot, patch: Partial<ProjectSnapshot>) => ({ ...current, ...patch }), initial);
  return { state, update, assets, fps, onSelectClip, project };
}
// 结束只清理草稿和冻结比例，真实工程数组不需要恢复，因为尚未改写。
// ref先清空，迟到的drop和自动滚动就不能借旧手势提交。
// 取消不需要把片段从候选位置挪回来，因为候选从未写入正式数组。
// 先清ref再更新展示状态，迟到drop看到空手势就会拒绝。
// setRange(null)恢复正常工程视口计算，不把冻结的旧标尺留到下一次拖动。
// setDraft(null)同时移除轮廓与固定状态栏中的候选时间。
// 这里不改notice，已存在的操作结果仍可被用户阅读。
// 也不改选择，取消移动不会让属性面板突然换成另一实例。
function cancelGesture(context: GestureContext) {
  context.gesture.current = null; context.setRange(null); context.setDraft(null);
}
// 起点快照只取当前会话真实身份，拖动失败行或未知片段被原生取消。
// pixels来自V1内容列，不包含sticky头部的宽度。
// 抓取偏移以秒冻结，不能在移动中按新位置重新计算。
// 从真实滚动容器查V1内容列，样板或未挂载时间线无法启动有效手势。
// 素材行的id用于查assets，片段按钮的id用于查clips，两个查找不混用。
// ready检查在起点再做一次，不能只依赖draggable属性防止非法调用。
// 缺少lane或身份时preventDefault，浏览器不会继续一个无源拖动。
// asset创建命令生成新UUID，clip移动命令保留原UUID。
// pixels用内容列宽除range，避开全窗口宽度和轨道头宽度。
// 片段offset从当前按钮left计算，窄片段也保留真实抓取位置。
// 素材拖入没有既有工程位置，offset固定为零使鼠标代表新起点。
// 新建草稿长度向上对齐项目帧，与最终命令使用相同长度规则。
// lane初始为空，必须实际经过一条轨道后才产生可见候选。
// setData只写三项身份，不把路径、视频字节或整个工程暴露在拖动正文。
// effectAllowed分别为copy和move，让浏览器表达复制引用与移动安排的差别。
// 冻结range在发布手势后发生，随后的渲染使用同一标尺分母。
// 清空旧notice只结束上次工程反馈，LIVE-01导入信息不受影响。
// 原生抓取先保存PointerEvent偏移，再由dragstart写DataTransfer身份。
// 浏览器的整数dragstart坐标会丢小数，直接反算时会让细秒尺产生一帧漂移。
// 只对可信原生事件读取按下偏移，合成回归事件仍使用自己的明确坐标。
// 消费后立即清掉grab，下一次拖动不能误用上一次单击的位置。
// 来源视频、分离音频都按同一比例计算offset，不能把音轨固定从左端抓取。
// 新的候选轨只由dragKind显示，真实轨道此时仍未写入state.tracks。
// 来源锁定的move在写载荷前拒绝，不给后续drop留一个貌似合法的会话。
// 素材可拖时仍检查ready/video，加载或失败的行不能创建片段。
// 载荷只存session/kind/id，不包含原始磁盘路径或可执行代码。
// 隐藏原生拖影只是防止系统截图影子遮住时间轮廓，真实片段仍留在原位。
function startGesture(context: GestureContext, event: DragEvent<HTMLElement>, kind: "asset" | "clip", id: string) {
  const { state, assets, fps } = context.project;
  const lane = context.scrollRef.current?.querySelector<HTMLDivElement>('[data-editor-track-lane="V1"]');
  const clip = kind === "clip" ? state.clips.find(item => item.id === id) : undefined, asset = assets.find(item => item.id === id);
  if (clip && state.lockedTracks.includes(clip.track)) { event.preventDefault(); return; }
  if (!lane || (kind === "asset" ? asset?.state !== "ready" || asset.kind !== "video" : !clip)) { event.preventDefault(); return; }
  const payload = { session: context.session, kind, id }, command: TimelineCommand = kind === "asset" ? { kind: "add", id: crypto.randomUUID(), assetId: id, start: 0 } : { kind: "move", id, start: 0 };
  const pixels = lane.getBoundingClientRect().width / context.range, offset = kind === "clip" ? (event.isTrusted && context.grab.current?.id === id ? context.grab.current.offset : event.clientX - event.currentTarget.getBoundingClientRect().left) / pixels : 0;
  context.grab.current = null;
  context.gesture.current = { payload, command, clips: state.clips, assets, fps, range: context.range, pixels, offset, length: clip ? clip.end - clip.start : Math.ceil((asset?.duration ?? 0) * fps) / fps, lane: null, x: event.clientX, updated: Date.now(), track: clip?.track ?? "V1", locked: state.lockedTracks };
  // 浏览器默认影子会随鼠标上下漂移，隐藏它，只显示锁轨的真实位置轮廓。
  // 透明画布只用于本次dragImage，不挂到DOM，也不保留视频封面副本。
  // 正式片段仍在原位，只有有效松手才提交水平位置。
  event.dataTransfer.setDragImage(document.createElement("canvas"), 0, 0);
  event.dataTransfer.setData(TIMELINE_DRAG_TYPE, JSON.stringify(payload)); event.dataTransfer.effectAllowed = kind === "asset" ? "copy" : "move";
  context.setRange(context.range); context.project.update({ notice: "", dragKind: isVideoTrack(clip?.track ?? "V1") ? "V" : "A" });
}
// hover只发布轮廓与dropEffect，不写clips，红框不等于错误工程已经产生。
// DataTransfer在保护模式不能读正文，本轮只认本地已有的起点快照。
// 先识别专用MIME，外部Files会继续冒泡到宿主的统一导入流程。
// 匹配内部MIME才preventDefault，表示这条轨道愿意处理内部落点。
// stopPropagation避免宿主把内部安排再次解释成文件导入。
// 浏览器dragover阶段可能禁止读取正文，所以此处只用已有本地手势。
// 没有手势时给invalid反馈，不根据当前列表首项猜测源。
// 每次over都刷新lane、x和updated，自动滚动据此追踪最后有效位置。
// 草稿通过统一函数生成，hover本身不直接判断重叠区间。
// 只有当前所属轨道的有效落点显示copy或move，跨轨与非法位置显示none。
// 鼠标光标只是辅助，文本原因仍保留在轮廓和status中。
// 无效位置也保留草稿，用户移动一点就能看到是否已离开冲突区。
// 内部MIME由时间线拥有，外部Files继续冒泡给素材导入宿主。
// dragOver必须preventDefault才能接收drop，同时stopPropagation防止外层误当文件导入。
// 没有活跃起点就拒绝，不能仅凭一个格式正确的MIME创建工程对象。
// 每次更新lane、x和时间戳，自动滚动才能读取最近目标而非上一行。
