// 此处没有存储调用，临时工程变换不等于工程已经保存。
  const { transform, selectCanvas } = timelineTransforms(project, assets, dimensions);
  return { speed: (id: string, speed: number) => commitSpeed(project, id, speed), transform, selectCanvas, lockedTracks: project.state.lockedTracks, seek, currentTime: project.state.currentTime, seekVersion: project.state.seekVersion, reportTime: (time: number) => project.update({ currentTime: time }), menu, clips: project.state.clips, duration, selectedClip: project.state.clips.find(clip => clip.id === project.state.selectedId) ?? null, viewed: project.state.viewed, closePreview: () => project.update({ viewed: false }), interaction, addAsset: (assetId: string) => { if (!context.gesture.current) commitTimeline(project, { kind: "add", id: crypto.randomUUID(), assetId, start: duration }); } };
}

// 项目快照与手势快照的交接只发生在commit边界，不把事件对象放进状态。
// React合成事件不在定时器中保存，自动滚动只保留必要的坐标标量和lane引用。
// lane引用在取消或卸载时释放，避免页面销毁后仍读取旧节点布局。
// UUID只用于当前运行的身份判断，不作为持久工程格式或跨进程授权令牌。
// 伪造同会话载荷也不能凭空创建手势，drop要求与现有起点kind和id相符。
// 从浏览器其他页面拖入普通文本没有专用MIME，不会调用工程创建命令。
// Files入口由宿主处理，当前Hook没有原始文件路径读取或导入能力。
// 工程宽度变动的取消策略优先保证准确，用户需要在新宽度下重新开始抓取。
// 窗口暂时失焦同样取消，不能在重新激活后提交失焦前的过期落点。
// 末尾按钮在拖动中不会与旧快照竞争，用户先完成或取消当前手势再添加。
// 键盘方向事件也遵守此门槛，避免一份手势里出现两个不同工程版本。
// 显示时间四舍五入只影响文案，命令保存仍保留项目帧对应的精度。
// 总长收缩不会删除空隙中的片段，始终取所有已提交end的最大值。
// 页面会话销毁后返回新工程，当前实现没有隐式localStorage恢复路径。

// 播放头是独立工程秒数，定位不改片段起止、不改变素材库高亮或属性选择。
// 像把书签放到一页中间，再按播放应从书签处读，不能总从这一章开头重读。
// 整数帧舍入由项目fps决定；视口空白不等于工程时长，定位夹在真实总长内。
// 每次显式定位增加版本号，媒体timeupdate只回报时间，不应反过来触发seek。
// 这把用户定位与媒体时钟分开，避免一次真实播放事件反复暂停并重设currentTime。
function seekTimeline(context: ProjectContext, time: number) {
  // 先拒绝非有限秒数，防止aria位置与CSS百分比出现NaN。
  // 项目帧舍入集中完成，标尺按键与指针位置不各取不同精度。
  // 定位上界取正式clips的最晚end，不用留有编辑空白的range。
  // 当前片段选择不参与夹限，用户可以定位到别的片段或真实空隙。
  // selectedId保持不变，属性不会跟着每次播放定位跳目标。
  // viewed开启工程查看，不改变素材面板里已经高亮的素材ID。
  // onSelectClip只结束素材源查看优先级，避免点击标尺却仍看到素材时钟。
  // seekVersion即使定位到相同秒数也增加，允许用户明确暂停并回到该书签。
  // 媒体进度报告不经过这里，否则每次timeupdate都会触发新的暂停定位。
  // currentTime是书签位置，version是用户命令身份，两者分离防止反馈循环。
  // 显式定位将同一工程秒数交给所有覆盖视频层；独立音轨试听不进入视觉层。
  // 本函数没有媒体ref，工程状态更新不直接操作浏览器解码器。
  if (!Number.isFinite(time)) return;
  const currentTime = Math.max(0, Math.min(timelineDuration(context.state.clips), Math.round(time * context.fps) / context.fps));
  context.update({ currentTime, seekVersion: context.state.seekVersion + 1, viewed: true });
  context.onSelectClip();
}

// 同一时刻按视频轨头顺序查找画面；显式选中音轨时保留原独立试听。
function insertTrack(tracks: readonly TrackId[], track: TrackId): TrackId[] {
  return isVideoTrack(track) ? [...tracks.filter(isVideoTrack), track, ...tracks.filter(item => !isVideoTrack(item))] : [...tracks, track];
}

// 画面补丁与选择意图分开，复用同一工程快照但不改时间安排。
// 构图更新继续只接受Partial<ClipTransform>，换层没有开放任意片段字段写入。
// 更新函数读取当前clips/assets/locks，不能用播放层身份覆盖属性选择。
// selectCanvas只就地选中，不把节目时间跳回层起点，方便在当前帧调整下层。
// 选择下层不会重排tracks，也不会改变主要播放器属于最高覆盖层的规则。
function timelineTransforms(project: ProjectContext, assets: readonly EditorMediaAsset[], dimensions: EditorPreviewProject) {
  const transform = (id: string, patch: Partial<ClipTransform>) => {
    const clips = updateClipTransform(project.state.clips, assets, id, patch, dimensions, project.state.lockedTracks);
    if (clips) project.update({ clips });
  };
  const selectCanvas = (id: string) => { if (project.state.clips.some(item => item.id === id)) project.update({ selectedId: id }); };
  return { transform, selectCanvas };
}

// 修剪与移动都只在确认边界替换工程；更新定位版本让播放器读取新的源入点。
// 字段修剪和键盘修剪共用纯模型，轨道锁在提交时再次检查。
// 新的clips只在有效结果时替换，null不能被当作空工程写入。
// 工程总长变短时书签夹到新末端，不能显示已经不存在的节目时间。
// seekVersion增加让同源同实例的播放器也重新定位到更新后的sourceIn。
// 修剪不更换素材文件，也不改变选择对象，检查器仍显示同一个片段的新时长。
// 左修剪确认后当前书签若仍在新范围内，保持工程时间，仅重算真实源定位。
// 如果删去的头部包含当前书签，预览可能变黑，这是区间不再覆盖而非元数据丢失。
// 若未来要自动把书签移到新入点，应作为显式交互约定，不能在纯模型里偷偷实施。
// 本次只对总长上界夹限，保留其他片段与空隙时间的原定位语义。
// 设置seekVersion不同于媒体timeupdate，不能由播放每帧回报反复增加。
// trimClip返回新数组后同源其他实例仍保持原对象，构图草稿依引用可识别当前版本。
// 选中ID不变，检查器时长由end-start重新计算而非源duration。
// 没有修改sourceDuration，因此以后向回延长仍知道未使用源的完整边界。
// 锁轨过程中trim.cancel先执行，最终模型保护只是第二道门槛而非唯一用户反馈。
// 边缘键盘回调同样进入这里，不另写一个绕过锁定的快捷键分支。
// 修剪提交只接收边缘、工程目标时间和片段ID，不让手势直接传一整份新工程。
// 模型按速度换算源入点，视图无需知道哪一帧应被读取。
// 左修剪同时调整sourceIn，右修剪只调整工程out，二者不能共用错误的字段补丁。
// 成功才增加seekVersion，取消或无效输入不制造一次无意义的媒体定位。
// 工程时长来自所有片段最远出点，裁短前片段未必改变整个工程长度。
// 当前节目位置超出新工程末尾时夹限，但不会重置素材列表的高亮。
// 锁表由工程传给模型，程序事件不能因为跳过disabled手柄而写入锁轨。
// 同轨邻居限制和源剩余限制都在纯模型中，像先看道路边界再看油箱余量。
// 不支持凭空延长源文件，向右拖到源末尾后继续拖动只停在合法边缘。
// 一次松手只确认一份片段区间，拖动过程的候选不反复写回工程。
function commitTimelineTrim(project: ProjectContext, id: string, edge: "start" | "end", time: number) {
  const clips = trimClip(project.state.clips, id, edge, time, project.fps, project.state.lockedTracks);
  if (clips) project.update({ clips, seekVersion: project.state.seekVersion + 1, currentTime: Math.min(project.state.currentTime, timelineDuration(clips)) });
}

// 只在指针事件中记住抓取点，不修改Hook返回的工程数据对象。
// 该ref记录的是CSS像素偏移，不是源秒数或项目帧，换算留在startGesture。
// 事件currentTarget是整个片段壳，不能取内部封面span的left。
// 例如从片段三分之一处抓取，鼠标落点减去这个偏移才是片段工程起点。
// 不保留PointerEvent对象，React事件结束后只留下id和一个有限数值。
// 下一次startGesture只接受id相符的记录，别的片段上一次单击不会串入。
// 消费后清记录避免后续合成拖放误读取旧按下位置。
// HTML拖放有自己的阈值，pointerdown与dragstart不是同一时刻，不能简单互相替代。
// 这里不preventDefault，原生HTML拖放还需要浏览器继续处理按下意图。
// 修剪手柄会stopPropagation，因此不会顺便建立整段移动的grab。
// 这个函数只改手势ref，不修改Hook返回的工程快照对象或Zustand状态。
// 抓取偏移在pointerdown保留小数CSS像素，原生dragstart整数字段不能代替它。
// 这是屏幕像素距离，开始拖动时才除以当时实际密度换算成秒。
// 同类跨轨使用同一内容列密度，不能因轨道编号变化重新从片段左边抓起。
// 可信原生dragstart消费这份偏移，测试合成事件仍按自己的显式坐标计算。
// 记录与片段ID绑定，旧片段按下后换一个片段不会误继承抓取位置。
// 读取currentTarget确保封面或标题span不会让偏移从错误子节点左边起算。
// 边缘修剪已经阻止事件冒泡，所以这里不会把修剪抓取误记成主体移动。
// 指针坐标不乘DPR，避免系统缩放时又将浏览器CSS坐标放大一次。
function captureGrab(context: GestureContext, event: PointerEvent<HTMLButtonElement>, id: string) {
  context.grab.current = { id, offset: event.clientX - event.currentTarget.getBoundingClientRect().left };
}

// 倍速提交与修剪都回到同一工程数组，属性面板不另存一个只改显示的速度。
// 提交后重新定位源时间，避免播放器继续沿旧速度对应的工程位置推进。
// 冲突时保持片段和所有邻居不变，状态条解释原因；不伪装已经应用。
// 速度命令使用最新project.state，不接收从旧菜单缓存的片段快照。
// 失败只更新附近状态条，不清空素材库，也不把其他轨道记录重建成默认值。
// 更新clips后duration由同一个timelineDuration推导，信息条和标尺不另记总长。
// 当前播放位置可能落在缩短后的工程之外，因此成功后先夹到新总长范围。
// seekVersion使同一个媒体节点重新应用新源映射，不必卸载再导入原文件。
// 构图位置、透明度与画面中心不参与速度计算，改速度不能改变项目构图。
// 音频分离后的实例独立，后续编辑不偷偷改变关联的另一个实例。
// 错误文案同时覆盖锁、范围与碰撞，属于拒绝原因概述，不是所有失败都有重叠。
// 属性输入依然显示真实确认值，状态条不把拒绝描述成一次保存失败。
// 这里没有波纹推移、撤销栈或导出任务，不能因速度生效推定完整剪辑链已接通。
function commitSpeed(project: ProjectContext, id: string, speed: number) {
  const clips = changeClipSpeed(project.state.clips, id, speed, project.fps, project.state.lockedTracks);
  if (!clips) { project.update({ notice: t("toolBox.editorUi.speedBlocked") }); return; }
  project.update({ clips, seekVersion: project.state.seekVersion + 1, currentTime: Math.min(project.state.currentTime, timelineDuration(clips)), notice: "" });
}

"use client";

// 单一工程时钟拥有播放意图；图层只登记真实video，不各自更新工程时间。
// 调度器按真实经过时间推进，并以媒体就绪状态为闸门，缓冲时不会伪造进度。
// 像过站换乘：先停在片段边界，等新列车开门后再走，空站台则正常经过。
import { useEffect, useRef, useState, type RefObject, type Dispatch, type SetStateAction } from "react";
import { attachSource, type LivePreviewTransport } from "./live-source-preview";
import { activeProgramLayers, nextProgramTime, pauseProgramMedia, playProgramMedia, programPhase, type ClockLayer, type ProgramClock, type ProgramMedia, type ProgramPhase } from "./program-clock";

// 输入layers是正式片段的轻量投影，仍引用原工程实例，不保存可独立编辑的副本。
// 传全部可见视频层才能计算未来边界，不能只传当前选中或当前活动层。
// transport来自现有工程书签，duration来自所有轨道安排的最大结束时间。
// 音轨尾部虽然无画面，仍属于工程时长，因此该段允许静音黑场。
// fps只用于精确定位的容差，源fps不会偷偷修改工程时间步长。
// rate是观看倍率，与片段自身的已有速度字段分开保存。
// 观看倍率不写工程，不会改动时间线片段长度或源区间。
// 控制器不接素材选择回调，播放过程中不能给素材列表强行换高亮。
// 控制器也不接属性提交回调，走钟不会生成属性草稿。
// 输入没有保存路径、输出选项或云端身份，这一阶段没有文件写回副作用。
interface PlaybackInput {
  layers: readonly ClockLayer[];
  transport: LivePreviewTransport;
  duration: number;
  fps: number;
  rate: number;
}
// phase告诉用户当前节目是否真的可显示，playing表示当前播放意图。
// 缓冲时保留播放意图才能在新层就绪后自然接播，不要求用户逐片段按播放。
// 界面仍允许在缓冲中按暂停，避免加载时无法取消先前播放请求。
// key标记这一份状态属于哪个定位与活动层组合，不能只凭phase字符串复用。
// 同一个time的小幅连续推进不一定改key，因为同组媒体不该每帧重建。
// 源时间是否跟上由真实节点校验，key本身不是成功证据。
// 状态里不放video引用，React重渲染不负责媒体资源的所有权。
// phase与playing相同时保留旧对象，减少没有视觉变化的无效重渲染。
interface PlaybackState { phase: ProgramPhase; playing: boolean; key: string; }

// 明确定位优先于正在播放的旧时间：递增请求号并关闭播放意图。
// 此处不向工程重复发送seek，防止两个定位回调互相触发造成抖动。
// 版本变化是用户明确定位或时间安排变化的授权，不是媒体通知。
// 同一个版本的工程进度回报只能更新显示，不能反复把媒体暂停并定位。
// 源时间在另外一层统一映射，本处只接收工程游标的新位置。
// 接受新请求先关intent，保证拖播放头时旧播放进度不会继续竞争。
// request增加后每个活动源都必须应用最新目标，旧seeked无法替新请求盖章。
// clock.time直接采用最新输入，不按历史请求排队逐个展示中间位置。
// 重置last防止用户拖动用掉的时间在下次播放时被补走。
// 暂停遍历全部登记源，刚离场但尚未卸载的节点也必须停下。
// 暂停不清src，明确定位仍尽量复用当前节点和缓冲。
// 此函数不调用onSeek，避免定位确认再触发定位命令造成循环。
// 此函数也不重写selectedId，书签与片段选择仍是两个状态。
// 用户连续拖过黑场时不用等待前一个区域加载完才处理最新目标。
// 只要React提交新输入，effect就接受版本，不需要等待媒体发出timeupdate。
// 返回页面时控制器新建，以当前书签为初始状态，不恢复旧播放意图。
function acceptProgramSeek(clock: ProgramClock, input: PlaybackInput, now: number) {
  if (clock.version === input.transport.version) return;
  clock.version = input.transport.version;
  clock.request += 1;
  clock.time = input.transport.time;
  clock.intent = false;
  clock.last = now;
  pauseProgramMedia(clock);
}

// 一次节拍只推进同一份工程时间，视频的timeupdate不参与竞争。
// 隐藏窗口直接停播，不靠后台rAF或计时器保持看不见的音视频读取。
// 跨边界先发布精确边界时间，下一次登记的真实节点决定能否继续。
// 等待期间重设last，解码完成后不会把等待的几秒一口气跳过去。
// duration来自工程所有片段，末尾音轨区间也能显示静音黑场。
// 节拍只看最近提交的输入，不能读取另一次尚未确认渲染的候选工程。
// 先更新源的真实倍率，再决定是否播放，暂停状态下的倍速预设也立即生效。
// 倍率变化不代表已经播放，因此不得顺带解除静音或自动启动。
// 存在错误或加载中时先停全部源，把经过的墙钟时间丢弃。
// 丢弃等待时间是为了保持工程暂停，不是把解码等待算成片段播放时长。
// 正常播放以单调经过时间推进，而非把多个timeupdate累加。
// 每节拍最多接收一小段经过时间，系统长时间卡顿后不会突然跨完整工程。
// 这是一种预览保守追赶策略，不承诺在严重过载时仍保持严格实时输出。
// 最近边界优先于候选时间，上层入场不能被一次较长节拍跨过去。
// 到边界后新层未登记会使phase转loading，旧层保持暂停直到合成可显示。
// 在黑场没有源可播放，但工程游标仍能向下一入点推进。
// 每次只通过原transport.onTime发布时间，不建立第二个时间线store。
// 源timeupdate没有发布权限，所以暂停中的迟到媒体事件不能回退书签。
// 工程尾部结束播放意图，并暂停所有剩余节点，不无限停在播放按钮状态。
// 末尾画面由半开区间过滤清空，不沿用最后选中片段的末帧。
// document.hidden会主动关播放意图，返回前台不在用户不知情时自动恢复。
// visibilitychange是快速停播通路，节拍中的读取是事件丢失时的兜底。
// 本节拍不改变源入点，修剪和移动仍由原共同业务模型拥有。
// 即使某视频已ended，工程其他有效层仍由同一时钟推进。
// 当前不建立音频设备时钟，因为节目尚无混音通路且全部静音。
function advanceProgram(clock: ProgramClock, input: PlaybackInput, phase: ProgramPhase, now: number) {
  if (document.hidden) clock.intent = false;
  const active = activeProgramLayers(input.layers, clock.time);
  for (const { clip } of active) {
    const entry = clock.media.get(clip.id);
    if (entry) entry.video.playbackRate = input.rate * (clip.speed ?? 1);
    if (entry && clock.intent && phase === "ready") playProgramMedia(clock, entry, entry.video.playbackRate);
  }
  if (!clock.intent || phase !== "ready") { pauseProgramMedia(clock); clock.last = now; return; }
  const target = clock.time + Math.min(.1, (now - clock.last) / 1000) * input.rate;
  clock.last = now;
  clock.time = nextProgramTime(input.layers, clock.time, target, input.duration);
  input.transport.onTime(clock.time);
  if (clock.time >= input.duration) { clock.intent = false; pauseProgramMedia(clock); }
}

// 媒体绑定复用素材播放器的attachSource，确保超时、事件和src释放只有一套机制。
// 表项按片段id独立，同一源的两个实例不能共享currentTime。
// 旧组件清理只删除自己的表项，不能误删随后注册的同id新重试节点。
// 强制muted同时禁用默认音量出口；本轮没有音频混音总线。
// 登记发生在真实video提交DOM之后，不在渲染期间创建播放器对象。
// 源URL直接来自原素材适配，不用文件名猜测或拼接本地路径。
// 缺失URL立即作为error登记，不能静默跳过这个层让合成貌似成功。
// 有URL但还未loadeddata时是loading，首次寻帧也要等metadata允许定位。
// 初始request负一确保第一次登记后应用当前工程目标。
// 每层deadline独立，慢源不能借另一层ready不断延后自己的超时。
// attachSource负责初次加载截止线，控制器负责后续定位截止线。
// 报告time和playing回调刻意为空，真实源事件不得拥有工程时钟。
// 源state回调只改本表项，不直接触发另一个实例的React状态。
// 旧源清理先核对map身份，重试同id时不能误删已经接班的新节点。
// 清理的detach解除事件和定时器，并暂停、移除src、load释放资源。
// 未注册成功也返回可调用清理，URL缺失分支不会留下一次空src加载。
// muted是节目约束，不继承素材查看时用户打开声音的偏好。
// 播放器控件不暴露原生controls，避免用户绕过节目时钟单独拖某层。
// 单一来源多实例仍逐clip登记，不按assetId复用一个只能指向单个时间的video。
// 本轮资源预算约等于当前有效视频数，未开始与已结束的源不常驻解码器。
function registerProgramMedia(clock: ProgramClock, id: string, video: HTMLVideoElement, source: string) {
  const entry: ProgramMedia = { video, state: source ? "loading" : "error", request: -1, deadline: performance.now() + 15000, failed: false, starting: false };
  clock.media.set(id, entry);
  const detach = source ? attachSource(video, source, { state: state => { entry.state = state; }, time: () => {}, playing: () => {} }) : () => {};
  video.muted = true;
  return () => {
    if (clock.media.get(id) === entry) clock.media.delete(id);
    detach();
  };
}

// useRef保存的是当前实例的调度器，不是全局缓存，A/B工程不会共享时间或媒体。
// React状态只报告phase与playing，时间仍回写原有timeline.reportTime。
// 输入通过effect发布，计时器无需每一帧拆装，也不读尚未提交的渲染候选。
// 定位后的旧媒体会立即被停止，旧seeked通过目标距离与请求号双重阻挡。
// Hook状态的生命周期与一个节目容器一致，素材查看切换会完整卸载它。
// ref初始last用零保持渲染纯净，真正播放授权在事件中读取performance.now。
// 浏览器API不在服务器预渲染期间访问DOM，周期安装只在effect运行。
// latest在提交后的effect更新，定时器只使用已经正式提交的片段列表。
// 同一个工程的普通时间更新不销毁定时器，避免每帧重新计时造成节拍抖动。
// 显式定位通过acceptProgramSeek接受，其余输入仅作为当前参数更新。
// attempt属于重试节点身份，不进入工程格式，也不影响素材库去重。
// 重试增加内部request，所有新节点必须重新对齐当前书签。
// register回调把当前clock交给媒体安装器，组件实例之间没有模块级可变状态。
// 返回的toggle修改播放意图，按钮图标随后由调度快照驱动。
// 返回phase还检查请求键，新版本不能借上一版本ready闪出旧帧。
// 普通构图草稿没有进入请求键，画布拖动不应反复出现加载遮罩。
// state更新只合并实际phase/playing/key变化，控制器本身不持有整个工程。
// 公开接口不允许绕过时钟直接获取并操纵所有video。
// 源组件卸载可独立清理，Hook卸载同时停止调度，双方无需等待对方确认。
// 没有跨页面缓存的播放意图，返回编辑器不会自动播放上一会话的源。
export function useProgramPlayback(input: PlaybackInput) {
  const clock = useRef<ProgramClock>({ time: input.transport.time, version: input.transport.version, request: 0, last: 0, intent: false, media: new Map() });
  const latest = useRef(input);
  const [state, setState] = useState<PlaybackState>({ phase: "loading", playing: false, key: "" });
  const [attempt, setAttempt] = useState(0);
  useEffect(() => { latest.current = input; acceptProgramSeek(clock.current, input, performance.now()); });
  useProgramScheduler(clock, latest, setState);
  return { ...state, phase: state.key === programRequestKey(input) ? state.phase : "loading" as const, attempt, register: (id: string, video: HTMLVideoElement, source: string) => registerProgramMedia(clock.current, id, video, source), toggle: () => toggleProgram(clock.current, latest.current), retry: () => { clock.current.request += 1; setAttempt(value => value + 1); } };
}

// 末尾再次播放从零开始，但不会改变片段选择或构图；定位本身始终保持暂停。
// 错误不自动重试死循环，由用户明确点击重试才重新加载源。
// 用户按播放时记录新的last，暂停期间经过的时间不会被算到下一次播放。
// 末尾重播仅把工程游标归零，不重排轨道、不修改任何片段或源文件。
// 归零增加内部request，让仍挂载的源也重新应用零时刻目标。
// 归零通过onTime发布工程书签，不伪造一次用户拖动播放头的外部版本。
// 如果开始位置是黑场，播放意图仍有效，直到时钟遇到下一素材入点。
// 停止意图立即pause已登记媒体，不等待下一个40ms节拍才执行。
// 未就绪时界面不给新的播放授权，但既有意图可以在等待时被用户取消。
// 错误发生后意图由报告层关闭，重试完成后仍要明确点击播放。
// 这个按钮只属于节目；素材查看的播放按钮继续调用单源播放器。
// 暂停不会把currentTime恢复到片段起点，用户可以在原书签继续观看。
function toggleProgram(clock: ProgramClock, input: PlaybackInput) {
  if (clock.time >= input.duration) { clock.time = 0; clock.request += 1; input.transport.onTime(0); }
  clock.intent = !clock.intent;
  clock.last = performance.now();
  if (!clock.intent) pauseProgramMedia(clock);
}

// 新定位或活动层改变时立即遮住旧帧，不必等下一次40ms节拍才切成loading。
// 构图变化不纳入请求键，否则每次拖动坐标都会不必要地重启解码等待。
// 请求键包含版本与活动片段身份，定位到相同片段的另一秒也能使旧结果失效。
// 活动列表改变意味着新的解码集合，必须隐藏上一集合的ready画面。
// 片段起止和sourceIn进入键，修剪或移动后不会借用旧源区间的完成状态。
// 位置、旋转和透明度不进键，空间调整只改变共享画布投影。
// 选中状态同样不进键，选择下层不是重新合成时序或抬高其图层的授权。
// 节目rate已由统一时钟执行，观看倍率变化不需要重新加载源。
// 键只用于内存中的快照比较，不作为工程持久化或媒体缓存文件名。
// 这里没有哈希磁盘视频，生成键的成本与片段数量有关，与文件字节大小无关。
// 字符串中只使用内部稳定ID和已确认数值，不把用户路径放入日志或DOM键。
function programRequestKey(input: PlaybackInput) {
  return `${input.transport.version}:${activeProgramLayers(input.layers, input.transport.time).map(({ clip }) => `${clip.id}/${clip.start}/${clip.end}/${clip.sourceIn ?? 0}`).join(',')}`;
}

// 调度和React报告分离，便于区分媒体是否就绪与按钮当前展示的播放意图。
// 请求键随正式输入更新，过期报告不会令新请求误显为ready。
// 先校验当前工程时间对应的全部媒体，再决定是否向下一个节拍推进。
// 只有ready状态会前进，错误与加载不会因为调度器一直运行而伪造进度。
// 当错误被观察到时关闭意图，防止用户未处理错误却自行恢复播放。
// playing报告意图而非某一个video.play事件，所有层必须服从同一授权。
// key取当前已提交输入，下一次渲染会再次比较，跨边界旧快照不能伪装新ready。
// publish的函数式更新能读取最新界面快照，不会用闭包覆盖稍后提交的状态。
// 控制器仍以clock.time作为工程真值，React快照只负责界面提示。
// 不在此追逐某个选中视频的currentTime，选中变化不能改变时钟来源。
// 媒体状态来自实际readyState与seeking；测试不能仅检查按钮文字判断成功。
// 报告层没有自动重试，连续失败不会形成无限装源循环。
// 控制器采用先核对当前帧、再推进下一节拍的保守顺序。
// 推进后若恰好进入新集合，UI请求键立即失效上一集合快照。
// 下一次报告检查新源，整个过程不需要借助选中片段触发切换。
// 工程游标可能停在某边界等待，但片段的start/end与sourceIn始终未改动。
// 不能为了消除等待而把上层开始时间推迟，这会改变工程内容。
// 也不能把下层结束时间提前来减轻解码负载，时序由工程确认值决定。
// 同轨冲突在编辑模型处理，控制器不会自行挑选冲突赢家掩盖工程非法状态。
// 跨轨同时活动时对全部节点检查，主层不存在特殊的免等待权。
// 实际帧播放与工程通知不使用同一个事件源，通知只由这根指挥棒产生。
// 源节点触发的pause或ended不会自行让整个工程退回片段起点。
// 如果只有下层在工程末尾继续，时钟保留其活动直到该层end。
// 如果工程尾部仅剩音轨，节目显示黑场静音，不暗中把音轨变成试听。
// 快照没有每个视频的原始错误对象，用户只看到统一失败状态。
// 测试可通过登记节点反证是否真的加载，不需要访问Hook私有闭包。
// Hook没有对window挂调试全局变量，正式程序不会暴露修改时钟的测试入口。
// 每次状态publish使用函数形式，避免同时到来的按钮更新被旧状态覆盖。
// 计时器闭包的clock是实例局部对象，不受其他工作区的播放按钮影响。
// 新工作区初始intent为false，旧工作区的异步play回执不能授权它播放。
// 重试attempt只改变媒体key，不改变当前属性草稿所属的片段ID。
// 错误源删除后其表项卸载，其他好源不会被持久错误状态拖住。
// 本轮没有预加载未来全部素材，因此越过边界可能看见短暂loading。
// 加载反馈属于真实等待，不能用封面把这段等待伪装成连续帧。
// 默认40ms节拍用于交互预览，不是导出编码的固定时间基。
// 将来离线导出必须按输出帧号驱动相同规则，不复用这个墙钟调度器。
// 性能测试结论只对应本轮两个小分辨率视频，不保证用户提高轨道上限后的满载。
function reportProgram(clock: ProgramClock, input: PlaybackInput, publish: Dispatch<SetStateAction<PlaybackState>>) {
  const now = performance.now();
  const phase = programPhase(clock, activeProgramLayers(input.layers, clock.time), input.fps, now);
  advanceProgram(clock, input, phase, now);
  if (phase === "error") clock.intent = false;
  const playing = clock.intent, key = programRequestKey(input);
  publish(previous => previous.phase === phase && previous.playing === playing && previous.key === key ? previous : { phase, playing, key });
}

// 安装时捕获具体时钟对象，卸载不能误停将来另一个实例的解码器。
// visibilitychange读取当下事实；即使事件缺失，下一节拍也检查document.hidden。
// 计时器不是媒体完成证明，programPhase未通过时advanceProgram不会推进。
// 周期只安装一次实例所需的调度器，publish由React保证稳定身份。
// 清理捕获安装时的clock对象，不能在卸载时意外引用后来的另一个工作区。
// visibilitychange读取当前document.hidden，不盲信事件携带的旧状态。
// 隐藏时立即暂停媒体，定时器兜底也会在下一次执行时核对隐藏事实。
// 卸载先清周期，再解除可见性监听，最后关意图并暂停全部源。
// 不等待requestAnimationFrame，后台窗口没有绘制回调时仍有有界错误处理。
// 40ms是控制调度频率，不代表媒体固定25fps；真实视频帧仍由浏览器解码。
// 当前工作区整棵树每节拍发布工程时间，有大量片段时可能增加主线程开销。
// 源生命周期独立卸载，scheduler不负责从DOM查询或重建媒体节点。
// 没有在这里申请系统扬声器、AudioContext或额外Worker。
// 事件和周期均由当前Hook拥有，返回页面会建立干净的新周期。
// 清理不回报新的工程时间，退出不应造成旧会话的迟到状态更新。
function useProgramScheduler(ref: RefObject<ProgramClock>, latest: RefObject<PlaybackInput>, publish: Dispatch<SetStateAction<PlaybackState>>) {
  useEffect(() => {
    const clock = ref.current;
    const tick = () => reportProgram(clock, latest.current, publish);
    const hidden = () => { if (document.hidden) { clock.intent = false; pauseProgramMedia(clock); } };
    const timer = setInterval(tick, 40);
    document.addEventListener("visibilitychange", hidden);
    return () => {
      clearInterval(timer);
      document.removeEventListener("visibilitychange", hidden);
      clock.intent = false;
      pauseProgramMedia(clock);
    };
  }, [ref, latest, publish]);
}

"use client";

// LIVE-02页面装配：真实素材和V1安排分别管理，工程持久化仍未接通。
// 各区域像同一工作台上的抽屉，外框固定，内容多时在各自抽屉内滚动。
// 上区、分隔条、时间轴和信息条的高度交给同一个 grid，避免各算窗口高度。
// 路由上方已有 AppShell，不重复创建导航、标题栏、品牌或系统按钮。
// 文案订阅现有语言状态，不为编辑器再建 Context 或另一套 locale。
// 临时工程状态归本页面会话，不把它写入全局生成或旧版剪辑store。
// 后续 UI-02–08 在这些区域边界接入局部状态，不整体复制页面装配。
import { useClipTransform } from "./use-clip-transform";
import { ClipInspector, MediaPanel, ProgramPreview } from "./editor-panels";
import { EditorWorkspace } from "./editor-workspace";
import { useLiveVideoSession } from "./use-live-video-session";
// 菜单共用现有Portal外壳，正式工程只注入当前目标与有限编辑意图。
// 样板和原视频/GIF入口没有这个会话，不会被自动开启右键编辑。
import { LiveClipMenu } from "./live-clip-menu";
import { type DragEvent } from "react";
import { ProgramCompositePreview } from "./program-composite-preview";
import { isVideoTrack } from "./timeline-track-model";
import { LiveSourcePreview } from "./live-source-preview";
import { useLiveTimeline } from "./use-live-timeline";
import styles from "./editor.module.css";

// 正式项目从0秒开始，宽高和帧率是工程设置，不从素材元数据暗中修改。
// 当前一律30fps对齐时间线，24fps素材仍保留自身帧率供源播放器显示。
// 工程常量中没有DEMO素材引用，真实导入和静态样板完全分开。
// 时长在装配时由正式片段数组覆盖，未安排任何素材时总长保持零。
const LIVE_PROJECT = { width: 1920, height: 1080, fps: 30, duration: 0, currentTime: 0 } as const;

// 编辑器 host 只建立容器查询边界，布局读取可用主区而非浏览器完整宽度。
// 默认保留三栏上区；空间不足时先隐藏属性，再隐藏素材，节目预览优先。
// UI-07临时入口由共享workspace注入，素材和属性复用原常驻节点。
// R05保留八像素命中槽，拖动和键盘布局调整由workspace统一处理。
// separator报告实测高度范围，媒体和工程状态不参与布局调节。
// 后续分隔逻辑只能改变 grid 比例，不能改项目或片段选择。
// host 高度不足时允许工作区整体纵向滚动，避免信息条被 overflow:hidden 吞掉。
// 正常高度下素材列表、属性内容和时间轴各自滚动，宿主 main 不产生第二条滚动条。
// 最小高度在本轮仅为骨架安全边界，UI-07 还须验证真实系统缩放和最低可用高度。
// 不在正式界面堆“当前为样例”的调试说明，未接通状态由动作禁用与原因表达。
// 静态占位也保留 R01–R10 编号数据属性，验收可逐区定位而不污染视觉原图。
// 正式入口从空库开始；源播放器卸载时停止读取，静态样板另有入口。
// LIVE-01拥有导入批次、素材选择和源读取，LIVE-02只拥有工程安排。
// 两者通过最小意图协调，片段选择结束素材查看优先级但不改素材高亮。
// previewAsset先尊重用户主动打开的素材，再考虑当前片段源查看。
// 返回节目同时关闭两种源查看意图，避免旧优先级让画面又跳回素材。
// clipAsset按assetId回查，不用标题匹配，支持重名文件和同源多实例。
// 属性头只绑定选中片段，用户浏览素材不会隐式生成安排或改属性目标。
// currentTime是独立工程书签，正式单段播放通过transport回报时间。
// 素材播放器key为assetId，片段播放器key为clipId，生命周期边界清楚。
// 外部Files即使落在V1也只调用统一startImport，不自动创建时间线片段。
// 内部载荷由轨道接管，不触发“正在导入文件”的全区覆盖提示。
// 宿主不读取File.path，路径解析仍走既有preload的getPathForFile。
// 新增会话没有存储副作用，离开确认仅提醒数据未保存，不假装已保存。
export function VideoEditorView() {
  const live = useLiveVideoSession();
  // 工程安排与素材库各自拥有选择，只有片段意图会更新右栏和节目对象。
  // 点片段先结束素材查看，再打开该实例引用的源，列表高亮保持不变。
  // 同源实例的播放器key仍不同，旧源先清理，不继承另一实例的播放位置。
  const timeline = useLiveTimeline(live.assets, LIVE_PROJECT.fps, live.returnToProgram, LIVE_PROJECT);
  const project = { ...LIVE_PROJECT, duration: timeline.duration };
  const transform = useClipTransform(timeline, project);
  const sourceAsset = live.assets.find(asset => asset.id === timeline.selectedClip?.assetId) ?? null;
  // 音轨安排需要音频属性头，但素材库仍保留原始视频卡片和元数据。
  // 这里只适配当前查看对象，不修改assets数组，也不新增虚构音频文件。
  // 源路径仍使用同一localfile地址，由单源播放器选择音频媒体元素。
  const clipAsset = sourceAsset && timeline.selectedClip?.audioOnly ? { ...sourceAsset, kind: "audio" as const, cover: null } : sourceAsset;
  // 全部视频层按明确tracks顺序装配，播放头由合成器筛选半开区间。
  // 这里不读取selectedId或素材高亮，选中下层不会使它浮到上层。
  // 隐藏轨道在进入解码器前排除；锁层继续参与显示，只禁止写入。
  // 缺失源仍交给合成器显示错误，不能悄悄把坏层跳过当成成功。
// tracks数组显式决定节目优先级，不读取素材导入顺序。
// 片段列表的DOM顺序也不作为图层契约；先按轨道分组后再按时间过滤。
// 即使选中音轨，节目仍按书签显示有效视频，不切成单源audio占位。
// 音轨选择只影响检查器，节目声音总线仍未接通。
// 缺失素材引用保留一个无源层，让预览准确报错而非悄悄漏掉一层。
// 正常素材失败批次不清空已有数组，所以引用不因另一次导入失败丢失。
// sourceVisible拥有独立优先权，但进入素材查看会卸载节目，不隐藏后台合成。
// 空工程仍复用原黑画布分支，没有媒体元素也不需要启动工程定时器。
// 有片段但书签在空隙时使用合成器，不能回退成选中片段单源预览。
// 检查器继续从selectedClip查asset，当前节目层名不会覆盖属性目标。
// 多个同源安排绑定各自transform.canvas，候选位置不按assetId共享。
// 源试看返回只改变查看模式，原素材高亮、片段选中和工程书签都保留。
// 本轮没有改变公共工作区外壳，导航与窗口控制仍由AppShell管理。
// 时间线动作仍使用原interaction，不向合成器复制移动或碰撞业务。
// 图层规则可供未来导出适配，但当前只有预览消费者，保存导出继续禁用。
  const layers = (timeline.interaction.tracks ?? []).filter(track => isVideoTrack(track) && !timeline.interaction.hiddenTracks?.includes(track)).flatMap(track => timeline.clips.filter(clip => clip.track === track && !clip.audioOnly).map(clip => ({
    clip, edit: transform.canvas(clip), asset: live.assets.find(asset => asset.id === clip.assetId) ?? { id: clip.assetId, name: clip.assetId, kind: "video" as const, duration: null, cover: null },
  })));
  const currentTime = timeline.currentTime;
  // 两种预览互斥显示，但共用同一组窄窗入口，不复制按钮体系。
  // 动作放在标题流内，文件名会让出实际宽度，英文标签也无需猜宽。
  // 入口回调由workspace提供；媒体播放与面板开合没有共享业务状态。
// 窄窗入口原先绝对定位在右上，会与长文件名占用同一块空间。
// 现在让它们参与标题行排版，文件名可压缩，按钮不覆盖文字。
// ProgramPreview和LiveSourcePreview接收同一个React片段，返回节目不更换控件外观。
// 这只是两种互斥预览中的插槽复用，不会把两个播放器一起隐藏挂载。
// 静态工程也注入相同布局入口，但不获得正式会话的导入或工程编辑回调。
// 素材与属性入口只控制显示，不启用面板中原本未接通的业务字段。
// 开合入口不会清空当前片段，也不会替用户切换素材高亮。
// 此处不按文件名长度估算宽度，中文和英文都交给真实flex几何处理。
// 标题区的滚动归属仍在共享预览容器，不创建独立横向滚动条。
// 外层nav开合改变可用宽度时，标题行会随容器重新分配空间。
  // 外部文件像送到货架的新包裹，只在真正松手时进入统一导入流程。
  // 内部片段拖动像挪动安排表，不是重新搬运视频文件，不能触发导入提示。
  // 不再记录整页dragging布尔值：子轨道会截住事件，外层未必收到对应的离开通知。
  // 取消遮罩后没有需要配对清除的视觉状态，Escape或离开窗口也不会留下提示。
  // dragOver只允许外部Files落下，不读取其中的路径或提前调用探测。
  // 路径仍在drop时经preload解析，不使用浏览器File.path或Node文件接口。
  // 真实导入的加载与错误继续由素材行表达，不靠全区覆盖模拟处理中。
  // 已有媒体节点不会因内部拖过轨道而卸载，播放时钟和当前画面因此保持原归属。
  function acceptDrop(event: DragEvent<HTMLDivElement>) {
    // 只有Files走既有导入链；内部身份拖放由时间线处理，不能误报非法文件。
    // 外部文件即使落在V1也只入库，后续明确添加才会产生片段。
    if (!event.dataTransfer.types.includes("Files")) return;
    event.preventDefault();
    const paths = Array.from(event.dataTransfer.files).map(file => window.electronAPI?.getPathForFile(file) ?? "");
    if (!paths.length) paths.push("");
    void live.startImport(paths);
  }
  return <div data-video-editor-ui="LIVE-02" data-live-video-session className={styles.host} onDragOver={event => { if (event.dataTransfer.types.includes("Files")) event.preventDefault(); }} onDrop={acceptDrop}><EditorWorkspace project={project} clips={timeline.clips} assets={live.assets} currentTime={currentTime} timeline={timeline.interaction} onImport={() => { void live.startImport(); }} busy={live.importBusy} onCancelImport={live.cancelImport}>
    {headerActions => <>

      {/* 素材区：正式会话传真实数组，样板组件默认数据保持独立。 */}
      <MediaPanel layout="cards" assets={live.assets} selectedId={live.selectedAssetId} onSelect={live.selectAsset} onAssetDragStart={(event, id) => timeline.interaction.start(event, "asset", id)} onAssetDragEnd={timeline.interaction.cancel} onAddToTimeline={timeline.addAsset} onImport={() => { void live.startImport(); }} onCancelImport={live.cancelImport} importBusy={live.importBusy} importNotice={live.importNotice} />
      {/* 素材预览只读源媒体时钟，返回节目后不改时间线片段选择。 */}
      {live.sourceVisible && live.selectedAsset ? <LiveSourcePreview key={live.selectedAsset.id} asset={live.selectedAsset} project={project} onBack={live.returnToProgram} headerActions={headerActions} /> : timeline.clips.length ? <ProgramCompositePreview layers={layers} project={project} transport={{ time: currentTime, version: timeline.seekVersion, onTime: timeline.reportTime, onSeek: timeline.seek }} headerActions={headerActions} /> : <ProgramPreview clip={null} assets={[]} project={project} currentTime={currentTime} emptyPresentation="black" headerActions={headerActions} />}

      <ClipInspector project={project} live editableKeys={transform.editable} locked={transform.locked} onCommit={transform.commitField} onReset={transform.reset} targets={timeline.selectedClip && clipAsset ? [{ id: timeline.selectedClip.id, asset: clipAsset, duration: timeline.selectedClip.end - timeline.selectedClip.start, values: transform.value(timeline.selectedClip) }] : []} />
      {/* 片段菜单：一次只绑定当前工程的实例，关闭或切页由公共外壳清理。 */}
      {timeline.menu.anchor && <LiveClipMenu anchor={timeline.menu.anchor} clip={timeline.clips.find(clip => clip.id === timeline.menu.anchor?.id)} asset={live.assets.find(asset => asset.id === timeline.clips.find(clip => clip.id === timeline.menu.anchor?.id)?.assetId)} onClose={timeline.menu.close} onAction={timeline.menu.perform} />}
  </>}</EditorWorkspace></div>;
}

"use client";

// 时间线胶片带从源视频抽取真实帧；它不使用播放器节点，也不改变节目播放位置。
// 所有片段排队共用一条解码队列，像共用一台冲印机，避免长工程同时打开几十个视频。
// 缓存只留64张160×90画布，约3.6MiB像素；不会读入整个视频或长期保留文件字节。
// 页面最后一条胶片带卸载即清缓存；进行中的任务收到取消后也释放媒体源。
import { useEffect, useRef } from "react";
import type { EditorMediaAsset } from "./editor-panels";
import styles from "./editor.module.css";

// 缓存只保存已解码的小图，不持有File、ArrayBuffer或完整视频Blob。
// 这里缓存的是像素，不是播放句柄；缓存命中不会恢复视频播放。
// 同一源被多次入轨可以复用相同时间点，但每条片段仍有自己的展示画布。
// 毫秒键是抽样展示精度，不参与正式剪辑的工程帧对齐。
// 缓存上限限制常驻图像像素，浏览器内部解码缓存不在这个数字内。
// 因此不能把3.6MiB当作本功能全部进程或显存占用的实测值。
// Map删除最早插入项，当前采用简单有界FIFO，不宣称是完整LRU。
// 页面无胶片带时主动清理，使下次进入工程不会保留旧用户源索引。
// 队列本身只保存待办闭包，不把所有任务的媒体字节预先下载到内存。
// 取消任务在实际取得队列席位后先检查signal，过时任务不再创建解码器。
// 前一个任务失败后队列仍可继续，坏视频不能阻塞整条工程缩略图。
// 任务只有一条顺序链，外层catch用于恢复链状态，不代表帧采样成功。
// users按有sourceUrl的胶片带订阅计数，静态样板封面不占这份缓存生命周期。
// StrictMode清理再挂载也会先取消旧任务，不让开发模式产生永久双订阅。
// 抽样缓存生命周期比某一个任务长，比一次编辑器会话短，这两个边界不能混在一起。
// 缓存键不使用本地磁盘哈希，因为抽取辅助帧不需要重新扫描大文件内容。
// 源URL若被其他程序原地替换而地址不变，本轮没有文件监视器自动失效机制。
// 因此当前缓存适用于会话内稳定源，不声称已经覆盖外部程序热替换同路径视频。
// 条目上限只按数量约束，固定160×90尺寸使每条像素成本大致一致。
// 若未来支持HDR或更高位深，不能沿用当前四字节每像素估算而不重新核查。
// Canvas缓存属于渲染进程小图，不会被保存到统一用户JSON中。
// 数据没有上传到云端，素材路径只供本地协议寻址，不参与远端搜索。
// 缓存不负责文件权限，是否允许读取由现有localfile协议边界处理。
// 队列顺序是请求顺序，当前没有优先队列抢占已经开始的可见片段抽样。
// 可见性取消能缩短等待，但不能保证每种编解码器的浏览器内部取消立刻释放所有内存。
// 没有测量驱动层显存，释放src只作为媒体生命周期行为，不报告为释放若干GB。
// 同一任务结束后video对象退出局部作用域，缓存不保留它的闭包引用。
// 一个任务异常不会自动重试到成功，新的尺寸或可见性请求才可能再次尝试。
// 这样坏源不形成无限重试循环，也不会持续挤占其他片段的解码机会。
const frames = new Map<string, HTMLCanvasElement>();
let queue: Promise<void> = Promise.resolve();
let users = 0;

// 等待真实媒体事件，取消、错误或五秒超时均拒绝，并成对清除监听与定时器。
// seeked与loadeddata才证明浏览器已拿到帧，固定延迟不能代替解码证据。
// 先挂监听再执行load/seek，短视频缓存命中也不会错过同步到达的通知。
// 把媒体事件等待当作有截止时间的收据，不是等一段时间就默认办好了。
// 事件名由内部固定调用传入，不接受用户指定任意DOM事件名称。
// loadeddata表示当前帧可读取；只有loadedmetadata仍可能没有任何解码像素。
// seeked表示这次定位完成；currentTime刚赋值并不表示对应画面已准备好。
// 同一等待同时注册媒体错误和取消，失败可以尽快释放串行队列的位置。
// 取消监听用once减少迟到回调，正常完成仍显式移除未触发的其他监听。
// 定时器由主线程的任务机制负责，不依赖隐藏窗口是否调度动画帧。
// 超时只表示辅助缩略帧不可用，不修改探测成功状态或现有节目片段。
// 这里产生的短错误只在本地收口，不把磁盘完整路径写入可见错误文字。
// promise只接收一次完成结果，success和abort紧接到达也不会重复推进队列。
// clearTimeout和removeEventListener在同一个完成边界运行，避免留下悬空等待。
// action在监听装好后才执行，源命中缓存时也不会先发事件后开始等。
// signal已取消时不执行action，防止旧任务再次启动视频load。
// 监听从传入的离屏video解绑，不去清除节目播放器或其他片段的监听。
// 事件等待不会绑定window级播放键，页面焦点和键盘路径不受辅助解码影响。
// 同步action异常仍使Promise拒绝，外层finally负责释放媒体源。
// video元素没有插入DOM，不会占用预览画布布局或抢夺焦点。
// 五秒是辅助单步等待上限，不是整个用户导入或节目播放的超时配置。
// 长GOP编码定位可能比短测试源慢，超时仅退回封面，不删除有效片段。
// 媒体元素的error事件不携带可直接展示的完整诊断，本层统一当辅助帧不可用处理。
// 取消是请求失效，不作为用户文件损坏的证据，不能写回asset.state=error。
// 错误与取消共用清理路径，但调用方仍通过signal区分是否应启动后续任务。
// 监听器捕获当前video，不根据document里第一个video猜测等待对象。
// 当节目和抽帧同时存在时，这条区别可防止节目seeked误唤醒辅助任务。
// 完成后移除abort监听，AbortController不会被旧回调链一直持有。
// 定时器只发出拒绝，真正停止源读取仍由paint的finally执行。
// 任何新等待都需要自己的监听，不能复用已经完成的Promise作为下一次定位证据。
function mediaEvent(video: HTMLVideoElement, name: string, signal: AbortSignal, action: () => void) {
  return new Promise<void>((resolve, reject) => {
    const finish = (failed: boolean) => {
      clearTimeout(timer);
      video.removeEventListener(name, ready);
      video.removeEventListener("error", failure);
      signal.removeEventListener("abort", failure);
      if (failed) reject(new Error("frame unavailable")); else resolve();
    };
    const ready = () => finish(false), failure = () => finish(true);
    const timer = setTimeout(failure, 5000);
    video.addEventListener(name, ready, { once: true });
    video.addEventListener("error", failure, { once: true });
    signal.addEventListener("abort", failure, { once: true });
    try { if (signal.aborted) failure(); else action(); } catch { failure(); }
  });
}

// 缓存键包含完整源URL和毫秒采样点，同名文件与不同源区间不会串图。
// 视频最后一刻可能恰好落在EOF外，向内留1ms，仍取本片段所覆盖的源时间。
// 新画布固定小尺寸，目标长片段上的高像素画布不进入共享缓存。
// 浏览器解码失败时拒绝此帧，不用封面复制出一条假的“连续帧”。
// 时间点由工程片段映射到源秒数后传入，不在这里重新推断片段速度。
// 源URL是缓存身份的一部分，不能仅凭文件名认定两个文件内容相同。
// sourceIn不同的同源实例自然查询不同帧，不会都回到文件第一帧。
// 缓存键保留三位小数，为小图去重复用，不写回剪辑数据。
// 读取命中缓存属于同步像素复用，不需要重新挂载视频节点。
// 真实源末尾是duration，工程为保留末帧可能多占不到一帧的时间。
// 抽帧以浏览器可读源区间夹限，不能请求不存在的EOF帧。
// 已经位于同一时间点时不等一个可能永远不会发出的seeked事件。
// 初始loadeddata已由paint等待，所以源零秒也有真实像素可画。
// 定位完成后再次看取消标记，快速切源时不能把旧帧写进新任务。
// 采样画布固定160×90，长时间线不会把原视频分辨率复制进共享缓存。
// 抽帧压缩只影响辅助预览，节目播放器仍读取真实原视频分辨率。
// 2D上下文可用时直接绘制媒体帧，不先把视频编码成另一份文件。
// 不使用toDataURL，所以不会为每格反复创建Base64长字符串。
// 不创建objectURL，因此缓存淘汰不需要维护一份容易漏掉的URL撤销表。
// 画布的像素容量上限可以估算，但浏览器对象与解码器开销另计。
// 先插入再淘汰保证新帧可供当前任务立即绘制，不依赖旧键一定存在。
// 缓存返回的是只读用途的采样画布，调用方只drawImage，不向它继续写图。
// 片段自己的长画布与缓存小画布不同，缩放时清空前者不会破坏别的片段。
// 抽样使用源秒而非源帧编号，因为浏览器currentTime的接口单位就是秒。
// 源帧率可能为非整数，不能简单把时间乘一个四舍五入fps再当准确帧索引。
// 辅助展示不追求逐帧编码分析，剪辑边界仍保持项目整数帧的独立契约。
// 没有设置crossOrigin绕过本地协议规则，绘制权限沿用现有媒体源处理。
// 缓存小画布可能继承媒体来源的安全标记，但本功能不读取像素或导出它。
// 若后续要导出帧，必须重新验证来源权限，不能把当前drawImage可见当可读取证明。
// 缓存命中时不修改取出的画布尺寸，否则其他片段复用会得到已清空的图。
// 图像缓冲使用普通Canvas，减少额外ImageBitmap.close配对资源的复杂度。
// 固定小图会丢失细节，这是时间线缩略用途的明确取舍，不影响节目解码帧。
// 当前辅助图按16:9缓冲绘制，竖视频在带中仅作内容识别，不代表节目画面被拉伸。
// 源分辨率仍从metadata给节目contain适配，不能从辅助图160×90反推源尺寸。
// 如果未来要求保持缩略格原始比例，应改目标绘制布局，不改工程宽高或源元数据。
async function sample(video: HTMLVideoElement, source: string, time: number, signal: AbortSignal) {
  const key = `${source}|${time.toFixed(3)}`, cached = frames.get(key);
  if (cached) return cached;
  const target = Math.min(Math.max(0, video.duration - .001), Math.max(0, time));
  if (Math.abs(video.currentTime - target) > .0001) await mediaEvent(video, "seeked", signal, () => { video.currentTime = target; });
  if (signal.aborted) throw new Error("cancelled");
  const frame = document.createElement("canvas");
  frame.width = 160; frame.height = 90;
  frame.getContext("2d")?.drawImage(video, 0, 0, 160, 90);
  frames.set(key, frame);
  if (frames.size > 64) frames.delete(frames.keys().next().value ?? "");
  return frame;
}

// 每格按照当前片段的源时间采样，不按标题或封面推算画面。
// sourceIn与speed共同映射项目时间，修剪和倍速后缩略带仍对应实际内容。
// 最多48格约束一次任务的工作量，缩小时同步减少采样而非继续解码隐藏大图。
// finally无论成功、失败还是取消都卸载源，离屏视频不能在后台继续播放。
// 一条任务从加载到释放只拥有一个离屏video，采样循环不会每格新建播放器。
// muted设置在源加载之前，辅助解码不允许把用户音轨意外播放出来。
// preload表示浏览器可以预读，不代表代码把完整源文件装入JS内存。
// 所有定位操作串行等待，不能同时对同一video发几十个currentTime写入。
// 帧数根据片段屏幕宽度决定，宽度越小抽样点越少。
// 最大48格是每条任务的预算，未声称逐一解码视频中的每一个源帧。
// 每格锚定源时间网格，修剪只移走左侧格子，不把剩余缩略图重新均分拉伸。
// 跨度由sourceIn之后实际覆盖内容定义，与素材总长不是同一个值。
// 2倍速的源跨度不变，但占用工程长度更短，画带随片段一起收窄。
// 格子正常64px，极宽片段在48格预算内增加格宽，最长画布仍4096px。
// 目标画布高度40缓冲像素，匹配正式中间帧槽，不覆盖底部真实声音。
// 画布最长4096像素，超宽片段会伸展有限缓冲，而非无限分配显存。
// 辅助帧拉伸并不改变源视频宽高或节目画布的contain适配尺寸。
// 只有全部格子成功才设置ready标记，中途失败不能谎称整条带已完成。
// 没有ready时外壳保留单封面回退，缺帧不会让整片段不能选择或修剪。
// 取消会在下一格开始前退出，正在等待的媒体事件则由signal立即结束。
// finally覆盖加载失败、单格定位失败、取消和正常结束四种路径。
// removeAttribute加load用于停止并释放该离屏媒体资源，不删除磁盘上的文件。
// video从不play，抽帧依赖定位后解码，不用假播放进度来猜画面。
// 串行队列只保护辅助抽帧，正式节目主播放器始终可以独立播放和定位。
// 单任务采样过程中源video没有声音输出，默认静音也不等于真实音频试听通过。
// 抽样任务和节目播放器各有媒体节点，因此抽帧seek不会直接跳动节目当前帧。
// 二者仍共享机器解码资源，串行预算只能限制辅助负担，不能承诺所有机器零卡顿。
// 这里没有向GPU上传无限长纹理，长片段目标缓冲被4096宽度限制。
// HTML画布CSS伸展只是概览，最大宽限制意味着极端放大时图像可能不够锐利。
// 用户可以据此定位内容，但不能用缩略格数判断视频总源帧数。
// 片段非常窄时仍保留至少一格，避免count为零产生除零或空循环假成功。
// 最后一格的源时间小于span终点，避免每次都抽到工程占位之外的源末尾。
// 相邻格可能因源帧率较低而落到同一实际帧，这是合法采样而非伪造重复封面。
// 只有ready标记控制封面回退可见性，错误不会产生一个可以点击的假重试成功按钮。
// 画布节点本身由React卸载，资源finally不尝试删除别的片段DOM。
// 即使队列被新的请求替换，旧Promise的finally仍会执行，不能提前遗失媒体引用。
async function paint(canvas: HTMLCanvasElement, source: string, sourceIn: number, span: number, signal: AbortSignal) {
  const video = document.createElement("video");
  video.muted = true; video.preload = "auto";
  try {
    await mediaEvent(video, "loadeddata", signal, () => { video.src = source; video.load(); });
    // 源秒与像素的换算像固定格距的胶卷尺：从当前入点左边最近的格子开始画。
    // 入点落在一格中间时x为负，由canvas自然裁掉左边，不能把该格挤窄重排。
    // 前后修剪后span与可见宽度同时变化，源时间网格的单位比例仍保持一致。
    // 仅缩放视口才改变格子覆盖的秒数，整个片段平移不会重新取另一组画面。
    // 额外取首尾相交格覆盖边缘，最多49张，与原有界串行解码/缓存共用。
    // 例：64px覆盖一秒、入点0.5秒时，第一格从x=-32开始，留下右半格。
    // 左边缘再向右裁0.25秒，这格会继续左移16px，而不是把整条视频重新均分。
    // 右边缘恢复内容时沿相同格距增加后续图，之前已可见的帧位置不会因均分而改变。
    // step使用源跨度除以像素宽，倍速导致工程宽变化时仍能对应正确源秒。
    // 源时间网格从零点锚定，不从每次修剪的新入点重新开始编号。
    // first可落在可见区之前一格，drawImage的负x由画布裁切，不需要额外DOM遮罩。
    // 多取一格覆盖不整除的右边缘，避免最后一小截保留黑色空洞。
    // 缓冲宽超过正常密度时tile增大，采样数量预算仍有界。
    // 画布上连续展示的是按时间抽样的缩略帧，不声称解码并常驻视频全部源帧。
    // 极大缩放下缓冲4096上限仍存在，细节清晰度边界与无限帧缓存不同。
    const tile = Math.max(64, canvas.width / 48), step = span / canvas.width * tile;
    const first = Math.floor(sourceIn / step), count = Math.ceil(canvas.width / tile) + 1;
    for (let index = 0; index < count; index += 1) {
      if (signal.aborted) return;
      const time = (first + index) * step, x = (time - sourceIn) / span * canvas.width;
      const frame = await sample(video, source, time, signal);
      canvas.getContext("2d")?.drawImage(frame, x, 0, Math.ceil(tile), canvas.height);
    }
    canvas.dataset.filmstripReady = "true";
  } finally { video.pause(); video.removeAttribute("src"); video.load(); }
}

// ResizeObserver读取片段真实宽度，Ctrl滚轮、滑杆、容器变化都走同一展示入口。
// 短暂停顿后才采样，连续滚轮会取消旧任务；确认片段时间本身从不被这里修改。
// 只观察可见区域附近的片段，横滚到远处才解码，不为屏外工程预先解码全部素材。
// 画布采样与节目媒体分离，逐帧定位不会被缩略图seek拖慢。
// 错误由本地catch收口并保留空带/已有封面，不把辅助缩略图失败标为素材导入失败。
// 卸载时清定时器、观察器和请求；队列任务也先检查取消标记才启动解码。
// 这个展示组件的输入是源、入点与源跨度，不持有工程写入回调。
// 片段从V1挪到V2但源区间不变时，不需要重新抽取相同画面。
// 父层把跨度舍入到微秒，消除浮点平移导致的无意义重复抽样。
// 真正修剪或改变源跨度会触发新的effect，取消旧任务后重新绘制。
// 窗口变化只触发本组件ResizeObserver，不修改项目宽高与片段时间。
// IntersectionObserver以真实裁切可见性判断，横向滚动后新进入视区才开始。
// 可见性退出同样取消当前任务，避免屏外片段继续抢占解码队列。
// 延后120ms用于合并连续尺寸变化，不作为视频帧准备完成的证据。
// 每次schedule先清上一个计时器，再取消旧signal，不能同时保留两份采样意图。
// 新signal局部捕获给本次任务，后来的重排不会把旧任务取消标记替换掉。
// 定时器触发时重新读取真实尺寸，不能沿用缩放开始时已经失效的旧矩形。
// width赋值会清除画布像素，paint随后按新缓冲宽度绘制完整帧带。
// Promise链末端catch是辅助展示的失败边界，不向素材列表写错误状态。
// 这与probeVideoFile失败不同：源元数据可用时，辅助图失败不能清空已有素材。
// 组件卸载清理两类Observer，返回页面不会再被旧节点尺寸通知唤醒。
// StrictMode下users增减配对，取消过的旧任务不能迟到追加缓存。
// 缓存清理只在最后使用者离开时执行，卸载一个片段不会让其他片段失去缓存。
// Canvas设置aria-hidden，读屏信息仍来自片段壳的真实文件名与修剪滑块。
// Canvas不接收指针，左右热区和主体移动仍由原外壳处理。
// 缺少sourceUrl时不创建任何后台任务，静态样板继续用自己的封面资源。
// Observer只订阅当前canvas，不监听整个应用每一张图片尺寸。
// 父层主题变化不会改源URL或span，通常无需重新解码相同内容。
// 素材封面补齐也不会改变sourceUrl，因此辅助帧缓存不依赖封面是否存在。
// 裁剪候选宽度变化可能短暂触发抽样意图，连续手势会由120ms合并避免每像素开任务。
// 确认后的入点变化则明确生成新的时间采样，不继续展示旧入点的完整帧带。
// 滚动可见性改变只决定辅助工作，不取消片段正在进行的主体拖放。
// 没有给canvas设置tabIndex，新增帧带不会让完整键盘路径多出几十个焦点站点。
// Canvas的aria-hidden不隐藏父片段，文件名、选中状态和修剪值仍可访问。
// ref在effect中读取，静态预渲染不会访问document或创建媒体元素。
// 组件需要use client仅因DOM与Observer，不代表允许渲染层导入Node模块。
// 清理不删除本地源文件，也不清空素材面板已经探测成功的元数据。
// 辅助预览没有持久化结构，因此离开页面不会额外生成一个缓存JSON文件。
export function VideoFilmstrip({ asset, sourceIn = 0, span }: { asset: EditorMediaAsset; sourceIn?: number; span: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas || !asset.sourceUrl) return;
    users += 1;
    let active = new AbortController(), timer: ReturnType<typeof setTimeout>, visible = false;
    const schedule = () => {
      clearTimeout(timer); active.abort(); active = new AbortController();
      const signal = active.signal;
      if (!visible) return;
      timer = setTimeout(() => {
        // 改画布尺寸会清空像素，先撤销旧就绪标记；重采样失败时才能重新露出封面。
        // 这像擦掉旧底片的“已冲印”章，不能让空白新底片沿用上一次成功状态。
        delete canvas.dataset.filmstripReady;
        // 像素缓冲与40px帧槽一致，标题和音频不进入采样画布。
        // 限宽仍4096，极端时间线缩放也不创建按源帧总数增长的纹理。
        // 缓冲大小只影响概览清晰度，不修改实际视频或节目画布分辨率。
        canvas.width = Math.max(1, Math.min(4096, Math.round(canvas.getBoundingClientRect().width))); canvas.height = 40;
        queue = queue.catch(() => {}).then(async () => { if (!signal.aborted) await paint(canvas, asset.sourceUrl ?? "", sourceIn, span, signal); }).catch(() => {});
      }, 120);
    };
    const resize = new ResizeObserver(schedule), intersection = new IntersectionObserver(entries => { visible = entries[0]?.isIntersecting ?? false; schedule(); });
    resize.observe(canvas); intersection.observe(canvas);
    return () => { active.abort(); clearTimeout(timer); resize.disconnect(); intersection.disconnect(); users -= 1; if (!users) frames.clear(); };
  }, [asset.sourceUrl, sourceIn, span]);
  // 帧带源区间与声音槽共用输入，修剪候选时两者同步，不改变节目时钟。
  // 数据标记供回归读取，不把请求状态放进正式工程或源元数据。
  // canvas不接收指针，边缘光标和修剪仍由共享片段壳处理。
  return <canvas ref={ref} aria-hidden="true" data-video-filmstrip data-filmstrip-source-in={sourceIn} data-filmstrip-span={span} className={styles.clipFilmstrip} />;
}

